Schema Design with TypeScript (Apollo Server) import { ApolloServer } from '@apollo/server';
import { startStandaloneServer } from '@apollo/server/standalone';
import { GraphQLError } from 'graphql';

const typeDefs = `#graphql
  type Query {
    user(id: ID!): User
    users(filter: UserFilter, pagination: PaginationInput): UserConnection!
    order(id: ID!): Order
  }

  type Mutation {
    createUser(input: CreateUserInput!): CreateUserPayload!
    updateUser(id: ID!, input: UpdateUserInput!): UpdateUserPayload!
    createOrder(input: CreateOrderInput!): CreateOrderPayload!
  }

  type Subscription {
    orderStatusChanged(orderId: ID!): OrderStatusEvent!
  }

  # Relay-style connection for cursor pagination
  type UserConnection {
    edges: [UserEdge!]!
    pageInfo: PageInfo!
    totalCount: Int!
  }

  type UserEdge {
    node: User!
    cursor: String!
  }

  type PageInfo {
    hasNextPage: Boolean!
    hasPreviousPage: Boolean!
    startCursor: String
    endCursor: String
  }

  type User {
    id: ID!
    email: String!
    name: String!
    role: UserRole!
    orders(first: Int = 10, after: String): OrderConnection!
    createdAt: DateTime!
    updatedAt: DateTime!
  }

  type Order {
    id: ID!
    customer: User!
    items: [OrderItem!]!
    status: OrderStatus!
    total: Money!
    createdAt: DateTime!
  }

  type OrderItem {
    product: Product!
    quantity: Int!
    unitPrice: Money!
  }

  type Money {
    amount: Int!       # Cents to avoid floating point
    currency: String!  # ISO 4217
  }

  # Input types for mutations
  input CreateUserInput {
    email: String!
    name: String!
    role: UserRole = CUSTOMER
  }

  input CreateOrderInput {
    customerId: ID!
    items: [OrderItemInput!]!
    idempotencyKey: String!
  }

  input OrderItemInput {
    productId: ID!
    quantity: Int!
  }

  # Mutation payloads follow a consistent pattern
  type CreateUserPayload {
    user: User
    errors: [UserError!]!
  }

  type UserError {
    field: String
    message: String!
    code: ErrorCode!
  }

  enum UserRole { ADMIN CUSTOMER SELLER }
  enum OrderStatus { PENDING CONFIRMED SHIPPED DELIVERED CANCELLED }
  enum ErrorCode { VALIDATION_ERROR NOT_FOUND CONFLICT UNAUTHORIZED }

  scalar DateTime

  input UserFilter {
    role: UserRole
    createdAfter: DateTime
    search: String
  }

  input PaginationInput {
    first: Int = 20
    after: String
  }
`;

Resolvers with DataLoader for N+1 Prevention import DataLoader from 'dataloader';
import { Resolvers } from './generated/types';

// DataLoader factory — create new loaders per request to avoid cross-request caching
function createLoaders(db: Database) {
  return {
    userLoader: new DataLoader<string, User>(async (ids) => {
      const users = await db.users.findByIds([...ids]);
      // DataLoader requires results in same order as input IDs
      const userMap = new Map(users.map(u => [u.id, u]));
      return ids.map(id => userMap.get(id) || new Error(`User ${id} not found`));
    }),

    ordersByUserLoader: new DataLoader<string, Order[]>(async (userIds) => {
      const orders = await db.orders.findByCustomerIds([...userIds]);
      const grouped = new Map<string, Order[]>();
      orders.forEach(order => {
        const existing = grouped.get(order.customerId) || [];
        existing.push(order);
        grouped.set(order.customerId, existing);
      });
      return userIds.map(id => grouped.get(id) || []);
    }),

    productLoader: new DataLoader<string, Product>(async (ids) => {
      const products = await db.products.findByIds([...ids]);
      const productMap = new Map(products.map(p => [p.id, p]));
      return ids.map(id => productMap.get(id) || new Error(`Product ${id} not found`));
    }),
  };
}

const resolvers: Resolvers = {
  Query: {
    user: async (_, { id }, { loaders }) => {
      return loaders.userLoader.load(id);
    },

    users: async (_, { filter, pagination }, { db }) => {
      const { first = 20, after } = pagination || {};
      const cursor = after ? decodeCursor(after) : null;

      const { items, hasMore, totalCount } = await db.users.findPaginated({
        filter,
        limit: first + 1, // Fetch one extra to determine hasNextPage
        afterId: cursor?.id,
      });

      const edges = items.slice(0, first).map(user => ({
        node: user,
        cursor: encodeCursor({ id: user.id }),
      }));

      return {
        edges,
        pageInfo: {
          hasNextPage: items.length > first,
          hasPreviousPage: !!after,
          startCursor: edges[0]?.cursor || null,
          endCursor: edges[edges.length - 1]?.cursor || null,
        },
        totalCount,
      };
    },
  },

  Mutation: {
    createOrder: async (_, { input }, { db, loaders, currentUser }) => {
      // Authorization check
      if (!currentUser) {
        return {
          order: null,
          errors: [{ message: 'Authentication required', code: 'UNAUTHORIZED' }],
        };
      }

      // Idempotency check
      const existing = await db.orders.findByIdempotencyKey(input.idempotencyKey);
      if (existing) {
        return { order: existing, errors: [] };
      }

      // Validate products exist and have sufficient stock
      const products = await Promise.all(
        input.items.map(item => loaders.productLoader.load(item.productId))
      );

      const errors = [];
      for (let i = 0; i < input.items.length; i++) {
        const product = products[i];
        if (product instanceof Error) {
          errors.push({
            field: `items[${i}].productId`,
            message: `Product not found`,
            code: 'NOT_FOUND' as const,
          });
        }
      }

      if (errors.length > 0) {
        return { order: null, errors };
      }

      const order = await db.orders.create({
        customerId: input.customerId,
        items: input.items,
        idempotencyKey: input.idempotencyKey,
      });

      return { order, errors: [] };
    },
  },

  // Field-level resolvers for relationships
  User: {
    orders: async (user, { first, after }, { loaders }) => {
      // DataLoader batches these calls across all users in the query
      const allOrders = await loaders.ordersByUserLoader.load(user.id);
      // Apply pagination on the loaded results
      return paginateArray(allOrders, { first, after });
    },
  },

  Order: {
    customer: async (order, _, { loaders }) => {
      return loaders.userLoader.load(order.customerId);
    },
  },

  OrderItem: {
    product: async (item, _, { loaders }) => {
      return loaders.productLoader.load(item.productId);
    },
  },
};

Query Complexity and Depth Limiting import { ApolloServer } from '@apollo/server';
import { createComplexityLimitRule } from 'graphql-validation-complexity';
import depthLimit from 'graphql-depth-limit';

// Custom complexity calculation
const complexityRule = createComplexityLimitRule(1000, {
  scalarCost: 1,
  objectCost: 2,
  listFactor: 10, // Lists multiply child complexity
  introspectionListFactor: 2,
  formatErrorMessage: (cost: number) =>
    `Query complexity ${cost} exceeds maximum allowed complexity of 1000`,
});

const server = new ApolloServer({
  typeDefs,
  resolvers,
  validationRules: [
    depthLimit(7), // Max query depth
    complexityRule,
  ],
  plugins: [
    // Query cost logging
    {
      async requestDidStart() {
        const start = Date.now();
        return {
          async willSendResponse({ response, contextValue }) {
            const duration = Date.now() - start;
            contextValue.logger.info('GraphQL request completed', {
              duration,
              operationName: contextValue.operationName,
              complexity: contextValue.queryComplexity,
            });
          },
          async didEncounterErrors({ errors, contextValue }) {
            contextValue.logger.error('GraphQL errors', { errors });
          },
        };
      },
    },
    // Persisted queries for production
    {
      async requestDidStart({ request }) {
        if (process.env.NODE_ENV === 'production' && !request.extensions?.persistedQuery) {
          throw new GraphQLError('Only persisted queries allowed in production', {
            extensions: { code: 'PERSISTED_QUERY_REQUIRED' },
          });
        }
      },
    },
  ],
});

Apollo Federation (Subgraph) import { buildSubgraphSchema } from '@apollo/subgraph';
import { ApolloServer } from '@apollo/server';
import gql from 'graphql-tag';

// Users subgraph — owns User entity
const typeDefs = gql`
  extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key", "@shareable", "@external"])

  type Query {
    me: User
    user(id: ID!): User
  }

  type User @key(fields: "id") {
    id: ID!
    email: String!
    name: String!
    role: UserRole!
    createdAt: DateTime!
  }

  enum UserRole { ADMIN CUSTOMER SELLER }
  scalar DateTime
`;

const resolvers = {
  Query: {
    me: (_, __, { currentUser }) => currentUser,
    user: (_, { id }, { dataSources }) => dataSources.users.findById(id),
  },
  User: {
    // Federation resolver — called when other subgraphs reference User
    __resolveReference: (reference, { dataSources }) => {
      return dataSources.users.findById(reference.id);
    },
  },
};

// Orders subgraph — extends User with orders field
const ordersTypeDefs = gql`
  extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key", "@external"])

  type Query {
    order(id: ID!): Order
  }

  type Order @key(fields: "id") {
    id: ID!
    customer: User!
    items: [OrderItem!]!
    status: OrderStatus!
    total: Int!
  }

  # Extend User from users subgraph
  type User @key(fields: "id") {
    id: ID! @external
    orders(first: Int = 10): [Order!]!
  }

  type OrderItem {
    productId: ID!
    quantity: Int!
    unitPrice: Int!
  }

  enum OrderStatus { PENDING CONFIRMED SHIPPED DELIVERED }
`;

const ordersResolvers = {
  User: {
    orders: (user, { first }, { dataSources }) => {
      return dataSources.orders.findByCustomerId(user.id, { limit: first });
    },
  },
  Order: {
    customer: (order) => ({ __typename: 'User', id: order.customerId }),
  },
};

Protocol Buffer Service Definition syntax = "proto3";

package ecommerce.orders.v1;

option java_package = "com.example.ecommerce.orders.v1";
option java_multiple_files = true;
option go_package = "github.com/example/ecommerce/orders/v1;ordersv1";

import "google/protobuf/timestamp.proto";
import "google/protobuf/field_mask.proto";

// Order service with all four RPC patterns
service OrderService {
  // Unary: create a single order
  rpc CreateOrder(CreateOrderRequest) returns (Order);

  // Unary: get order by ID
  rpc GetOrder(GetOrderRequest) returns (Order);

  // Server streaming: watch order status changes in real-time
  rpc WatchOrderStatus(WatchOrderStatusRequest) returns (stream OrderStatusEvent);

  // Client streaming: batch upload order items
  rpc BatchAddItems(stream AddItemRequest) returns (BatchAddItemsResponse);

  // Bidirectional streaming: real-time order negotiation
  rpc NegotiateOrder(stream NegotiationMessage) returns (stream NegotiationMessage);
}

message Order {
  string order_id = 1;
  string customer_id = 2;
  repeated OrderItem items = 3;
  OrderStatus status = 4;
  Money total = 5;
  google.protobuf.Timestamp created_at = 6;
  google.protobuf.Timestamp updated_at = 7;
  map<string, string> metadata = 8;
}

message OrderItem {
  string sku = 1;
  string name = 2;
  int32 quantity = 3;
  Money unit_price = 4;
}

message Money {
  string currency_code = 1;  // ISO 4217
  int64 units = 2;           // Whole units (e.g., dollars)
  int32 nanos = 3;           // Nano units (10^-9)
}

enum OrderStatus {
  ORDER_STATUS_UNSPECIFIED = 0;
  ORDER_STATUS_PENDING = 1;
  ORDER_STATUS_CONFIRMED = 2;
  ORDER_STATUS_SHIPPED = 3;
  ORDER_STATUS_DELIVERED = 4;
  ORDER_STATUS_CANCELLED = 5;
}

message CreateOrderRequest {
  string customer_id = 1;
  repeated OrderItem items = 2;
  map<string, string> metadata = 3;
  string idempotency_key = 4;  // Client-generated for safe retries
}

message GetOrderRequest {
  string order_id = 1;
  google.protobuf.FieldMask field_mask = 2;  // Partial response
}

message WatchOrderStatusRequest {
  string order_id = 1;
}

message OrderStatusEvent {
  string order_id = 1;
  OrderStatus previous_status = 2;
  OrderStatus new_status = 3;
  google.protobuf.Timestamp timestamp = 4;
  string reason = 5;
}

Go gRPC Server with Interceptors package main

import (
    "context"
    "log"
    "net"
    "time"

    "google.golang.org/grpc"
    "google.golang.org/grpc/codes"
    "google.golang.org/grpc/metadata"
    "google.golang.org/grpc/status"
    "google.golang.org/grpc/keepalive"

    pb "github.com/example/ecommerce/orders/v1"
)

type orderServer struct {
    pb.UnimplementedOrderServiceServer
    store OrderStore
}

func (s *orderServer) CreateOrder(ctx context.Context, req *pb.CreateOrderRequest) (*pb.Order, error) {
    // Check deadline propagation
    if deadline, ok := ctx.Deadline(); ok {
        remaining := time.Until(deadline)
        if remaining < 100*time.Millisecond {
            return nil, status.Error(codes.DeadlineExceeded, "insufficient time remaining")
        }
    }

    // Idempotency check
    if req.IdempotencyKey != "" {
        if existing, err := s.store.GetByIdempotencyKey(ctx, req.IdempotencyKey); err == nil {
            return existing, nil
        }
    }

    order, err := s.store.Create(ctx, req)
    if err != nil {
        return nil, status.Errorf(codes.Internal, "failed to create order: %v", err)
    }

    // Set response metadata
    header := metadata.Pairs("x-request-id", extractRequestID(ctx))
    grpc.SetHeader(ctx, header)

    return order, nil
}

func (s *orderServer) WatchOrderStatus(req *pb.WatchOrderStatusRequest, stream pb.OrderService_WatchOrderStatusServer) error {
    ctx := stream.Context()
    events := s.store.Subscribe(req.OrderId)
    defer s.store.Unsubscribe(req.OrderId, events)

    for {
        select {
        case <-ctx.Done():
            return status.Error(codes.Cancelled, "client disconnected")
        case event, ok := <-events:
            if !ok {
                return nil // Channel closed, order finalized
            }
            if err := stream.Send(event); err != nil {
                return status.Errorf(codes.Internal, "failed to send event: %v", err)
            }
        }
    }
}

// Unary interceptor for logging and metrics
func loggingInterceptor(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
    start := time.Now()
    resp, err := handler(ctx, req)
    duration := time.Since(start)

    code := codes.OK
    if err != nil {
        code = status.Code(err)
    }

    log.Printf("method=%s duration=%v code=%s", info.FullMethod, duration, code)
    recordMetrics(info.FullMethod, code, duration)

    return resp, err
}

// Auth interceptor
func authInterceptor(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
    md, ok := metadata.FromIncomingContext(ctx)
    if !ok {
        return nil, status.Error(codes.Unauthenticated, "missing metadata")
    }

    tokens := md.Get("authorization")
    if len(tokens) == 0 {
        return nil, status.Error(codes.Unauthenticated, "missing authorization token")
    }

    claims, err := validateToken(tokens[0])
    if err != nil {
        return nil, status.Errorf(codes.Unauthenticated, "invalid token: %v", err)
    }

    // Inject claims into context for downstream use
    ctx = context.WithValue(ctx, claimsKey{}, claims)
    return handler(ctx, req)
}

func main() {
    lis, err := net.Listen("tcp", ":50051")
    if err != nil {
        log.Fatalf("failed to listen: %v", err)
    }

    server := grpc.NewServer(
        grpc.ChainUnaryInterceptor(
            loggingInterceptor,
            authInterceptor,
        ),
        grpc.KeepaliveParams(keepalive.ServerParameters{
            MaxConnectionIdle: 5 * time.Minute,
            Time:             1 * time.Minute,
            Timeout:          20 * time.Second,
        }),
        grpc.MaxRecvMsgSize(4 * 1024 * 1024), // 4MB max message
    )

    pb.RegisterOrderServiceServer(server, &orderServer{store: NewOrderStore()})

    log.Printf("gRPC server listening on :50051")
    if err := server.Serve(lis); err != nil {
        log.Fatalf("failed to serve: %v", err)
    }
}

Java gRPC Client with Retry and Load Balancing import io.grpc.*;
import io.grpc.stub.StreamObserver;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.CountDownLatch;

public class OrderClient {

    private final OrderServiceGrpc.OrderServiceBlockingStub blockingStub;
    private final OrderServiceGrpc.OrderServiceStub asyncStub;
    private final ManagedChannel channel;

    public OrderClient(String target) {
        // Client-side load balancing with round-robin
        this.channel = ManagedChannelBuilder.forTarget(target)
            .defaultLoadBalancingPolicy("round_robin")
            .enableRetry()
            .maxRetryAttempts(3)
            .keepAliveTime(30, TimeUnit.SECONDS)
            .keepAliveTimeout(10, TimeUnit.SECONDS)
            .build();

        this.blockingStub = OrderServiceGrpc.newBlockingStub(channel)
            .withDeadlineAfter(5, TimeUnit.SECONDS)
            .withCompression("gzip");

        this.asyncStub = OrderServiceGrpc.newStub(channel);
    }

    public Order createOrder(CreateOrderRequest request) {
        try {
            return blockingStub
                .withDeadlineAfter(3, TimeUnit.SECONDS)
                .createOrder(request);
        } catch (StatusRuntimeException e) {
            switch (e.getStatus().getCode()) {
                case DEADLINE_EXCEEDED:
                    throw new ServiceTimeoutException("Order creation timed out", e);
                case ALREADY_EXISTS:
                    // Idempotent retry hit existing order
                    return getOrder(request.getIdempotencyKey());
                case UNAVAILABLE:
                    throw new ServiceUnavailableException("Order service unavailable", e);
                default:
                    throw new ServiceException("Order creation failed: " + e.getStatus(), e);
            }
        }
    }

    public void watchOrderStatus(String orderId, OrderStatusListener listener) {
        WatchOrderStatusRequest request = WatchOrderStatusRequest.newBuilder()
            .setOrderId(orderId)
            .build();

        asyncStub.watchOrderStatus(request, new StreamObserver<OrderStatusEvent>() {
            @Override
            public void onNext(OrderStatusEvent event) {
                listener.onStatusChange(event);
            }

            @Override
            public void onError(Throwable t) {
                Status status = Status.fromThrowable(t);
                if (status.getCode() == Status.Code.UNAVAILABLE) {
                    // Reconnect with exponential backoff
                    scheduleReconnect(orderId, listener);
                } else {
                    listener.onError(t);
                }
            }

            @Override
            public void onCompleted() {
                listener.onComplete();
            }
        });
    }

    // Bidirectional streaming example
    public void negotiateOrder(List<NegotiationMessage> proposals) throws InterruptedException {
        CountDownLatch finishLatch = new CountDownLatch(1);

        StreamObserver<NegotiationMessage> requestObserver = asyncStub.negotiateOrder(
            new StreamObserver<NegotiationMessage>() {
                @Override
                public void onNext(NegotiationMessage response) {
                    System.out.println("Server response: " + response.getMessage());
                }

                @Override
                public void onError(Throwable t) {
                    finishLatch.countDown();
                }

                @Override
                public void onCompleted() {
                    finishLatch.countDown();
                }
            });

        for (NegotiationMessage proposal : proposals) {
            requestObserver.onNext(proposal);
            Thread.sleep(500); // Simulate thinking time
        }
        requestObserver.onCompleted();

        finishLatch.await(30, TimeUnit.SECONDS);
    }

    public void shutdown() throws InterruptedException {
        channel.shutdown().awaitTermination(5, TimeUnit.SECONDS);
    }
}

Resource Design with Spring Boot @RestController
@RequestMapping("/api/v1/users")
@Validated
public class UserController {

    private final UserService userService;

    @GetMapping
    public ResponseEntity<PagedResponse<UserDto>> listUsers(
            @RequestParam(defaultValue = "0") @Min(0) int page,
            @RequestParam(defaultValue = "20") @Min(1) @Max(100) int size,
            @RequestParam(required = false) String status,
            @RequestParam(defaultValue = "createdAt") String sortBy,
            @RequestParam(defaultValue = "desc") String sortDir) {

        Pageable pageable = PageRequest.of(page, size,
            Sort.by(Sort.Direction.fromString(sortDir), sortBy));

        Page<UserDto> users = userService.findAll(status, pageable);

        PagedResponse<UserDto> response = PagedResponse.<UserDto>builder()
            .data(users.getContent())
            .page(users.getNumber())
            .size(users.getSize())
            .totalElements(users.getTotalElements())
            .totalPages(users.getTotalPages())
            .hasNext(users.hasNext())
            .build();

        return ResponseEntity.ok()
            .cacheControl(CacheControl.maxAge(30, TimeUnit.SECONDS))
            .body(response);
    }

    @GetMapping("/{userId}")
    public ResponseEntity<UserDto> getUser(
            @PathVariable @UUID String userId,
            HttpServletRequest request) {

        UserDto user = userService.findById(userId);

        // ETag for conditional requests
        String etag = "\"" + user.getVersion() + "\"";
        if (etag.equals(request.getHeader("If-None-Match"))) {
            return ResponseEntity.status(HttpStatus.NOT_MODIFIED).build();
        }

        return ResponseEntity.ok()
            .eTag(etag)
            .cacheControl(CacheControl.maxAge(60, TimeUnit.SECONDS))
            .body(user);
    }

    @PostMapping
    public ResponseEntity<UserDto> createUser(
            @Valid @RequestBody CreateUserRequest request,
            UriComponentsBuilder uriBuilder) {

        UserDto created = userService.create(request);

        URI location = uriBuilder.path("/api/v1/users/{id}")
            .buildAndExpand(created.getId())
            .toUri();

        return ResponseEntity.created(location).body(created);
    }

    @PatchMapping("/{userId}")
    public ResponseEntity<UserDto> updateUser(
            @PathVariable @UUID String userId,
            @Valid @RequestBody UpdateUserRequest request,
            @RequestHeader("If-Match") String ifMatch) {

        // Optimistic concurrency control
        long expectedVersion = Long.parseLong(ifMatch.replace("\"", ""));
        UserDto updated = userService.update(userId, request, expectedVersion);

        return ResponseEntity.ok()
            .eTag("\"" + updated.getVersion() + "\"")
            .body(updated);
    }

    @DeleteMapping("/{userId}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void deleteUser(@PathVariable @UUID String userId) {
        userService.delete(userId);
    }
}

Standardized Error Response @RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ResourceNotFoundException.class)
    public ResponseEntity<ProblemDetail> handleNotFound(ResourceNotFoundException ex) {
        ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.NOT_FOUND);
        problem.setTitle("Resource Not Found");
        problem.setDetail(ex.getMessage());
        problem.setType(URI.create("https://api.example.com/errors/not-found"));
        problem.setProperty("resourceType", ex.getResourceType());
        problem.setProperty("resourceId", ex.getResourceId());
        problem.setProperty("timestamp", Instant.now());
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(problem);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ProblemDetail> handleValidation(MethodArgumentNotValidException ex) {
        ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
        problem.setTitle("Validation Failed");
        problem.setDetail("One or more fields failed validation");
        problem.setType(URI.create("https://api.example.com/errors/validation"));

        List<Map<String, String>> violations = ex.getBindingResult()
            .getFieldErrors().stream()
            .map(error -> Map.of(
                "field", error.getField(),
                "message", error.getDefaultMessage(),
                "rejectedValue", String.valueOf(error.getRejectedValue())
            ))
            .toList();

        problem.setProperty("violations", violations);
        return ResponseEntity.badRequest().body(problem);
    }

    @ExceptionHandler(OptimisticLockException.class)
    public ResponseEntity<ProblemDetail> handleConflict(OptimisticLockException ex) {
        ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.CONFLICT);
        problem.setTitle("Conflict");
        problem.setDetail("Resource was modified by another request. Fetch the latest version and retry.");
        problem.setType(URI.create("https://api.example.com/errors/conflict"));
        return ResponseEntity.status(HttpStatus.CONFLICT).body(problem);
    }

    @ExceptionHandler(RateLimitExceededException.class)
    public ResponseEntity<ProblemDetail> handleRateLimit(RateLimitExceededException ex) {
        ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.TOO_MANY_REQUESTS);
        problem.setTitle("Rate Limit Exceeded");
        problem.setDetail("You have exceeded the rate limit. Try again after the reset time.");
        problem.setProperty("retryAfter", ex.getRetryAfterSeconds());

        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
            .header("Retry-After", String.valueOf(ex.getRetryAfterSeconds()))
            .header("X-RateLimit-Limit", String.valueOf(ex.getLimit()))
            .header("X-RateLimit-Remaining", "0")
            .header("X-RateLimit-Reset", String.valueOf(ex.getResetTimestamp()))
            .body(problem);
    }
}

HATEOAS Implementation @RestController
@RequestMapping("/api/v1/orders")
public class OrderController {

    @GetMapping("/{orderId}")
    public EntityModel<OrderDto> getOrder(@PathVariable String orderId) {
        OrderDto order = orderService.findById(orderId);

        EntityModel<OrderDto> model = EntityModel.of(order);

        // Self link
        model.add(linkTo(methodOn(OrderController.class).getOrder(orderId)).withSelfRel());

        // Related resource links
        model.add(linkTo(methodOn(UserController.class)
            .getUser(order.getCustomerId(), null)).withRel("customer"));

        // State-dependent action links (HATEOAS drives available transitions)
        switch (order.getStatus()) {
            case PENDING:
                model.add(linkTo(methodOn(OrderController.class)
                    .confirmOrder(orderId)).withRel("confirm"));
                model.add(linkTo(methodOn(OrderController.class)
                    .cancelOrder(orderId)).withRel("cancel"));
                break;
            case CONFIRMED:
                model.add(linkTo(methodOn(OrderController.class)
                    .shipOrder(orderId, null)).withRel("ship"));
                model.add(linkTo(methodOn(OrderController.class)
                    .cancelOrder(orderId)).withRel("cancel"));
                break;
            case SHIPPED:
                model.add(linkTo(methodOn(OrderController.class)
                    .deliverOrder(orderId)).withRel("deliver"));
                break;
        }

        return model;
    }

    @GetMapping
    public CollectionModel<EntityModel<OrderDto>> listOrders(
            @RequestParam(defaultValue = "") String cursor,
            @RequestParam(defaultValue = "20") int limit) {

        CursorPage<OrderDto> page = orderService.findAll(cursor, limit);

        List<EntityModel<OrderDto>> orderModels = page.getItems().stream()
            .map(order -> EntityModel.of(order,
                linkTo(methodOn(OrderController.class)
                    .getOrder(order.getId())).withSelfRel()))
            .toList();

        CollectionModel<EntityModel<OrderDto>> collection =
            CollectionModel.of(orderModels);

        collection.add(linkTo(methodOn(OrderController.class)
            .listOrders("", limit)).withSelfRel());

        if (page.hasNext()) {
            collection.add(linkTo(methodOn(OrderController.class)
                .listOrders(page.getNextCursor(), limit)).withRel("next"));
        }

        return collection;
    }
}

