Saga Pattern with Orchestration // Saga definition with steps and compensations
public class OrderSaga {

    private final List<SagaStep> steps = new ArrayList<>();
    private final List<SagaStep> completedSteps = new ArrayList<>();
    private SagaStatus status = SagaStatus.STARTED;

    public void addStep(String name, Runnable action, Runnable compensation) {
        steps.add(new SagaStep(name, action, compensation));
    }

    public SagaResult execute() {
        for (SagaStep step : steps) {
            try {
                step.action().run();
                completedSteps.add(step);
            } catch (Exception e) {
                status = SagaStatus.COMPENSATING;
                compensate();
                status = SagaStatus.FAILED;
                return SagaResult.failure(step.name(), e);
            }
        }
        status = SagaStatus.COMPLETED;
        return SagaResult.success();
    }

    private void compensate() {
        // Execute compensations in reverse order
        ListIterator<SagaStep> iterator = completedSteps.listIterator(completedSteps.size());
        while (iterator.hasPrevious()) {
            SagaStep step = iterator.previous();
            try {
                step.compensation().run();
            } catch (Exception e) {
                log.error("Compensation failed for step: {}", step.name(), e);
                // Alert for manual intervention
                alertService.critical("Saga compensation failure", step.name(), e);
            }
        }
    }
}

// Choreography-based saga with event handlers
@Component
public class PaymentSagaParticipant {

    @KafkaListener(topics = "saga-commands", groupId = "payment-saga")
    public void handleCommand(SagaCommand command) {
        if (command instanceof ProcessPaymentCommand cmd) {
            try {
                PaymentResult result = paymentGateway.charge(cmd.amount(), cmd.paymentMethod());
                eventPublisher.publish("saga-events", cmd.sagaId(),
                    new PaymentProcessedEvent(cmd.sagaId(), result.transactionId()));
            } catch (PaymentDeclinedException e) {
                eventPublisher.publish("saga-events", cmd.sagaId(),
                    new PaymentFailedEvent(cmd.sagaId(), e.getReason()));
            }
        } else if (command instanceof RefundPaymentCommand cmd) {
            paymentGateway.refund(cmd.transactionId());
            eventPublisher.publish("saga-events", cmd.sagaId(),
                new PaymentRefundedEvent(cmd.sagaId(), cmd.transactionId()));
        }
    }
}

Choosing Between Kafka and RabbitMQ // Decision framework implementation
public class MessagingPlatformSelector {

    public MessagingPlatform recommend(WorkloadCharacteristics workload) {
        // Kafka strengths
        if (workload.requiresEventReplay()) return KAFKA;
        if (workload.throughputPerSecond() > 100_000) return KAFKA;
        if (workload.requiresEventSourcing()) return KAFKA;
        if (workload.hasMultipleIndependentConsumers()) return KAFKA;
        if (workload.requiresStreamProcessing()) return KAFKA;

        // RabbitMQ strengths
        if (workload.requiresComplexRouting()) return RABBITMQ;
        if (workload.requiresPriorityQueues()) return RABBITMQ;
        if (workload.requiresRequestReply()) return RABBITMQ;
        if (workload.requiresPerMessageTTL()) return RABBITMQ;
        if (workload.requiresMessageDeletionAfterConsumption()) return RABBITMQ;
        if (workload.throughputPerSecond() < 10_000) return RABBITMQ;

        // Default: Kafka for event-driven, RabbitMQ for task-driven
        return workload.isEventDriven() ? KAFKA : RABBITMQ;
    }
}

/*
 * Summary comparison:
 *
 * | Aspect              | Kafka                        | RabbitMQ                    |
 * |---------------------|------------------------------|-----------------------------|
 * | Model               | Distributed log              | Message broker              |
 * | Persistence         | Retained after consumption   | Deleted after ack           |
 * | Ordering            | Per-partition                | Per-queue (FIFO)            |
 * | Replay              | Yes (seek to any offset)     | No (consumed = gone)        |
 * | Routing             | Topic-based only             | Exchange types + bindings   |
 * | Throughput          | Millions/sec                 | Tens of thousands/sec       |
 * | Consumer model      | Pull (consumer polls)        | Push (broker delivers)      |
 * | Scaling             | Add partitions + consumers   | Add queues + consumers      |
 * | Use case            | Event streaming, CDC, logs   | Task queues, routing, RPC   |
 */

Configuring Assignment Strategies // Consumer configuration with cooperative sticky assignor (recommended)
Properties props = new Properties();
props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092,broker2:9092,broker3:9092");
props.put(ConsumerConfig.GROUP_ID_CONFIG, "order-processing-group");
props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, JsonDeserializer.class.getName());

// Use cooperative sticky assignor for incremental rebalancing
props.put(ConsumerConfig.PARTITION_ASSIGNMENT_STRATEGY_CONFIG,
    CooperativeStickyAssignor.class.getName());

// Important: with cooperative protocol, partitions are revoked incrementally
// The consumer will receive onPartitionsRevoked() only for partitions being moved
// Other partitions continue processing during the rebalance

KafkaConsumer<String, OrderEvent> consumer = new KafkaConsumer<>(props);

// Rebalance listener adapted for cooperative protocol
consumer.subscribe(List.of("order-events", "payment-events"), new ConsumerRebalanceListener() {
    @Override
    public void onPartitionsRevoked(Collection<TopicPartition> partitions) {
        // With cooperative: only called for partitions being moved away
        // Commit offsets for revoked partitions only
        Map<TopicPartition, OffsetAndMetadata> offsets = new HashMap<>();
        for (TopicPartition tp : partitions) {
            offsets.put(tp, new OffsetAndMetadata(currentOffsets.get(tp)));
        }
        consumer.commitSync(offsets);
        log.info("Revoked {} partitions: {}", partitions.size(), partitions);
    }

    @Override
    public void onPartitionsAssigned(Collection<TopicPartition> partitions) {
        // Initialize state for newly assigned partitions
        for (TopicPartition tp : partitions) {
            initializePartitionState(tp);
        }
        log.info("Assigned {} partitions: {}", partitions.size(), partitions);
    }

    @Override
    public void onPartitionsLost(Collection<TopicPartition> partitions) {
        // Called when partitions are lost without a clean revocation
        // (e.g., consumer exceeded session timeout)
        // State for these partitions may be stale — clean up without committing
        for (TopicPartition tp : partitions) {
            cleanupPartitionState(tp);
        }
        log.warn("Lost {} partitions unexpectedly: {}", partitions.size(), partitions);
    }
});

Implementing a Custom Rack-Aware Assignor public class RackAwareAssignor extends AbstractPartitionAssignor {

    @Override
    public String name() {
        return "rack-aware";
    }

    @Override
    public Map<String, List<TopicPartition>> assign(
            Map<String, Integer> partitionsPerTopic,
            Map<String, Subscription> subscriptions) {

        // Build consumer-to-rack mapping from subscription user data
        Map<String, String> consumerRacks = new HashMap<>();
        for (Map.Entry<String, Subscription> entry : subscriptions.entrySet()) {
            String consumerId = entry.getKey();
            String rack = extractRack(entry.getValue().userData());
            consumerRacks.put(consumerId, rack);
        }

        // Build partition-to-rack mapping (leader broker rack)
        Map<TopicPartition, String> partitionRacks = getPartitionLeaderRacks();

        // Assign partitions preferring same-rack consumers
        Map<String, List<TopicPartition>> assignment = new HashMap<>();
        subscriptions.keySet().forEach(c -> assignment.put(c, new ArrayList<>()));

        for (Map.Entry<String, Integer> topicEntry : partitionsPerTopic.entrySet()) {
            String topic = topicEntry.getKey();
            int numPartitions = topicEntry.getValue();

            for (int partition = 0; partition < numPartitions; partition++) {
                TopicPartition tp = new TopicPartition(topic, partition);
                String partitionRack = partitionRacks.getOrDefault(tp, "unknown");

                // Find consumers in the same rack
                List<String> sameRackConsumers = subscriptions.keySet().stream()
                    .filter(c -> subscriptions.get(c).topics().contains(topic))
                    .filter(c -> partitionRack.equals(consumerRacks.get(c)))
                    .collect(Collectors.toList());

                // Assign to least-loaded same-rack consumer, or least-loaded overall
                String target;
                if (!sameRackConsumers.isEmpty()) {
                    target = sameRackConsumers.stream()
                        .min(Comparator.comparingInt(c -> assignment.get(c).size()))
                        .orElseThrow();
                } else {
                    target = subscriptions.keySet().stream()
                        .filter(c -> subscriptions.get(c).topics().contains(topic))
                        .min(Comparator.comparingInt(c -> assignment.get(c).size()))
                        .orElseThrow();
                }
                assignment.get(target).add(tp);
            }
        }
        return assignment;
    }
}

