// Practical async patterns: retry with exponential backoff and circuit breaker
class CircuitBreaker {
  #state = 'closed'; // closed, open, half-open
  #failureCount = 0;
  #lastFailureTime = 0;
  #options;

  constructor(options = {}) {
    this.#options = {
      failureThreshold: options.failureThreshold ?? 5,
      resetTimeout: options.resetTimeout ?? 30000,
      halfOpenRequests: options.halfOpenRequests ?? 1,
    };
  }

  async execute(fn) {
    if (this.#state === 'open') {
      if (Date.now() - this.#lastFailureTime > this.#options.resetTimeout) {
        this.#state = 'half-open';
      } else {
        throw new Error('Circuit breaker is open');
      }
    }

    try {
      const result = await fn();
      this.#onSuccess();
      return result;
    } catch (error) {
      this.#onFailure();
      throw error;
    }
  }

  #onSuccess() {
    this.#failureCount = 0;
    this.#state = 'closed';
  }

  #onFailure() {
    this.#failureCount++;
    this.#lastFailureTime = Date.now();
    if (this.#failureCount >= this.#options.failureThreshold) {
      this.#state = 'open';
    }
  }

  get state() { return this.#state; }
}

async function fetchWithRetry(url, options = {}) {
  const {
    maxRetries = 3,
    baseDelay = 1000,
    maxDelay = 30000,
    signal,
    onRetry,
  } = options;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(url, { signal });
      if (!response.ok && response.status >= 500) {
        throw new Error(`Server error: ${response.status}`);
      }
      return response;
    } catch (error) {
      if (error.name === 'AbortError') throw error; // Don't retry cancellations
      if (attempt === maxRetries) throw error;

      const delay = Math.min(baseDelay * 2 ** attempt, maxDelay);
      const jitter = delay * (0.5 + Math.random() * 0.5);

      onRetry?.({ attempt: attempt + 1, delay: jitter, error });

      await new Promise((resolve, reject) => {
        const timeout = setTimeout(resolve, jitter);
        signal?.addEventListener('abort', () => {
          clearTimeout(timeout);
          reject(new DOMException('Aborted', 'AbortError'));
        });
      });
    }
  }
} // Promise combinators for concurrent operations
