// WeakMap for private data and metadata without memory leaks
const metadata = new WeakMap();

class Component {
  constructor(name) {
    this.name = name;
    metadata.set(this, {
      renderCount: 0,
      lastRendered: null,
      mountedAt: Date.now(),
    });
