const Validatable = {
  validate() {
    const errors = [];
    if (this._validationRules) {
      for (const [field, rules] of Object.entries(this._validationRules)) {
        for (const rule of rules) {
          const error = rule(this[field], field);
          if (error) errors.push(error);
