  { name: 'Alice', email: 'alice@example.com', age: 30 },
  {
    name: [(v) => !v ? 'Name required' : null],
    email: [(v) => !v?.includes('@') ? 'Invalid email' : null],
    age: [(v) => v < 0 || v > 150 ? 'Invalid age' : null],
  }
);

user.observe((change) => console.log(`${change.prop}: ${change.oldValue} → ${change.newValue}`));
user.name = 'Bob'; // Logs: "name: Alice → Bob"
user.validate();   // { valid: true }
user.toJSON();     // { name: 'Bob', email: 'alice@example.com', age: 30 }

Example 1: App Router with Server and Client Components // app/dashboard/page.tsx — Server Component (default)
// This component runs ONLY on the server. It can directly access databases,
// read files, and call internal services without exposing secrets to the client.

import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { DashboardChart } from './DashboardChart';

export default async function DashboardPage() {
  const session = await getServerSession();

  if (!session) {
    redirect('/login');
  }

  // Direct database access — no API route needed
  const metrics = await prisma.metric.findMany({
    where: { userId: session.user.id },
    orderBy: { createdAt: 'desc' },
    take: 30,
  });

  // Server Component passes serializable data to Client Component
  return (
    <main>
      <h1>Dashboard</h1>
      <DashboardChart data={metrics} />
    </main>
  );
} // app/dashboard/DashboardChart.tsx — Client Component
// The 'use client' directive marks this as a Client Component.
// It ships JavaScript to the browser and can use hooks, event handlers, and browser APIs.

'use client';

import { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip } from 'recharts';

interface Metric {
  id: string;
  value: number;
  createdAt: string;
}

export function DashboardChart({ data }: { data: Metric[] }) {
  const [timeRange, setTimeRange] = useState<'7d' | '30d'>('7d');

  const filtered = timeRange === '7d' ? data.slice(0, 7) : data;

  return (
    <div>
      <button onClick={() => setTimeRange('7d')}>7 Days</button>
      <button onClick={() => setTimeRange('30d')}>30 Days</button>
      <LineChart width={600} height={300} data={filtered}>
        <XAxis dataKey="createdAt" />
        <YAxis />
        <Tooltip />
        <Line type="monotone" dataKey="value" stroke="#8884d8" />
      </LineChart>
    </div>
  );
} The Server Component fetches data directly from the database without an intermediate API layer, reducing latency and eliminating client-side loading states for the initial render. The Client Component receives pre-fetched data as props and handles interactive state locally.

Example 2: Server Actions for Form Handling // app/posts/new/page.tsx — Server Action defined inline
import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { prisma } from '@/lib/prisma';
import { z } from 'zod';

const PostSchema = z.object({
  title: z.string().min(1).max(200),
  content: z.string().min(10).max(50000),
  published: z.coerce.boolean().default(false),
});

export default function NewPostPage() {
  async function createPost(formData: FormData) {
    'use server';

    const parsed = PostSchema.safeParse({
      title: formData.get('title'),
      content: formData.get('content'),
      published: formData.get('published'),
    });

    if (!parsed.success) {
      throw new Error('Validation failed: ' + parsed.error.message);
    }

    await prisma.post.create({
      data: parsed.data,
    });

    revalidatePath('/posts');
    redirect('/posts');
  }

  return (
    <form action={createPost}>
      <input name="title" placeholder="Post title" required />
      <textarea name="content" placeholder="Write your post..." required />
      <label>
        <input type="checkbox" name="published" />
        Publish immediately
      </label>
      <button type="submit">Create Post</button>
    </form>
  );
} Server Actions eliminate the need for separate API routes for form submissions. The function marked with 'use server' executes entirely on the server, with Next.js automatically handling the network request, serialization, and error propagation. This pattern reduces boilerplate while maintaining type safety between client and server.

Example 3: Middleware for Authentication and Routing // middleware.ts — Runs at the edge before every matched request
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { getToken } from 'next-auth/jwt';

export async function middleware(request: NextRequest) {
  const token = await getToken({ req: request });
  const { pathname } = request.nextUrl;

  // Allow public routes
  if (pathname.startsWith('/login') || pathname.startsWith('/api/auth')) {
    return NextResponse.next();
  }

  // Redirect unauthenticated users to login
  if (!token) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('callbackUrl', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Role-based access control
  if (pathname.startsWith('/admin') && token.role !== 'admin') {
    return NextResponse.redirect(new URL('/unauthorized', request.url));
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
}; Middleware executes at the edge (CDN level) before the request reaches your application server. This makes authentication checks extremely fast and prevents unauthorized requests from consuming server resources. The matcher configuration excludes static assets from middleware processing.

SSR Server-Side Rendering generates HTML on the server for every incoming request, ensuring users and search engine crawlers receive fully rendered content without waiting for JavaScript to execute on the client. In Next.js, SSR is the default behavior in the App Router for any Server Component that performs data fetching, and is explicitly opted into in the Pages Router via getServerSideProps. The server executes the component tree, resolves all data dependencies, and streams the resulting HTML to the client along with a minimal JavaScript payload for hydration. SSR is essential for pages that display user-specific or frequently changing data that cannot be pre-rendered at build time. Examples include personalized dashboards, search results pages, and authenticated content where the response depends on cookies or headers. The trade-off is increased server load and higher Time to First Byte (TTFB) compared to static pages, since every request triggers a full render cycle on the server. In the App Router, Server Components are SSR by default. Any component in the app/ directory that does not include the "use client" directive runs exclusively on the server. You can fetch data directly in the component body using async/await without additional API layers. Next.js automatically deduplicates identical fetch requests within a single render pass, and you can control caching behavior with the cache and next.revalidate options on individual fetch calls. In the Pages Router, getServerSideProps runs on every request and passes its return value as props to the page component. The function has access to the request object, cookies, headers, and query parameters. It must return an object with a props key, a redirect key, or a notFound: true flag. The function never runs in the browser, so you can safely use server-only code like database queries or secret API keys. // App Router - Server Component with SSR (default behavior)
// app/dashboard/page.tsx
import { cookies } from 'next/headers';

interface DashboardData {
  user: { name: string; email: string };
  stats: { totalOrders: number; revenue: number };
}

export default async function DashboardPage() {
  const cookieStore = cookies();
  const token = cookieStore.get('session')?.value;

  const data: DashboardData = await fetch('https://api.example.com/dashboard', {
    headers: { Authorization: `Bearer ${token}` },
    cache: 'no-store', // Opt out of caching for fresh data every request
  }).then(res => res.json());

  return (
    <main>
      <h1>Welcome, {data.user.name}</h1>
      <div className="stats-grid">
        <StatCard label="Total Orders" value={data.stats.totalOrders} />
        <StatCard label="Revenue" value={`$${data.stats.revenue}`} />
      </div>
    </main>
  );
} // Pages Router - getServerSideProps
// pages/profile/[id].tsx
import { GetServerSideProps } from 'next';

interface ProfileProps {
  user: { id: string; name: string; bio: string };
}

export const getServerSideProps: GetServerSideProps<ProfileProps> = async (context) => {
  const { id } = context.params!;
  const res = await fetch(`https://api.example.com/users/${id}`);

  if (!res.ok) {
    return { notFound: true };
  }

  const user = await res.json();
  return { props: { user } };
};

export default function ProfilePage({ user }: ProfileProps) {
  return (
    <article>
      <h1>{user.name}</h1>
      <p>{user.bio}</p>
    </article>
  );
}

SSG Static Site Generation pre-renders pages at build time, producing plain HTML files that can be served directly from a CDN without any server computation at request time. SSG delivers the fastest possible page loads because the HTML is already generated and cached at the edge. In Next.js, SSG is achieved in the Pages Router via getStaticProps (optionally combined with getStaticPaths for dynamic routes) and in the App Router by using fetch with default caching behavior or by exporting generateStaticParams for dynamic segments. SSG is ideal for content that does not change between deployments or changes infrequently enough that rebuilding is acceptable. Marketing pages, blog posts, documentation, product catalogs, and landing pages are classic SSG candidates. The key constraint is that the content must be knowable at build time: you need access to the data source during the build process, and the number of pages must be finite and enumerable. For dynamic routes with SSG, you must tell Next.js which paths to pre-render. In the Pages Router, getStaticPaths returns an array of path parameters. The fallback option controls behavior for paths not generated at build time: false returns 404, true serves a loading state while generating the page on first request, and 'blocking' waits for generation to complete before responding (behaving like SSR for the first visitor). In the App Router, generateStaticParams serves the same purpose, returning an array of parameter objects for each path to pre-render. The build output for SSG pages is a set of .html files and corresponding .json files containing the page props. These are deployed to a CDN and served with appropriate cache headers. Subsequent deployments generate new static files, and the CDN invalidates its cache. This model scales infinitely because serving static files requires no compute resources beyond the CDN edge nodes. // App Router - Static Generation with generateStaticParams
// app/blog/[slug]/page.tsx
import { notFound } from 'next/navigation';

interface Post {
  slug: string;
  title: string;
  content: string;
  publishedAt: string;
}

// Generate static paths at build time
export async function generateStaticParams() {
  const posts: Post[] = await fetch('https://cms.example.com/posts').then(r => r.json());
  return posts.map((post) => ({ slug: post.slug }));
}

// Generate metadata for SEO
export async function generateMetadata({ params }: { params: { slug: string } }) {
  const post = await getPost(params.slug);
  if (!post) return { title: 'Not Found' };
  return { title: post.title, description: post.content.slice(0, 160) };
}

async function getPost(slug: string): Promise<Post | null> {
  const res = await fetch(`https://cms.example.com/posts/${slug}`, {
    next: { revalidate: false }, // Fully static, no revalidation
  });
  if (!res.ok) return null;
  return res.json();
}

export default async function BlogPostPage({ params }: { params: { slug: string } }) {
  const post = await getPost(params.slug);
  if (!post) notFound();

  return (
    <article>
      <h1>{post.title}</h1>
      <time dateTime={post.publishedAt}>{new Date(post.publishedAt).toLocaleDateString()}</time>
      <div dangerouslySetInnerHTML={{ __html: post.content }} />
    </article>
  );
}

ISR Incremental Static Regeneration combines the performance benefits of static generation with the freshness of server-side rendering. ISR serves pre-rendered static pages from the cache but revalidates them in the background after a configurable time interval. When a request arrives for a page whose revalidation period has elapsed, Next.js serves the stale cached version immediately (ensuring fast response times) while triggering a background regeneration. The next request after regeneration completes receives the updated page. This pattern is sometimes called stale-while-revalidate at the page level. ISR solves the fundamental limitation of pure SSG: content staleness. With SSG, updating a single blog post requires rebuilding and redeploying the entire site. With ISR, you set a revalidate interval (in seconds), and Next.js automatically regenerates individual pages in the background without a full rebuild. This makes ISR suitable for content that updates periodically but does not need real-time freshness: product prices that change hourly, news articles that update throughout the day, or user-generated content that grows over time. On-demand revalidation extends ISR by allowing you to trigger regeneration programmatically rather than waiting for the time-based interval. When your CMS publishes a new article or updates a product price, it can call a Next.js API route that invokes revalidatePath() or revalidateTag(), immediately invalidating the cached page. This gives you the performance of static pages with near-real-time content updates, limited only by the time it takes to regenerate the page. In the App Router, ISR is configured by passing next: { revalidate: seconds } to fetch calls or by exporting a revalidate segment config. In the Pages Router, you add a revalidate property to the object returned by getStaticProps. Both approaches produce the same behavior: serve static HTML, revalidate in the background after the specified interval. // App Router - ISR with time-based revalidation
// app/products/[id]/page.tsx
interface Product {
  id: string;
  name: string;
  price: number;
  description: string;
  lastUpdated: string;
}

// Revalidate every 60 seconds
export const revalidate = 60;

export async function generateStaticParams() {
  const products = await fetch('https://api.example.com/products').then(r => r.json());
  return products.map((p: Product) => ({ id: p.id }));
}

export default async function ProductPage({ params }: { params: { id: string } }) {
  const product: Product = await fetch(`https://api.example.com/products/${params.id}`, {
    next: { revalidate: 60 }, // ISR: revalidate every 60 seconds
  }).then(r => r.json());

  return (
    <div>
      <h1>{product.name}</h1>
      <p className="price">${product.price.toFixed(2)}</p>
      <p>{product.description}</p>
      <small>Last updated: {product.lastUpdated}</small>
    </div>
  );
} // On-demand revalidation via API route
// app/api/revalidate/route.ts
import { revalidatePath, revalidateTag } from 'next/cache';
import { NextRequest, NextResponse } from 'next/server';

export async function POST(request: NextRequest) {
  const { secret, path, tag } = await request.json();

  if (secret !== process.env.REVALIDATION_SECRET) {
    return NextResponse.json({ message: 'Invalid secret' }, { status: 401 });
  }

  if (path) {
    revalidatePath(path);
    return NextResponse.json({ revalidated: true, path });
  }

  if (tag) {
    revalidateTag(tag);
    return NextResponse.json({ revalidated: true, tag });
  }

  return NextResponse.json({ message: 'Missing path or tag' }, { status: 400 });
}

API Routes API routes in Next.js provide serverless backend endpoints that deploy alongside your frontend application. They handle HTTP requests without requiring a separate backend server, making them ideal for form submissions, webhook handlers, authentication callbacks, and lightweight CRUD operations. API routes run in a Node.js environment (or Edge runtime) and have access to the full request/response cycle including headers, cookies, and request bodies. In the App Router, API routes are called Route Handlers and are defined in route.ts files within the app/ directory. Each file exports named functions corresponding to HTTP methods (GET, POST, PUT, DELETE, PATCH). Route Handlers receive a NextRequest object and return a NextResponse. They support both the Node.js runtime (default) and the Edge runtime for lower latency at the cost of a restricted API surface. In the Pages Router, API routes live in the pages/api/ directory. Each file exports a default handler function that receives req (NextApiRequest) and res (NextApiResponse) objects similar to Express.js. Dynamic API routes use the same bracket syntax as page routes ([id].ts), and catch-all routes use spread syntax ([...params].ts). API routes are serverless functions under the hood when deployed to Vercel or similar platforms. This means they have cold start latency, a maximum execution duration (typically 10-60 seconds depending on the plan), and no persistent state between invocations. For long-running operations, use background jobs or queue-based architectures. For real-time communication, consider WebSocket alternatives or server-sent events with streaming responses. // App Router - Route Handler with multiple HTTP methods
// app/api/posts/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';

const PostSchema = z.object({
  title: z.string().min(1).max(200),
  content: z.string().min(10),
  published: z.boolean().default(false),
});

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const page = parseInt(searchParams.get('page') || '1');
  const limit = parseInt(searchParams.get('limit') || '10');

  const posts = await db.post.findMany({
    skip: (page - 1) * limit,
    take: limit,
    orderBy: { createdAt: 'desc' },
  });

  return NextResponse.json({ posts, page, limit });
}

export async function POST(request: NextRequest) {
  const body = await request.json();
  const parsed = PostSchema.safeParse(body);

  if (!parsed.success) {
    return NextResponse.json(
      { error: 'Validation failed', details: parsed.error.flatten() },
      { status: 400 }
    );
  }

  const post = await db.post.create({ data: parsed.data });
  return NextResponse.json(post, { status: 201 });
} // App Router - Dynamic route handler
// app/api/posts/[id]/route.ts
import { NextRequest, NextResponse } from 'next/server';

export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  const post = await db.post.findUnique({ where: { id: params.id } });

  if (!post) {
    return NextResponse.json({ error: 'Not found' }, { status: 404 });
  }

  return NextResponse.json(post);
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  await db.post.delete({ where: { id: params.id } });
  return new NextResponse(null, { status: 204 });
}

Middleware Middleware in Next.js runs before a request is completed, executing at the edge (close to the user) before the request reaches your route handlers or page components. Middleware intercepts every request matching its configured path pattern and can rewrite URLs, redirect users, modify request and response headers, set cookies, or return early responses. It is the ideal location for cross-cutting concerns like authentication checks, A/B testing, geolocation-based routing, bot detection, and rate limiting. Middleware is defined in a single middleware.ts file at the root of your project (next to app/ or pages/). It exports a default function that receives a NextRequest and must return a NextResponse. The config export with a matcher array controls which paths trigger the middleware. Without a matcher, middleware runs on every request including static assets, so always define explicit path patterns to avoid unnecessary execution. The Edge runtime used by middleware provides a subset of Node.js APIs optimized for low-latency execution. You cannot use Node.js-specific modules like fs, path, or native database drivers. Instead, use fetch-based APIs, edge-compatible libraries, and lightweight operations. Middleware has a strict execution time limit (typically 1.5 seconds on Vercel) and a maximum response body size, making it unsuitable for heavy computation or large data transformations. Middleware executes in a specific order within the Next.js request lifecycle: it runs after the next.config.js rewrites and redirects but before route matching, rendering, and API route execution. This positioning means middleware can modify the request before any page or API logic sees it, enabling patterns like injecting user identity headers that downstream components can read without repeating authentication logic. // middleware.ts - Authentication and routing middleware
import { NextRequest, NextResponse } from 'next/server';
import { verifyToken } from './lib/auth';

const publicPaths = ['/login', '/register', '/api/auth', '/public'];
const adminPaths = ['/admin', '/api/admin'];

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Allow public paths without authentication
  if (publicPaths.some(path => pathname.startsWith(path))) {
    return NextResponse.next();
  }

  // Check authentication token
  const token = request.cookies.get('auth-token')?.value;
  if (!token) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('redirect', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Verify token and extract user claims
  const user = await verifyToken(token);
  if (!user) {
    return NextResponse.redirect(new URL('/login', request.url));
  }

  // Admin route authorization
  if (adminPaths.some(path => pathname.startsWith(path)) && user.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  // Inject user identity into request headers for downstream use
  const response = NextResponse.next();
  response.headers.set('x-user-id', user.id);
  response.headers.set('x-user-role', user.role);
  return response;
}

export const config = {
  matcher: [
    // Match all paths except static files and Next.js internals
    '/((?!_next/static|_next/image|favicon.ico|public/).*)',
  ],
};

App Router Patterns The App Router, introduced in Next.js 13 and stable in Next.js 14, represents a fundamental shift in how Next.js applications are structured. It uses React Server Components by default, file-system-based routing with the app/ directory, nested layouts that persist across navigations, streaming with Suspense boundaries, and parallel routes for complex UI compositions. Understanding App Router patterns is essential for building modern Next.js applications. Layouts and Templates: Layouts are components that wrap child routes and persist their state across navigations. A layout.tsx file in any directory becomes the layout for all routes within that directory and its subdirectories. Unlike the Pages Router's _app.tsx which re-renders on every navigation, layouts only re-render when their own data changes. Templates (template.tsx) are similar but create a new instance on every navigation, useful for enter/exit animations or per-page state reset. Server Components vs Client Components: In the App Router, all components are Server Components by default. They run only on the server, can directly access databases and file systems, and send zero JavaScript to the client. Add the "use client" directive at the top of a file to make it a Client Component that hydrates in the browser with interactivity. The boundary between server and client components is the key architectural decision: keep data fetching and heavy logic in Server Components, and push only interactive UI (event handlers, state, effects) to Client Components. Loading and Error States: The App Router uses special file conventions for loading and error handling. A loading.tsx file in any route segment automatically wraps the page in a Suspense boundary, showing the loading component while the page's async data resolves. An error.tsx file creates an error boundary that catches runtime errors in the segment and its children, displaying a fallback UI with a retry mechanism. A not-found.tsx file handles 404 responses triggered by the notFound() function. Parallel Routes and Intercepting Routes: Parallel routes (defined with @slot folder naming) allow rendering multiple pages simultaneously in the same layout, useful for dashboards with independent panels or modal patterns. Intercepting routes (using (.), (..), (...) conventions) let you intercept a navigation and show a route in a different context, such as opening a photo in a modal while keeping the gallery visible behind it. Data Fetching Patterns: The App Router encourages fetching data at the component level rather than at the page level. Each Server Component can independently fetch its own data using async/await. Next.js automatically deduplicates identical fetch requests within a render pass. For shared data across components, use React's cache() function to memoize expensive computations. For mutations, use Server Actions (functions marked with "use server") that can be called directly from Client Components without creating API endpoints. // App Router - Nested layout with parallel routes
// app/dashboard/layout.tsx
export default function DashboardLayout({
  children,
  analytics,
  notifications,
}: {
  children: React.ReactNode;
  analytics: React.ReactNode;   // @analytics parallel route
  notifications: React.ReactNode; // @notifications parallel route
}) {
  return (
    <div className="dashboard-grid">
      <main>{children}</main>
      <aside className="analytics-panel">{analytics}</aside>
      <aside className="notifications-panel">{notifications}</aside>
    </div>
  );
}

// app/dashboard/@analytics/page.tsx
export default async function AnalyticsPanel() {
  const stats = await fetch('https://api.example.com/analytics', {
    next: { revalidate: 300 }, // Revalidate every 5 minutes
  }).then(r => r.json());

  return <AnalyticsChart data={stats} />;
} // Server Actions for mutations
// app/posts/actions.ts
'use server';

import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { z } from 'zod';

const CreatePostSchema = z.object({
  title: z.string().min(1),
  content: z.string().min(10),
});

export async function createPost(formData: FormData) {
  const parsed = CreatePostSchema.safeParse({
    title: formData.get('title'),
    content: formData.get('content'),
  });

  if (!parsed.success) {
    return { error: parsed.error.flatten().fieldErrors };
  }

  await db.post.create({ data: parsed.data });
  revalidatePath('/posts');
  redirect('/posts');
}

// app/posts/new/page.tsx (Client Component using Server Action)
'use client';

import { createPost } from '../actions';
import { useFormState } from 'react-dom';

export default function NewPostPage() {
  const [state, formAction] = useFormState(createPost, null);

  return (
    <form action={formAction}>
      <input name="title" placeholder="Post title" required />
      {state?.error?.title && <p className="error">{state.error.title}</p>}
      <textarea name="content" placeholder="Write your post..." required />
      {state?.error?.content && <p className="error">{state.error.content}</p>}
      <button type="submit">Publish</button>
    </form>
  );
}

Code Examples // Compound component pattern with context
import { createContext, useContext, useState, ReactNode, useId } from 'react';

interface TabsContextType {
  activeTab: string;
  setActiveTab: (id: string) => void;
  baseId: string;
}

const TabsContext = createContext<TabsContextType | null>(null);

function useTabs() {
  const context = useContext(TabsContext);
  if (!context) throw new Error('Tab components must be used within Tabs');
  return context;
}

function Tabs({ children, defaultTab }: { children: ReactNode; defaultTab: string }) {
  const [activeTab, setActiveTab] = useState(defaultTab);
  const baseId = useId();

  return (
    <TabsContext.Provider value={{ activeTab, setActiveTab, baseId }}>
      <div role="tablist">{children}</div>
    </TabsContext.Provider>
  );
}

function TabTrigger({ id, children }: { id: string; children: ReactNode }) {
  const { activeTab, setActiveTab, baseId } = useTabs();
  const isActive = activeTab === id;

  return (
    <button
      role="tab"
      id={`${baseId}-tab-${id}`}
      aria-selected={isActive}
      aria-controls={`${baseId}-panel-${id}`}
      tabIndex={isActive ? 0 : -1}
      onClick={() => setActiveTab(id)}
    >
      {children}
    </button>
  );
}

function TabPanel({ id, children }: { id: string; children: ReactNode }) {
  const { activeTab, baseId } = useTabs();
  if (activeTab !== id) return null;

  return (
    <div
      role="tabpanel"
      id={`${baseId}-panel-${id}`}
      aria-labelledby={`${baseId}-tab-${id}`}
    >
      {children}
    </div>
  );
}

Tabs.Trigger = TabTrigger;
Tabs.Panel = TabPanel;

// Usage: consumers control composition order and content
function App() {
  return (
    <Tabs defaultTab="overview">
      <Tabs.Trigger id="overview">Overview</Tabs.Trigger>
      <Tabs.Trigger id="settings">Settings</Tabs.Trigger>
