createSlice with Immer and Prepared Actions import { createSlice, PayloadAction, nanoid } from '@reduxjs/toolkit';

interface CartItem {
  id: string;
  productId: string;
  name: string;
  price: number;
  quantity: number;
  addedAt: string;
}

interface CartState {
  items: CartItem[];
  couponCode: string | null;
  discountPercent: number;
}

const initialState: CartState = {
  items: [],
  couponCode: null,
  discountPercent: 0,
};

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    // Simple reducer — Immer allows "mutating" syntax
    addItem: {
      reducer(state, action: PayloadAction<CartItem>) {
        const existing = state.items.find(i => i.productId === action.payload.productId);
        if (existing) {
          existing.quantity += action.payload.quantity;
        } else {
          state.items.push(action.payload);
        }
      },
      // Prepare callback — add generated fields before reaching reducer
      prepare(product: { id: string; name: string; price: number }, quantity = 1) {
        return {
          payload: {
            id: nanoid(),
            productId: product.id,
            name: product.name,
            price: product.price,
            quantity,
            addedAt: new Date().toISOString(),
          },
        };
      },
    },

    removeItem(state, action: PayloadAction<string>) {
      state.items = state.items.filter(item => item.id !== action.payload);
    },

    updateQuantity(state, action: PayloadAction<{ id: string; quantity: number }>) {
      const item = state.items.find(i => i.id === action.payload.id);
      if (item) {
        item.quantity = Math.max(0, action.payload.quantity);
        if (item.quantity === 0) {
          state.items = state.items.filter(i => i.id !== action.payload.id);
        }
      }
    },

    applyCoupon(state, action: PayloadAction<{ code: string; discount: number }>) {
      state.couponCode = action.payload.code;
      state.discountPercent = action.payload.discount;
    },

    clearCart() {
      return initialState;
    },
  },
});

export const { addItem, removeItem, updateQuantity, applyCoupon, clearCart } = cartSlice.actions;

createAsyncThunk with Error Handling import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import type { RootState } from '../../store';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  stock: number;
}

interface ProductsState {
  items: Product[];
  selectedProduct: Product | null;
  status: 'idle' | 'loading' | 'succeeded' | 'failed';
  error: string | null;
  currentPage: number;
  totalPages: number;
}

// Async thunk with typed error handling
export const fetchProducts = createAsyncThunk<
  { products: Product[]; totalPages: number },  // Return type
  { page: number; category?: string },           // Argument type
  { state: RootState; rejectValue: string }      // ThunkAPI config
>(
  'products/fetchProducts',
  async ({ page, category }, { rejectWithValue, signal }) => {
    try {
      const params = new URLSearchParams({ page: String(page) });
      if (category) params.set('category', category);

      const response = await fetch(`/api/products?${params}`, { signal });

      if (!response.ok) {
        const error = await response.json();
        return rejectWithValue(error.message || 'Failed to fetch products');
      }

      return await response.json();
    } catch (err) {
      if (err instanceof Error && err.name === 'AbortError') {
        return rejectWithValue('Request cancelled');
      }
      return rejectWithValue('Network error');
    }
  },
  {
    // Condition — prevent duplicate requests
    condition: (_, { getState }) => {
      const { products } = getState();
      if (products.status === 'loading') return false;  // Already loading
    },
  }
);

export const productsSlice = createSlice({
  name: 'products',
  initialState: {
    items: [],
    selectedProduct: null,
    status: 'idle',
    error: null,
    currentPage: 1,
    totalPages: 0,
  } as ProductsState,
  reducers: {
    selectProduct(state, action: PayloadAction<string>) {
      state.selectedProduct = state.items.find(p => p.id === action.payload) || null;
    },
    clearError(state) {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchProducts.pending, (state) => {
        state.status = 'loading';
        state.error = null;
      })
      .addCase(fetchProducts.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.items = action.payload.products;
        state.totalPages = action.payload.totalPages;
      })
      .addCase(fetchProducts.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.payload ?? 'Unknown error';
      });
  },
});

