    markAllAsRead(state) {
      const updates = state.ids.map(id => ({
        id: id as string,
        changes: { read: true },
      }));
      notificationsAdapter.updateMany(state, updates);
    },
    removeNotification: notificationsAdapter.removeOne,
    addNotification: notificationsAdapter.addOne,
  },
  extraReducers: (builder) => {
