Accessible Modal Dialog import { useRef, useEffect, useCallback } from 'react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

function AccessibleModal({ isOpen, onClose, title, children }: ModalProps) {
  const modalRef = useRef<HTMLDivElement>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);

  // Trap focus within modal
  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      onClose();
      return;
    }

    if (event.key !== 'Tab') return;

    const focusableElements = modalRef.current?.querySelectorAll<HTMLElement>(
      'a[href], button:not([disabled]), textarea, input, select, [tabindex]:not([tabindex="-1"])'
    );

    if (!focusableElements || focusableElements.length === 0) return;

    const firstElement = focusableElements[0];
    const lastElement = focusableElements[focusableElements.length - 1];

    if (event.shiftKey && document.activeElement === firstElement) {
      event.preventDefault();
      lastElement.focus();
    } else if (!event.shiftKey && document.activeElement === lastElement) {
      event.preventDefault();
      firstElement.focus();
    }
  }, [onClose]);

  useEffect(() => {
    if (isOpen) {
      previousFocusRef.current = document.activeElement as HTMLElement;
      document.addEventListener('keydown', handleKeyDown);
      // Focus the modal after render
      setTimeout(() => modalRef.current?.focus(), 0);
      // Prevent background scrolling
      document.body.style.overflow = 'hidden';
    }

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = '';
      // Restore focus to trigger element
      previousFocusRef.current?.focus();
    };
  }, [isOpen, handleKeyDown]);

  if (!isOpen) return null;

  return (
    <>
      {/* Backdrop */}
      <div
        className="modal-backdrop"
        aria-hidden="true"
        onClick={onClose}
      />
      {/* Modal */}
      <div
        ref={modalRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
        aria-describedby="modal-description"
        tabIndex={-1}
        className="modal"
      >
        <header className="modal__header">
          <h2 id="modal-title">{title}</h2>
          <button
            onClick={onClose}
            aria-label="Close dialog"
            className="modal__close"
          >
            <span aria-hidden="true">&times;</span>
          </button>
        </header>
        <div id="modal-description" className="modal__body">
          {children}
        </div>
      </div>
    </>
  );
}

Accessible Form with Validation import { useState, useId } from 'react';

interface FormErrors {
  [field: string]: string;
}

function AccessibleForm() {
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitted, setSubmitted] = useState(false);
  const emailId = useId();
  const passwordId = useId();
  const nameId = useId();
  const errorSummaryId = useId();

  const validate = (formData: FormData): FormErrors => {
    const newErrors: FormErrors = {};
    const email = formData.get('email') as string;
    const password = formData.get('password') as string;

    if (!email) newErrors.email = 'Email is required';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))
      newErrors.email = 'Enter a valid email address';

    if (!password) newErrors.password = 'Password is required';
    else if (password.length < 8)
      newErrors.password = 'Password must be at least 8 characters';

    return newErrors;
  };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const newErrors = validate(formData);
    setErrors(newErrors);

    if (Object.keys(newErrors).length > 0) {
      // Focus error summary for screen reader announcement
      document.getElementById(errorSummaryId)?.focus();
      return;
    }

    setSubmitted(true);
  };

  return (
    <form onSubmit={handleSubmit} noValidate aria-label="Registration form">
      {/* Error summary — announced when focused */}
      {Object.keys(errors).length > 0 && (
        <div
          id={errorSummaryId}
          role="alert"
          aria-labelledby="error-heading"
          tabIndex={-1}
          className="error-summary"
        >
          <h3 id="error-heading">There are {Object.keys(errors).length} errors in this form</h3>
          <ul>
            {Object.entries(errors).map(([field, message]) => (
              <li key={field}>
                <a href={`#${field}`}>{message}</a>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Success message */}
      {submitted && (
        <div role="status" aria-live="polite" className="success-message">
          Registration successful! Check your email for confirmation.
        </div>
      )}

      <div className="form-field">
        <label htmlFor={nameId}>
          Full name <span aria-hidden="true">*</span>
          <span className="visually-hidden">(required)</span>
        </label>
        <input
          id={nameId}
          name="name"
          type="text"
          required
          aria-required="true"
          autoComplete="name"
        />
      </div>

      <div className="form-field">
        <label htmlFor={emailId}>
          Email address <span aria-hidden="true">*</span>
          <span className="visually-hidden">(required)</span>
        </label>
        <input
          id={emailId}
          name="email"
          type="email"
          required
          aria-required="true"
          aria-invalid={!!errors.email}
          aria-describedby={errors.email ? `${emailId}-error` : undefined}
          autoComplete="email"
        />
        {errors.email && (
          <span id={`${emailId}-error`} className="field-error" role="alert">
            {errors.email}
          </span>
        )}
      </div>

      <div className="form-field">
        <label htmlFor={passwordId}>
          Password <span aria-hidden="true">*</span>
          <span className="visually-hidden">(required)</span>
        </label>
        <input
          id={passwordId}
          name="password"
          type="password"
          required
          aria-required="true"
          aria-invalid={!!errors.password}
          aria-describedby={`${passwordId}-hint ${errors.password ? `${passwordId}-error` : ''}`}
          autoComplete="new-password"
          minLength={8}
        />
        <span id={`${passwordId}-hint`} className="field-hint">
          Must be at least 8 characters with one uppercase and one number
        </span>
        {errors.password && (
          <span id={`${passwordId}-error`} className="field-error" role="alert">
            {errors.password}
          </span>
        )}
      </div>

      <button type="submit">Create account</button>
    </form>
  );
}

Accessible Data Table with Sorting import { useState } from 'react';

interface Column<T> {
  key: keyof T;
  label: string;
  sortable?: boolean;
}

interface AccessibleTableProps<T> {
  data: T[];
  columns: Column<T>[];
  caption: string;
}

function AccessibleTable<T extends Record<string, any>>({
  data, columns, caption
}: AccessibleTableProps<T>) {
  const [sortColumn, setSortColumn] = useState<keyof T | null>(null);
  const [sortDirection, setSortDirection] = useState<'ascending' | 'descending'>('ascending');
  const [announcement, setAnnouncement] = useState('');

  const handleSort = (column: Column<T>) => {
    if (!column.sortable) return;

    const newDirection = sortColumn === column.key && sortDirection === 'ascending'
      ? 'descending' : 'ascending';

    setSortColumn(column.key);
    setSortDirection(newDirection);
    setAnnouncement(`Table sorted by ${column.label}, ${newDirection}`);
  };

  const sortedData = [...data].sort((a, b) => {
    if (!sortColumn) return 0;
    const aVal = a[sortColumn];
    const bVal = b[sortColumn];
    const comparison = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
    return sortDirection === 'ascending' ? comparison : -comparison;
  });

  return (
    <>
      {/* Live region for sort announcements */}
      <div aria-live="polite" aria-atomic="true" className="visually-hidden">
        {announcement}
      </div>

      <table aria-label={caption} role="grid">
        <caption className="visually-hidden">{caption}</caption>
        <thead>
          <tr>
            {columns.map(column => (
              <th
                key={String(column.key)}
                scope="col"
                aria-sort={sortColumn === column.key ? sortDirection : undefined}
              >
                {column.sortable ? (
                  <button
                    onClick={() => handleSort(column)}
                    aria-label={`Sort by ${column.label}, currently ${
                      sortColumn === column.key ? sortDirection : 'unsorted'
                    }`}
                    className="sort-button"
                  >
                    {column.label}
                    <span aria-hidden="true" className="sort-icon">
                      {sortColumn === column.key
                        ? (sortDirection === 'ascending' ? '▲' : '▼')
                        : '⇅'}
                    </span>
                  </button>
                ) : (
                  column.label
                )}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {sortedData.map((row, index) => (
            <tr key={index}>
              {columns.map(column => (
                <td key={String(column.key)}>{String(row[column.key])}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </>
  );
}

