Image Optimization with Responsive Loading import { useState, useRef, useEffect } from 'react';

interface OptimizedImageProps {
  src: string;
  alt: string;
  width: number;
  height: number;
  priority?: boolean;
  sizes?: string;
}

function OptimizedImage({ src, alt, width, height, priority = false, sizes }: OptimizedImageProps) {
  // Generate srcset for responsive images
  const widths = [320, 640, 768, 1024, 1280, 1920];
  const srcSet = widths
    .filter(w => w <= width * 2) // Don't upscale beyond 2x
    .map(w => `${src}?w=${w}&format=webp ${w}w`)
    .join(', ');

  const defaultSizes = sizes || `
    (max-width: 640px) 100vw,
    (max-width: 1024px) 50vw,
    33vw
  `;

  return (
    <picture>
      {/* AVIF for browsers that support it (30-50% smaller than WebP) */}
      <source
        type="image/avif"
        srcSet={widths.filter(w => w <= width * 2).map(w => `${src}?w=${w}&format=avif ${w}w`).join(', ')}
        sizes={defaultSizes}
      />
      {/* WebP fallback */}
      <source
        type="image/webp"
        srcSet={srcSet}
        sizes={defaultSizes}
      />
      {/* Original format as final fallback */}
      <img
        src={`${src}?w=768&format=webp`}
        alt={alt}
        width={width}
        height={height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : 'auto'}
        style={{ aspectRatio: `${width} / ${height}` }}
      />
    </picture>
  );
}

// Intersection Observer for lazy-loaded components
function useLazyLoad(rootMargin = '200px') {
  const ref = useRef<HTMLDivElement>(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin }
    );

    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [rootMargin]);

  return { ref, isVisible };
}

Service Worker Caching Strategies // service-worker.ts
const CACHE_VERSION = 'v2';
const STATIC_CACHE = `static-${CACHE_VERSION}`;
const DYNAMIC_CACHE = `dynamic-${CACHE_VERSION}`;
const API_CACHE = `api-${CACHE_VERSION}`;

const STATIC_ASSETS = [
  '/',
  '/index.html',
  '/static/js/main.chunk.js',
  '/static/css/main.css',
  '/manifest.json',
];

// Install: pre-cache static assets
self.addEventListener('install', (event: ExtendableEvent) => {
  event.waitUntil(
    caches.open(STATIC_CACHE).then(cache => cache.addAll(STATIC_ASSETS))
  );
  self.skipWaiting();
});

// Activate: clean old caches
self.addEventListener('activate', (event: ExtendableEvent) => {
  event.waitUntil(
    caches.keys().then(keys =>
      Promise.all(
        keys
          .filter(key => !key.includes(CACHE_VERSION))
          .map(key => caches.delete(key))
      )
    )
  );
  self.clients.claim();
});

// Fetch: strategy-based routing
self.addEventListener('fetch', (event: FetchEvent) => {
  const { request } = event;
  const url = new URL(request.url);

  if (url.pathname.startsWith('/api/')) {
    // Network First for API calls (fresh data preferred)
    event.respondWith(networkFirst(request, API_CACHE));
  } else if (request.destination === 'image') {
    // Cache First for images (rarely change)
    event.respondWith(cacheFirst(request, DYNAMIC_CACHE));
  } else if (STATIC_ASSETS.includes(url.pathname)) {
    // Cache First for pre-cached static assets
    event.respondWith(cacheFirst(request, STATIC_CACHE));
  } else {
    // Stale While Revalidate for everything else
    event.respondWith(staleWhileRevalidate(request, DYNAMIC_CACHE));
  }
});

async function networkFirst(request: Request, cacheName: string): Promise<Response> {
  try {
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(cacheName);
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    const cached = await caches.match(request);
    return cached || new Response('Offline', { status: 503 });
  }
}

async function cacheFirst(request: Request, cacheName: string): Promise<Response> {
  const cached = await caches.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(cacheName);
    cache.put(request, response.clone());
  }
  return response;
}

async function staleWhileRevalidate(request: Request, cacheName: string): Promise<Response> {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);

  const fetchPromise = fetch(request).then(response => {
    if (response.ok) cache.put(request, response.clone());
    return response;
  });

  return cached || fetchPromise;
}

