  ]
}

// Application migration function
function migrateUser(doc) {
  if (doc.schema_version === 1) {
    const parts = doc.address.split(', ');
    doc.address = { street: parts[0], city: parts[1], state: parts[2]?.split(' ')[0], zip: parts[2]?.split(' ')[1] };
    doc.schema_version = 2;
  }
  if (doc.schema_version === 2) {
    doc.addresses = [{ type: "home", ...doc.address }];
    delete doc.address;
    doc.name = { first: doc.name.split(' ')[0], last: doc.name.split(' ')[1] };
    doc.schema_version = 3;
  }
  return doc;
}

// Lazy migration: upgrade on read
async function getUser(userId) {
  let user = await db.users.findOne({ _id: userId });
  if (user.schema_version < 3) {
    user = migrateUser(user);
    await db.users.replaceOne({ _id: userId }, user);
  }
  return user;
}

Data Guard Configuration -- PRIMARY database preparation
-- Enable FORCE LOGGING (ensures all changes are logged, even NOLOGGING operations)
ALTER DATABASE FORCE LOGGING;

-- Configure redo transport to standby
ALTER SYSTEM SET LOG_ARCHIVE_DEST_2 =
    'SERVICE=standby_tns ASYNC VALID_FOR=(ONLINE_LOGFILES,PRIMARY_ROLE)
     DB_UNIQUE_NAME=standby_db COMPRESSION=ENABLE' SCOPE=BOTH;

-- For Maximum Availability (synchronous, zero data loss):
ALTER SYSTEM SET LOG_ARCHIVE_DEST_2 =
    'SERVICE=standby_tns SYNC AFFIRM VALID_FOR=(ONLINE_LOGFILES,PRIMARY_ROLE)
     DB_UNIQUE_NAME=standby_db NET_TIMEOUT=10' SCOPE=BOTH;

-- Set protection mode
ALTER DATABASE SET STANDBY DATABASE TO MAXIMIZE AVAILABILITY;
-- Options: MAXIMIZE PROTECTION (sync, primary shuts down if standby unavailable)
--          MAXIMIZE AVAILABILITY (sync, degrades to async if standby unavailable)
--          MAXIMIZE PERFORMANCE (async, default, minimal primary impact)

-- Create standby redo logs (required for real-time apply)
-- One more group than online redo logs, same size
ALTER DATABASE ADD STANDBY LOGFILE GROUP 4 SIZE 1G;
ALTER DATABASE ADD STANDBY LOGFILE GROUP 5 SIZE 1G;
ALTER DATABASE ADD STANDBY LOGFILE GROUP 6 SIZE 1G;
ALTER DATABASE ADD STANDBY LOGFILE GROUP 7 SIZE 1G;

-- STANDBY database: Start managed recovery (redo apply)
ALTER DATABASE RECOVER MANAGED STANDBY DATABASE USING CURRENT LOGFILE DISCONNECT;

-- Active Data Guard: Open standby read-only while applying redo
ALTER DATABASE OPEN READ ONLY;
ALTER DATABASE RECOVER MANAGED STANDBY DATABASE USING CURRENT LOGFILE DISCONNECT;

-- Monitor Data Guard status
SELECT
    DEST_ID, STATUS, TYPE, DATABASE_MODE, PROTECTION_MODE,
    ARCHIVED_SEQ#, APPLIED_SEQ#, ARCHIVED_SEQ# - APPLIED_SEQ# AS GAP
FROM V$ARCHIVE_DEST_STATUS
WHERE DEST_ID = 2;

-- Check apply lag
SELECT NAME, VALUE, DATUM_TIME FROM V$DATAGUARD_STATS
WHERE NAME IN ('transport lag', 'apply lag', 'apply finish time');

PL/SQL: Packages, Bulk Operations, and Error Handling -- Package specification: defines the public interface
CREATE OR REPLACE PACKAGE order_processing AS
    -- Custom exception
    e_insufficient_inventory EXCEPTION;
    PRAGMA EXCEPTION_INIT(e_insufficient_inventory, -20001);

    -- Types for bulk operations
    TYPE t_order_ids IS TABLE OF orders.order_id%TYPE;
    TYPE t_order_rec IS RECORD (
        order_id    orders.order_id%TYPE,
        customer_id orders.customer_id%TYPE,
        total       orders.total_amount%TYPE,
        status      orders.status%TYPE
    );
    TYPE t_order_tab IS TABLE OF t_order_rec;

    -- Public procedures
    PROCEDURE process_batch(
        p_order_ids IN t_order_ids,
        p_results   OUT SYS_REFCURSOR
    );

    FUNCTION calculate_discount(
        p_customer_id IN NUMBER,
        p_order_total IN NUMBER
    ) RETURN NUMBER DETERMINISTIC;

    PROCEDURE fulfill_order(
        p_order_id IN NUMBER
    );
END order_processing;
/

-- Package body: implementation
CREATE OR REPLACE PACKAGE BODY order_processing AS

    PROCEDURE process_batch(
        p_order_ids IN t_order_ids,
        p_results   OUT SYS_REFCURSOR
    ) IS
        v_processed NUMBER := 0;
        v_failed    NUMBER := 0;
    BEGIN
        -- FORALL: bulk DML with SAVE EXCEPTIONS for partial failure handling
        FORALL i IN 1..p_order_ids.COUNT SAVE EXCEPTIONS
            UPDATE orders
            SET status = 'PROCESSING',
                processed_at = SYSTIMESTAMP
            WHERE order_id = p_order_ids(i)
              AND status = 'PENDING';

        v_processed := SQL%ROWCOUNT;

        -- Return results cursor
        OPEN p_results FOR
            SELECT order_id, status, processed_at
            FROM orders
            WHERE order_id MEMBER OF p_order_ids;

    EXCEPTION
        WHEN DML_ERRORS THEN
            -- Handle partial failures from SAVE EXCEPTIONS
            v_failed := SQL%BULK_EXCEPTIONS.COUNT;
            FOR j IN 1..v_failed LOOP
                INSERT INTO order_errors (
                    order_id, error_code, error_msg, created_at
                ) VALUES (
                    p_order_ids(SQL%BULK_EXCEPTIONS(j).ERROR_INDEX),
                    SQL%BULK_EXCEPTIONS(j).ERROR_CODE,
                    SQLERRM(-SQL%BULK_EXCEPTIONS(j).ERROR_CODE),
                    SYSTIMESTAMP
                );
            END LOOP;
            -- Still open results cursor for caller
            OPEN p_results FOR
                SELECT order_id, status, processed_at
                FROM orders
                WHERE order_id MEMBER OF p_order_ids;
    END process_batch;

    FUNCTION calculate_discount(
        p_customer_id IN NUMBER,
        p_order_total IN NUMBER
    ) RETURN NUMBER DETERMINISTIC IS
        v_tier        VARCHAR2(20);
        v_lifetime    NUMBER;
        v_discount    NUMBER := 0;
    BEGIN
        -- BULK COLLECT with LIMIT for memory-safe cursor processing
        SELECT loyalty_tier, lifetime_spend
        INTO v_tier, v_lifetime
        FROM customers
        WHERE customer_id = p_customer_id;

        v_discount := CASE v_tier
            WHEN 'PLATINUM' THEN LEAST(p_order_total * 0.15, 500)
            WHEN 'GOLD'     THEN LEAST(p_order_total * 0.10, 200)
            WHEN 'SILVER'   THEN LEAST(p_order_total * 0.05, 100)
            ELSE 0
        END;

        RETURN v_discount;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN 0;
    END calculate_discount;

    PROCEDURE fulfill_order(p_order_id IN NUMBER) IS
        PRAGMA AUTONOMOUS_TRANSACTION;  -- independent transaction for audit
        v_order orders%ROWTYPE;
    BEGIN
        SELECT * INTO v_order FROM orders WHERE order_id = p_order_id FOR UPDATE;

        -- Check inventory using BULK COLLECT
        FOR item IN (SELECT * FROM order_items WHERE order_id = p_order_id) LOOP
            UPDATE inventory
            SET quantity = quantity - item.quantity
            WHERE product_id = item.product_id
              AND quantity >= item.quantity;

            IF SQL%ROWCOUNT = 0 THEN
                RAISE e_insufficient_inventory;
            END IF;
        END LOOP;

        UPDATE orders SET status = 'FULFILLED', fulfilled_at = SYSTIMESTAMP
        WHERE order_id = p_order_id;

        -- Autonomous transaction: audit log commits independently
        INSERT INTO fulfillment_audit (order_id, action, performed_at)
        VALUES (p_order_id, 'FULFILLED', SYSTIMESTAMP);
        COMMIT;  -- commits only the autonomous transaction

    EXCEPTION
        WHEN e_insufficient_inventory THEN
            ROLLBACK;
            UPDATE orders SET status = 'BACKORDER' WHERE order_id = p_order_id;
            COMMIT;
    END fulfill_order;

END order_processing;
/

