EventBridge with Content-Based Routing import * as cdk from 'aws-cdk-lib';
import * as events from 'aws-cdk-lib/aws-events';
import * as targets from 'aws-cdk-lib/aws-events-targets';
import * as lambda from 'aws-cdk-lib/aws-lambda';

export class EventRoutingStack extends cdk.Stack {
  constructor(scope: cdk.App, id: string) {
    super(scope, id);

    const bus = new events.EventBus(this, 'AppEventBus', {
      eventBusName: 'ecommerce-events',
    });

    // Route high-value orders to priority processing
    new events.Rule(this, 'HighValueOrderRule', {
      eventBus: bus,
      eventPattern: {
        source: ['ecommerce.orders'],
        detailType: ['OrderCreated'],
        detail: {
          total: [{ numeric: ['>=', 1000] }],
          customerTier: ['premium', 'enterprise'],
        },
      },
      targets: [new targets.LambdaFunction(priorityProcessor)],
    });

    // Route inventory events to warehouse system
    new events.Rule(this, 'InventoryRule', {
      eventBus: bus,
      eventPattern: {
        source: ['ecommerce.inventory'],
        detailType: ['StockLevelChanged'],
        detail: {
          currentStock: [{ numeric: ['<=', 10] }],
        },
      },
      targets: [
        new targets.LambdaFunction(reorderFunction),
        new targets.SqsQueue(warehouseAlertQueue),
      ],
    });

    // Archive all events for replay capability
    new events.Archive(this, 'EventArchive', {
      sourceEventBus: bus,
      eventPattern: { source: [{ prefix: 'ecommerce' }] },
      retention: cdk.Duration.days(90),
    });
  }
}

Serverless API with Lambda Function URLs import { APIGatewayProxyEventV2, APIGatewayProxyResultV2, Context } from 'aws-lambda';

const ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN ?? '*';

function addCorsHeaders(response: APIGatewayProxyResultV2): APIGatewayProxyResultV2 {
  const resp = response as { statusCode: number; headers?: Record<string, string>; body?: string };
  resp.headers = {
    ...resp.headers,
    'Access-Control-Allow-Origin': ALLOWED_ORIGIN,
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
  };
  return resp;
}

type RouteHandler = (event: APIGatewayProxyEventV2, params: Record<string, string>) => APIGatewayProxyResultV2;

const routes: Map<string, RouteHandler> = new Map([
  ['GET /api/products', listProducts],
  ['GET /api/products/{id}', getProduct],
  ['POST /api/products', createProduct],
]);

export const handler = async (
  event: APIGatewayProxyEventV2,
  context: Context
): Promise<APIGatewayProxyResultV2> => {
  // Lambda Function URL handler with path-based routing
  const method = event.requestContext.http.method;
  const path = event.requestContext.http.path;

  if (method === 'OPTIONS') {
    return addCorsHeaders({ statusCode: 204, body: '' });
  }

  for (const [routeKey, handlerFunc] of routes) {
    const [routeMethod, routePath] = routeKey.split(' ');
    if (method === routeMethod && matchPath(path, routePath)) {
      const params = extractParams(path, routePath);
      return addCorsHeaders(handlerFunc(event, params));
    }
  }

  return addCorsHeaders({
    statusCode: 404,
    body: JSON.stringify({ error: 'Not found' }),
    headers: { 'Content-Type': 'application/json' }
  });
};

function matchPath(actual: string, template: string): boolean {
  const actualParts = actual.split('/');
  const templateParts = template.split('/');
  if (actualParts.length !== templateParts.length) return false;
  return templateParts.every((part, i) =>
    part.startsWith('{') || part === actualParts[i]
  );
}

function extractParams(actual: string, template: string): Record<string, string> {
  const params: Record<string, string> = {};
  const actualParts = actual.split('/');
  const templateParts = template.split('/');
  templateParts.forEach((part, i) => {
    if (part.startsWith('{') && part.endsWith('}')) {
      params[part.slice(1, -1)] = actualParts[i];
    }
  });
  return params;
}

VPC with Multi-AZ Subnets Using AWS CDK import * as cdk from 'aws-cdk-lib';
import * as ec2 from 'aws-cdk-lib/aws-ec2';

export class NetworkingStack extends cdk.Stack {
  public readonly vpc: ec2.Vpc;

  constructor(scope: cdk.App, id: string, props?: cdk.StackProps) {
    super(scope, id, props);

    // Production VPC with carefully planned CIDR
    this.vpc = new ec2.Vpc(this, 'ProductionVpc', {
      vpcName: 'production-vpc',
      ipAddresses: ec2.IpAddresses.cidr('10.0.0.0/16'), // 65,536 IPs
      maxAzs: 3,
      natGateways: 2, // Cost optimization: 2 NATs for 3 AZs

      subnetConfiguration: [
        {
          name: 'Public',
          subnetType: ec2.SubnetType.PUBLIC,
          cidrMask: 24, // 256 IPs per AZ for load balancers, NAT GWs
          mapPublicIpOnLaunch: false, // Explicit control over public IPs
        },
        {
          name: 'Application',
          subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS,
          cidrMask: 20, // 4,096 IPs per AZ for application workloads
        },
        {
          name: 'Database',
          subnetType: ec2.SubnetType.PRIVATE_ISOLATED,
          cidrMask: 22, // 1,024 IPs per AZ for databases
        },
      ],

      flowLogs: {
        'vpc-flow-logs': {
          destination: ec2.FlowLogDestination.toCloudWatchLogs(),
          trafficType: ec2.FlowLogTrafficType.ALL,
        },
      },
    });

    // VPC Endpoints for AWS service access without NAT Gateway costs
    this.vpc.addGatewayEndpoint('S3Endpoint', {
      service: ec2.GatewayVpcEndpointAwsService.S3,
      subnets: [{ subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS }],
    });

    this.vpc.addGatewayEndpoint('DynamoDBEndpoint', {
      service: ec2.GatewayVpcEndpointAwsService.DYNAMODB,
    });

    this.vpc.addInterfaceEndpoint('EcrEndpoint', {
      service: ec2.InterfaceVpcEndpointAwsService.ECR,
      privateDnsEnabled: true,
      subnets: { subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS },
    });

    this.vpc.addInterfaceEndpoint('EcrDockerEndpoint', {
      service: ec2.InterfaceVpcEndpointAwsService.ECR_DOCKER,
      privateDnsEnabled: true,
      subnets: { subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS },
    });

    this.vpc.addInterfaceEndpoint('CloudWatchLogsEndpoint', {
      service: ec2.InterfaceVpcEndpointAwsService.CLOUDWATCH_LOGS,
      privateDnsEnabled: true,
      subnets: { subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS },
    });
  }
}

Security Groups with Layered Access Control import * as ec2 from 'aws-cdk-lib/aws-ec2';

// ALB Security Group - accepts traffic from the internet
const albSecurityGroup = new ec2.SecurityGroup(this, 'AlbSg', {
  vpc,
  securityGroupName: 'alb-sg',
  description: 'Security group for Application Load Balancer',
  allowAllOutbound: false,
});
albSecurityGroup.addIngressRule(
  ec2.Peer.anyIpv4(),
  ec2.Port.tcp(443),
  'Allow HTTPS from internet'
);
albSecurityGroup.addEgressRule(
  ec2.Peer.anyIpv4(),
  ec2.Port.tcp(443),
  'Allow outbound HTTPS'
);

// Application Security Group - accepts traffic only from ALB
const appSecurityGroup = new ec2.SecurityGroup(this, 'AppSg', {
  vpc,
  securityGroupName: 'app-sg',
  description: 'Security group for application containers',
  allowAllOutbound: false,
});
appSecurityGroup.addIngressRule(
  albSecurityGroup,
  ec2.Port.tcp(8080),
  'Allow traffic from ALB only'
);
appSecurityGroup.addEgressRule(
  ec2.Peer.anyIpv4(),
  ec2.Port.tcp(443),
  'Allow outbound HTTPS for AWS API calls'
);

// Database Security Group - accepts traffic only from application tier
const dbSecurityGroup = new ec2.SecurityGroup(this, 'DbSg', {
  vpc,
  securityGroupName: 'db-sg',
  description: 'Security group for RDS instances',
  allowAllOutbound: false,
});
dbSecurityGroup.addIngressRule(
  appSecurityGroup,
  ec2.Port.tcp(5432),
  'Allow PostgreSQL from application tier only'
);
// No egress rules - database should not initiate outbound connections

Network ACLs for Subnet-Level Protection // NACL for database subnets - defense in depth beyond security groups
const dbNacl = new ec2.NetworkAcl(this, 'DatabaseNacl', {
  vpc,
  networkAclName: 'database-nacl',
  subnetSelection: { subnetType: ec2.SubnetType.PRIVATE_ISOLATED },
});

// Allow inbound PostgreSQL only from application subnets
dbNacl.addEntry('AllowPostgresInbound', {
  ruleNumber: 100,
  cidr: ec2.AclCidr.ipv4('10.0.16.0/20'), // Application subnet CIDR
  traffic: ec2.AclTraffic.tcpPort(5432),
  direction: ec2.TrafficDirection.INGRESS,
  ruleAction: ec2.Action.ALLOW,
});

// Allow ephemeral port responses back to application subnets
dbNacl.addEntry('AllowEphemeralOutbound', {
  ruleNumber: 100,
  cidr: ec2.AclCidr.ipv4('10.0.16.0/20'),
  traffic: ec2.AclTraffic.tcpPortRange(1024, 65535),
  direction: ec2.TrafficDirection.EGRESS,
  ruleAction: ec2.Action.ALLOW,
});

// Explicit deny all other traffic (NACLs have implicit deny, but explicit is clearer)
dbNacl.addEntry('DenyAllInbound', {
  ruleNumber: 200,
  cidr: ec2.AclCidr.anyIpv4(),
  traffic: ec2.AclTraffic.allTraffic(),
  direction: ec2.TrafficDirection.INGRESS,
  ruleAction: ec2.Action.DENY,
});

Jenkins Declarative Pipeline // Jenkinsfile - Declarative pipeline
pipeline {
    agent {
        kubernetes {
            yaml '''
                apiVersion: v1
                kind: Pod
                spec:
                  containers:
                  - name: gradle
                    image: gradle:8.4-jdk17
                    command: ['sleep', '99d']
                  - name: docker
                    image: docker:24
                    command: ['sleep', '99d']
                    volumeMounts:
                    - name: docker-sock
                      mountPath: /var/run/docker.sock
                  volumes:
                  - name: docker-sock
                    hostPath:
                      path: /var/run/docker.sock
            '''
        }
    }

    environment {
        DOCKER_REGISTRY = 'registry.example.com'
        IMAGE_NAME = "${DOCKER_REGISTRY}/app:${env.BUILD_NUMBER}"
        GRADLE_OPTS = '-Dorg.gradle.daemon=false'
    }

    options {
        timeout(time: 30, unit: 'MINUTES')
        disableConcurrentBuilds()
        buildDiscarder(logRotator(numToKeepStr: '10'))
    }

    stages {
        stage('Build') {
            steps {
                container('gradle') {
                    sh 'gradle assemble --no-daemon'
                }
            }
        }

        stage('Test') {
            parallel {
                stage('Unit Tests') {
                    steps {
                        container('gradle') {
                            sh 'gradle test --no-daemon'
                        }
                    }
                    post {
                        always {
                            junit 'build/test-results/test/*.xml'
                        }
                    }
                }
                stage('Integration Tests') {
                    steps {
                        container('gradle') {
                            sh 'gradle integrationTest --no-daemon'
                        }
                    }
                }
            }
        }

        stage('Package') {
            steps {
                container('docker') {
                    sh "docker build -t ${IMAGE_NAME} ."
                    sh "docker push ${IMAGE_NAME}"
                }
            }
        }

        stage('Deploy Staging') {
            when {
                branch 'main'
            }
            steps {
                sh "kubectl set image deployment/app app=${IMAGE_NAME} -n staging"
                sh "kubectl rollout status deployment/app -n staging --timeout=300s"
            }
        }

        stage('Deploy Production') {
            when {
                branch 'main'
            }
            input {
                message 'Deploy to production?'
                ok 'Deploy'
                submitter 'admin,release-team'
            }
            steps {
                sh "kubectl set image deployment/app app=${IMAGE_NAME} -n production"
                sh "kubectl rollout status deployment/app -n production --timeout=300s"
            }
        }
    }

    post {
        success {
            slackSend(channel: '#deployments', message: "Build ${env.BUILD_NUMBER} succeeded")
        }
        failure {
            slackSend(channel: '#deployments', color: 'danger',
                      message: "Build ${env.BUILD_NUMBER} failed: ${env.BUILD_URL}")
        }
        always {
            cleanWs()
        }
    }
}

Terraform: Production VPC with Multi-AZ Subnets # modules/vpc/main.tf
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  type        = string
  description = "Environment name (dev, staging, prod)"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "availability_zones" {
  type    = list(string)
  default = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

locals {
  public_subnets  = [for i, az in var.availability_zones : cidrsubnet(var.vpc_cidr, 8, i)]
  private_subnets = [for i, az in var.availability_zones : cidrsubnet(var.vpc_cidr, 8, i + 10)]
  db_subnets      = [for i, az in var.availability_zones : cidrsubnet(var.vpc_cidr, 8, i + 20)]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "${var.environment}-vpc"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.availability_zones)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnets[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-${var.availability_zones[count.index]}"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.availability_zones)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = {
    Name = "${var.environment}-private-${var.availability_zones[count.index]}"
    Tier = "private"
  }
}

resource "aws_nat_gateway" "main" {
  count         = length(var.availability_zones)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.environment}-nat-${var.availability_zones[count.index]}"
  }
}

resource "aws_eip" "nat" {
  count  = length(var.availability_zones)
  domain = "vpc"
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

