Anagram Detection and Grouping Anagram problems reduce to character frequency comparison, a pattern that appears in plagiarism detection, spell checkers, and word games. public class Anagrams {
    /**
     * Check if two strings are anagrams using frequency counting.
     * Time: O(n), Space: O(1) for fixed alphabet
     */
    public static boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) return false;

        int[] freq = new int[26];  // Assumes lowercase English
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - 'a']++;
            freq[t.charAt(i) - 'a']--;
        }

        for (int count : freq) {
            if (count != 0) return false;
        }
        return true;
    }

    /**
     * Group anagrams together using sorted string as canonical key.
     * Time: O(n * k log k) where k is max string length
     */
    public static List<List<String>> groupAnagrams(String[] strs) {
        Map<String, List<String>> groups = new HashMap<>();

        for (String s : strs) {
            char[] chars = s.toCharArray();
            Arrays.sort(chars);
            String key = new String(chars);
            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
        }

        return new ArrayList<>(groups.values());
    }
} import java.util.*;

