     * Group anagrams using sorted string as canonical key.
     */
    public static List<List<String>> groupAnagrams(String[] strs) {
        Map<String, List<String>> groups = new HashMap<>();
        for (String s : strs) {
            char[] chars = s.toCharArray();
            Arrays.sort(chars);
            String key = new String(chars);
            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
        }
        return new ArrayList<>(groups.values());
    }

    /**
     * Find all starting indices of pattern's anagrams in text.
     * Uses sliding window with frequency comparison. O(n) time.
     */
    public static List<Integer> findAnagramsInText(String text, String pattern) {
        List<Integer> result = new ArrayList<>();
        int n = text.length(), m = pattern.length();
        if (m > n) return result;

        int[] pCount = new int[26];
        int[] wCount = new int[26];

        for (int i = 0; i < m; i++) {
            pCount[pattern.charAt(i) - 'a']++;
            wCount[text.charAt(i) - 'a']++;
        }

        if (Arrays.equals(pCount, wCount)) result.add(0);

        for (int i = m; i < n; i++) {
            // Add new character to window
            wCount[text.charAt(i) - 'a']++;
            // Remove old character from window
            wCount[text.charAt(i - m) - 'a']--;

            if (Arrays.equals(pCount, wCount)) {
                result.add(i - m + 1);
            }
        }
        return result;
    }
}

Palindrome Operations Palindrome detection and construction using two-pointer and dynamic programming approaches. public class Palindromes {
    /**
     * Check if string is a palindrome using two pointers.
     * Ignores non-alphanumeric characters and case.
     * Time: O(n), Space: O(1)
     */
    public static boolean isPalindrome(String s) {
        int left = 0, right = s.length() - 1;

        while (left < right) {
            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) left++;
            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) right--;

            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

    /**
     * Longest palindromic substring using expand-around-center.
     * Time: O(n^2), Space: O(1)
     */
    public static String longestPalindrome(String s) {
        if (s.length() < 2) return s;

        int start = 0, maxLen = 1;

        for (int i = 0; i < s.length(); i++) {
            // Odd-length palindromes
            int len1 = expandAroundCenter(s, i, i);
            // Even-length palindromes
            int len2 = expandAroundCenter(s, i, i + 1);
            int len = Math.max(len1, len2);

            if (len > maxLen) {
                maxLen = len;
                start = i - (len - 1) / 2;
            }
        }

        return s.substring(start, start + maxLen);
    }

    private static int expandAroundCenter(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }
        return right - left - 1;
    }
}

KMP Algorithm Implementation The KMP algorithm preprocesses the pattern to build a failure function (also called the partial match table or prefix function) that indicates how far back to reset the pattern pointer on a mismatch, avoiding redundant comparisons. public class KMP {
    /**
     * Builds the failure function (longest proper prefix-suffix array).
     * failure[i] = length of longest proper prefix of pattern[0..i]
     * that is also a suffix of pattern[0..i].
     * Time: O(m), Space: O(m)
     */
    public static int[] buildFailureFunction(String pattern) {
        int m = pattern.length();
        int[] failure = new int[m];
        failure[0] = 0;
        int len = 0;  // Length of previous longest prefix-suffix
        int i = 1;

        while (i < m) {
            if (pattern.charAt(i) == pattern.charAt(len)) {
                len++;
                failure[i] = len;
                i++;
            } else {
                if (len != 0) {
                    len = failure[len - 1];  // Fall back, don't increment i
                } else {
                    failure[i] = 0;
                    i++;
                }
            }
        }
        return failure;
    }

    /**
     * Finds all occurrences of pattern in text using KMP.
     * Returns list of starting indices.
     * Time: O(n + m), Space: O(m)
     */
    public static List<Integer> search(String text, String pattern) {
        List<Integer> result = new ArrayList<>();
        if (pattern.isEmpty()) return result;

        int[] failure = buildFailureFunction(pattern);
        int n = text.length(), m = pattern.length();
        int i = 0, j = 0;  // i for text, j for pattern

        while (i < n) {
            if (text.charAt(i) == pattern.charAt(j)) {
                i++;
                j++;
            }

            if (j == m) {
                result.add(i - j);  // Found match at index i - j
                j = failure[j - 1];  // Continue searching for next occurrence
            } else if (i < n && text.charAt(i) != pattern.charAt(j)) {
                if (j != 0) {
                    j = failure[j - 1];  // Use failure function to skip
                } else {
                    i++;
                }
            }
        }
        return result;
    }
} function buildFailureFunction(pattern: string): number[] {
  const m = pattern.length;
  const failure = new Array(m).fill(0);
  let len = 0;
  let i = 1;

  while (i < m) {
    if (pattern[i] === pattern[len]) {
      len++;
      failure[i] = len;
      i++;
    } else {
      if (len !== 0) {
        len = failure[len - 1];
      } else {
        failure[i] = 0;
        i++;
      }
    }
  }
  return failure;
}

function kmpSearch(text: string, pattern: string): number[] {
  const result: number[] = [];
  if (pattern.length === 0) return result;

  const failure = buildFailureFunction(pattern);
  const n = text.length;
  const m = pattern.length;
  let i = 0;
  let j = 0;

  while (i < n) {
    if (text[i] === pattern[j]) {
      i++;
      j++;
    }

    if (j === m) {
      result.push(i - j);
      j = failure[j - 1];
    } else if (i < n && text[i] !== pattern[j]) {
      if (j !== 0) {
        j = failure[j - 1];
      } else {
        i++;
      }
    }
  }
  return result;
}

Rabin-Karp with Rolling Hash Rabin-Karp uses a rolling hash to compare the pattern hash with substring hashes in O(1) per position. Only when hashes match does it perform a character-by-character verification to handle collisions. public class RabinKarp {
    private static final long MOD = 1_000_000_007L;
    private static final long BASE = 31L;

    /**
     * Finds all occurrences of pattern in text using rolling hash.
     * Average: O(n + m), Worst: O(n * m) due to hash collisions.
     */
    public static List<Integer> search(String text, String pattern) {
        List<Integer> result = new ArrayList<>();
        int n = text.length(), m = pattern.length();
        if (m > n) return result;

        // Compute hash of pattern and first window
        long patternHash = 0, windowHash = 0;
        long highPow = 1;  // BASE^(m-1) mod MOD

        for (int i = 0; i < m; i++) {
            patternHash = (patternHash * BASE + pattern.charAt(i)) % MOD;
            windowHash = (windowHash * BASE + text.charAt(i)) % MOD;
            if (i > 0) highPow = (highPow * BASE) % MOD;
        }

        for (int i = 0; i <= n - m; i++) {
            if (windowHash == patternHash) {
                // Verify character by character (handle collisions)
                if (text.substring(i, i + m).equals(pattern)) {
                    result.add(i);
                }
            }

            // Roll the hash: remove leftmost char, add next char
            if (i < n - m) {
                windowHash = (windowHash - text.charAt(i) * highPow % MOD + MOD) % MOD;
                windowHash = (windowHash * BASE + text.charAt(i + m)) % MOD;
            }
        }
        return result;
    }

    /**
     * Multi-pattern search: find any of the given patterns in text.
     * Useful for dictionary matching, content filtering.
     */
    public static Map<String, List<Integer>> multiSearch(String text, Set<String> patterns) {
        Map<String, List<Integer>> results = new HashMap<>();
        for (String pattern : patterns) {
            List<Integer> matches = search(text, pattern);
            if (!matches.isEmpty()) {
                results.put(pattern, matches);
            }
        }
        return results;
    }
} /**
 * Alternative Rabin-Karp implementation with configurable base and modulus.
 * Demonstrates the rolling hash technique for pattern matching.
 */
public class RabinKarpAlt {
    /**
     * Find all occurrences of pattern in text using rolling hash.
     * @param base hash base (typically a prime like 31)
     * @param mod hash modulus (large prime like 10^9 + 7)
     */
    public static List<Integer> search(String text, String pattern, long base, long mod) {
        int n = text.length(), m = pattern.length();
        if (m > n) return Collections.emptyList();

        List<Integer> result = new ArrayList<>();
        long patternHash = 0, windowHash = 0;
        long highPow = 1;  // base^(m-1) mod mod

        for (int i = 0; i < m; i++) {
            patternHash = (patternHash * base + pattern.charAt(i)) % mod;
            windowHash = (windowHash * base + text.charAt(i)) % mod;
            if (i > 0) highPow = (highPow * base) % mod;
        }

        for (int i = 0; i <= n - m; i++) {
            if (windowHash == patternHash) {
                // Verify character by character on hash match
                if (text.substring(i, i + m).equals(pattern)) {
                    result.add(i);
                }
            }

            if (i < n - m) {
                windowHash = (windowHash - text.charAt(i) * highPow % mod + mod) % mod;
                windowHash = (windowHash * base + text.charAt(i + m)) % mod;
            }
        }
        return result;
    }
}

Z-Algorithm The Z-algorithm computes the Z-array where Z[i] is the length of the longest substring starting at position i that matches a prefix of the string. Concatenating pattern + separator + text allows single-pattern matching. public class ZAlgorithm {
    /**
     * Computes Z-array: Z[i] = length of longest substring starting at i
     * that is also a prefix of the string.
     * Time: O(n), Space: O(n)
     */
    public static int[] computeZArray(String s) {
        int n = s.length();
        int[] z = new int[n];
        int left = 0, right = 0;

        for (int i = 1; i < n; i++) {
            if (i < right) {
                z[i] = Math.min(right - i, z[i - left]);
            }
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) {
                z[i]++;
            }
            if (i + z[i] > right) {
                left = i;
                right = i + z[i];
            }
        }
        return z;
    }

    /**
     * Find all occurrences of pattern in text using Z-algorithm.
     * Concatenate: pattern + "$" + text, then find Z[i] == pattern.length
     */
    public static List<Integer> search(String text, String pattern) {
        String combined = pattern + "$" + text;
        int[] z = computeZArray(combined);
        List<Integer> result = new ArrayList<>();
        int m = pattern.length();

        for (int i = m + 1; i < combined.length(); i++) {
            if (z[i] == m) {
                result.add(i - m - 1);
            }
        }
        return result;
    }
}

Two Sum on Sorted Array The classic two-pointer pattern for finding a pair that sums to a target. Pointers converge from both ends based on whether the current sum is too small or too large. public class TwoPointers {
    /**
     * Finds indices of two numbers in a sorted array that sum to target.
     * Returns [-1, -1] if no such pair exists.
     * Time: O(n), Space: O(1)
     */
    public static int[] twoSum(int[] sorted, int target) {
        int left = 0, right = sorted.length - 1;

        while (left < right) {
            int sum = sorted[left] + sorted[right];
            if (sum == target) {
                return new int[]{left, right};
            } else if (sum < target) {
                left++;   // Need larger sum, move left pointer right
            } else {
                right--;  // Need smaller sum, move right pointer left
            }
        }

        return new int[]{-1, -1};
    }

    /**
     * Three-sum: find all unique triplets that sum to zero.
     * Fix one element, then use two-pointer on the remainder.
     * Time: O(n^2), Space: O(1) excluding output
     */
    public static List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> result = new ArrayList<>();

        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue; // Skip duplicates

            int left = i + 1, right = nums.length - 1;
            while (left < right) {
                int sum = nums[i] + nums[left] + nums[right];
                if (sum == 0) {
                    result.add(Arrays.asList(nums[i], nums[left], nums[right]));
                    while (left < right && nums[left] == nums[left + 1]) left++;
                    while (left < right && nums[right] == nums[right - 1]) right--;
                    left++;
                    right--;
                } else if (sum < 0) {
                    left++;
                } else {
                    right--;
                }
            }
        }
        return result;
    }
} function twoSum(sorted: number[], target: number): [number, number] | null {
  let left = 0;
  let right = sorted.length - 1;

  while (left < right) {
    const sum = sorted[left] + sorted[right];
    if (sum === target) return [left, right];
    if (sum < target) left++;
    else right--;
  }

  return null;
}

function threeSum(nums: number[]): number[][] {
  nums.sort((a, b) => a - b);
  const result: number[][] = [];

  for (let i = 0; i < nums.length - 2; i++) {
    if (i > 0 && nums[i] === nums[i - 1]) continue;

    let left = i + 1;
    let right = nums.length - 1;

    while (left < right) {
      const sum = nums[i] + nums[left] + nums[right];
      if (sum === 0) {
        result.push([nums[i], nums[left], nums[right]]);
        while (left < right && nums[left] === nums[left + 1]) left++;
        while (left < right && nums[right] === nums[right - 1]) right--;
        left++;
        right--;
      } else if (sum < 0) left++;
      else right--;
    }
  }

  return result;
}

Fixed-Size Sliding Window Compute the maximum sum of any contiguous subarray of size k. The window slides one position at a time, adding the new element and removing the old one. public class SlidingWindow {
    /**
     * Maximum sum of any subarray of exactly size k.
     * Time: O(n), Space: O(1)
     */
    public static int maxSumSubarray(int[] arr, int k) {
        if (arr.length < k) throw new IllegalArgumentException("Array smaller than window");

        int windowSum = 0;
        for (int i = 0; i < k; i++) {
            windowSum += arr[i];
        }

        int maxSum = windowSum;
        for (int i = k; i < arr.length; i++) {
            windowSum += arr[i] - arr[i - k];  // Slide: add new, remove old
            maxSum = Math.max(maxSum, windowSum);
        }

        return maxSum;
    }
}

Variable-Size Sliding Window Find the length of the longest substring without repeating characters. The window expands right and shrinks left when a duplicate is found. public class VariableWindow {
    /**
     * Longest substring without repeating characters.
     * Time: O(n), Space: O(min(n, alphabet_size))
     */
    public static int lengthOfLongestSubstring(String s) {
        Map<Character, Integer> lastSeen = new HashMap<>();
        int maxLen = 0;
        int left = 0;

        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (lastSeen.containsKey(c) && lastSeen.get(c) >= left) {
                left = lastSeen.get(c) + 1;  // Shrink window past duplicate
            }
            lastSeen.put(c, right);
            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }

    /**
     * Minimum window substring: smallest window in s containing all chars of t.
     * Time: O(n), Space: O(t.length)
     */
    public static String minWindow(String s, String t) {
        Map<Character, Integer> need = new HashMap<>();
        for (char c : t.toCharArray()) need.merge(c, 1, Integer::sum);

        int have = 0, required = need.size();
        int left = 0, minLen = Integer.MAX_VALUE, minStart = 0;
        Map<Character, Integer> window = new HashMap<>();

        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            window.merge(c, 1, Integer::sum);

            if (need.containsKey(c) && window.get(c).equals(need.get(c))) {
                have++;
            }

            while (have == required) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    minStart = left;
                }
                char leftChar = s.charAt(left);
                window.merge(leftChar, -1, Integer::sum);
                if (need.containsKey(leftChar) && window.get(leftChar) < need.get(leftChar)) {
                    have--;
                }
                left++;
            }
        }

        return minLen == Integer.MAX_VALUE ? "" : s.substring(minStart, minStart + minLen);
    }
} /**
 * Alternative sliding window implementations demonstrating
 * the variable-size window pattern with different constraints.
 */
public class VariableWindowAlt {
    /**
     * Longest substring without repeating characters. O(n) time.
     * Uses array-based tracking for ASCII characters.
     */
    public static int lengthOfLongestSubstring(String s) {
        int[] lastSeen = new int[128]; // ASCII
        Arrays.fill(lastSeen, -1);
        int maxLen = 0, left = 0;

        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (lastSeen[c] >= left) {
                left = lastSeen[c] + 1;
            }
            lastSeen[c] = right;
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }

    /**
     * Minimum window substring containing all characters of t.
     * Time: O(n), Space: O(t.length())
     */
    public static String minWindow(String s, String t) {
        if (s.isEmpty() || t.isEmpty()) return "";

        Map<Character, Integer> need = new HashMap<>();
        for (char c : t.toCharArray()) need.merge(c, 1, Integer::sum);

        int have = 0, required = need.size();
        int left = 0, minLen = Integer.MAX_VALUE, minStart = 0;
        Map<Character, Integer> window = new HashMap<>();

        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            window.merge(c, 1, Integer::sum);

            if (need.containsKey(c) && window.get(c).equals(need.get(c))) {
                have++;
            }

            while (have == required) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    minStart = left;
                }
                char leftChar = s.charAt(left);
                window.merge(leftChar, -1, Integer::sum);
                if (need.containsKey(leftChar) && window.get(leftChar) < need.get(leftChar)) {
                    have--;
                }
                left++;
            }
        }

        return minLen == Integer.MAX_VALUE ? "" : s.substring(minStart, minStart + minLen);
    }
}

Interval DP: Burst Balloons The burst balloons problem demonstrates interval DP where you choose which element to process last within each interval, building the solution from smaller intervals. public class IntervalDP {
    /**
     * Burst Balloons: maximize coins from bursting all balloons.
     * Key insight: think about which balloon to burst LAST in interval [i,j].
     * dp[i][j] = max coins from bursting all balloons between i and j.
     * Time: O(n³), Space: O(n²)
     */
    public static int maxCoins(int[] nums) {
        int n = nums.length;
        // Pad with 1s on both ends for boundary handling
        int[] padded = new int[n + 2];
        padded[0] = padded[n + 1] = 1;
        System.arraycopy(nums, 0, padded, 1, n);

        int[][] dp = new int[n + 2][n + 2];

        // Fill by increasing interval length
        for (int len = 1; len <= n; len++) {
            for (int left = 1; left <= n - len + 1; left++) {
                int right = left + len - 1;
                for (int last = left; last <= right; last++) {
                    // Burst 'last' balloon last in interval [left, right]
                    int coins = padded[left - 1] * padded[last] * padded[right + 1]
                        + dp[left][last - 1] + dp[last + 1][right];
                    dp[left][right] = Math.max(dp[left][right], coins);
                }
            }
        }
        return dp[1][n];
    }

    /**
     * Palindrome Partitioning: minimum cuts to partition string into palindromes.
     * Combine palindrome checking DP with partition DP.
     * Time: O(n²), Space: O(n²)
     */
    public static int minCut(String s) {
        int n = s.length();
        // isPalin[i][j] = true if s[i..j] is a palindrome
        boolean[][] isPalin = new boolean[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                isPalin[i][j] = s.charAt(i) == s.charAt(j)
                    && (j - i <= 2 || isPalin[i + 1][j - 1]);
            }
        }

        // dp[i] = minimum cuts for s[0..i]
        int[] dp = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE);

        for (int i = 0; i < n; i++) {
            if (isPalin[0][i]) {
                dp[i] = 0;  // Entire prefix is palindrome, no cuts needed
            } else {
                for (int j = 1; j <= i; j++) {
                    if (isPalin[j][i]) {
                        dp[i] = Math.min(dp[i], dp[j - 1] + 1);
                    }
                }
            }
        }
        return dp[n - 1];
    }
} function maxCoins(nums: number[]): number {
  const n = nums.length;
  const padded = [1, ...nums, 1];
  const dp: number[][] = Array.from({ length: n + 2 }, () => new Array(n + 2).fill(0));

  for (let len = 1; len <= n; len++) {
    for (let left = 1; left <= n - len + 1; left++) {
      const right = left + len - 1;
      for (let last = left; last <= right; last++) {
        const coins = padded[left - 1] * padded[last] * padded[right + 1]
          + dp[left][last - 1] + dp[last + 1][right];
        dp[left][right] = Math.max(dp[left][right], coins);
      }
    }
  }
  return dp[1][n];
}

Bitmask DP: Traveling Salesman Problem Bitmask DP tracks which elements have been visited using a bitmask, enabling efficient subset enumeration for problems with small n. public class BitmaskDP {
    /**
     * Traveling Salesman Problem: minimum cost to visit all cities and return.
     * State: (current city, set of visited cities as bitmask)
     * dp[mask][i] = min cost to visit cities in mask, ending at city i.
     * Time: O(2^n * n²), Space: O(2^n * n)
     */
    public static int tsp(int[][] dist) {
        int n = dist.length;
        int fullMask = (1 << n) - 1;
        int[][] dp = new int[1 << n][n];
        for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE / 2);

        dp[1][0] = 0;  // Start at city 0, only city 0 visited

        for (int mask = 1; mask <= fullMask; mask++) {
            for (int u = 0; u < n; u++) {
                if ((mask & (1 << u)) == 0) continue;  // u not in mask
                if (dp[mask][u] == Integer.MAX_VALUE / 2) continue;

                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) != 0) continue;  // v already visited
                    int newMask = mask | (1 << v);
                    dp[newMask][v] = Math.min(dp[newMask][v],
                        dp[mask][u] + dist[u][v]);
                }
            }
        }

        // Find minimum cost to return to start after visiting all cities
        int minCost = Integer.MAX_VALUE;
        for (int u = 1; u < n; u++) {
            if (dp[fullMask][u] + dist[u][0] < minCost) {
                minCost = dp[fullMask][u] + dist[u][0];
            }
        }
        return minCost;
    }

    /**
     * Count Hamiltonian paths: number of paths visiting all vertices exactly once.
     * Similar structure to TSP but counting instead of minimizing.
     */
    public static int countHamiltonianPaths(boolean[][] adj) {
        int n = adj.length;
        int[][] dp = new int[1 << n][n];

        // Base: single vertex paths
        for (int i = 0; i < n; i++) dp[1 << i][i] = 1;

        for (int mask = 1; mask < (1 << n); mask++) {
            for (int u = 0; u < n; u++) {
                if ((mask & (1 << u)) == 0 || dp[mask][u] == 0) continue;
                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) != 0 || !adj[u][v]) continue;
                    dp[mask | (1 << v)][v] += dp[mask][u];
                }
            }
        }

        int count = 0;
        int fullMask = (1 << n) - 1;
        for (int i = 0; i < n; i++) count += dp[fullMask][i];
        return count;
    }
}

DP on Trees: Maximum Independent Set Tree DP computes answers bottom-up from leaves to root, where each node's answer depends on its children's answers. public class TreeDP {
    /**
     * Maximum Independent Set on a tree.
     * Select maximum-weight subset of vertices with no two adjacent.
     * dp[v][0] = max weight not including v
     * dp[v][1] = max weight including v
     * Time: O(n), Space: O(n)
     */
    public static int maxIndependentSet(List<List<Integer>> tree, int[] weights, int root) {
        int n = weights.length;
        int[][] dp = new int[n][2];
        boolean[] visited = new boolean[n];

        dfs(tree, weights, root, dp, visited);
        return Math.max(dp[root][0], dp[root][1]);
    }

    private static void dfs(List<List<Integer>> tree, int[] weights,
                            int v, int[][] dp, boolean[] visited) {
        visited[v] = true;
        dp[v][1] = weights[v];  // Include v: start with its weight

        for (int child : tree.get(v)) {
            if (visited[child]) continue;
            dfs(tree, weights, child, dp, visited);

            // If v not included, children can be included or not
            dp[v][0] += Math.max(dp[child][0], dp[child][1]);
            // If v included, children must not be included
            dp[v][1] += dp[child][0];
        }
    }

    /**
     * Tree Diameter: longest path between any two nodes.
     * At each node, track the two longest paths through children.
     * Time: O(n)
     */
    public static int treeDiameter(List<List<Integer>> tree, int root) {
        int[] diameter = {0};
        dfsDepth(tree, root, -1, diameter);
        return diameter[0];
    }

    private static int dfsDepth(List<List<Integer>> tree, int v, int parent, int[] diameter) {
        int maxDepth1 = 0, maxDepth2 = 0;  // Two longest paths through children

        for (int child : tree.get(v)) {
            if (child == parent) continue;
            int childDepth = 1 + dfsDepth(tree, child, v, diameter);

            if (childDepth > maxDepth1) {
                maxDepth2 = maxDepth1;
                maxDepth1 = childDepth;
            } else if (childDepth > maxDepth2) {
                maxDepth2 = childDepth;
            }
        }

        // Diameter through v = sum of two longest paths
        diameter[0] = Math.max(diameter[0], maxDepth1 + maxDepth2);
        return maxDepth1;  // Return longest single path for parent's computation
    }
} /**
 * Maximum weight independent set on a tree using DFS-based tree DP.
 * dp[v][0] = max weight excluding vertex v
 * dp[v][1] = max weight including vertex v
 * Time: O(n)
 */
public class MaxIndependentSet {
    private int[][] dp;
    private List<List<Integer>> tree;
    private int[] weights;

    public int solve(List<List<Integer>> tree, int[] weights, int root) {
        int n = weights.length;
        this.dp = new int[n][2];
        this.tree = tree;
        this.weights = weights;

        dfs(root, -1);
        return Math.max(dp[root][0], dp[root][1]);
    }

    private void dfs(int v, int parent) {
        dp[v][1] = weights[v];
        for (int child : tree.get(v)) {
            if (child == parent) continue;
            dfs(child, v);
            dp[v][0] += Math.max(dp[child][0], dp[child][1]);
            dp[v][1] += dp[child][0];
        }
    }
}

Memoization vs Tabulation Comparison Demonstrating both approaches on the classic Fibonacci problem, showing the trade-offs between recursive elegance and iterative efficiency. public class DPFundamentals {
    /**
     * Top-down (memoization): natural recursive structure with caching.
     * Pros: only computes needed subproblems, natural problem decomposition.
     * Cons: recursion overhead, potential stack overflow for large n.
     */
    public static long fibMemo(int n) {
        return fibMemoHelper(n, new HashMap<>());
    }

    private static long fibMemoHelper(int n, Map<Integer, Long> memo) {
        if (n <= 1) return n;
        if (memo.containsKey(n)) return memo.get(n);
        long result = fibMemoHelper(n - 1, memo) + fibMemoHelper(n - 2, memo);
        memo.put(n, result);
        return result;
    }

    /**
     * Bottom-up (tabulation): iterative, fills table from base cases.
     * Pros: no recursion overhead, better cache locality, easy to optimize space.
     * Cons: computes all subproblems even if not all needed.
     */
    public static long fibTabulation(int n) {
        if (n <= 1) return n;
        long[] dp = new long[n + 1];
        dp[0] = 0;
        dp[1] = 1;
        for (int i = 2; i <= n; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }
        return dp[n];
    }

    /**
     * Space-optimized: only need previous two values.
     * O(n) time, O(1) space.
     */
    public static long fibOptimized(int n) {
        if (n <= 1) return n;
        long prev2 = 0, prev1 = 1;
        for (int i = 2; i <= n; i++) {
            long curr = prev1 + prev2;
            prev2 = prev1;
            prev1 = curr;
        }
        return prev1;
    }
} // Top-down with memoization
function fibMemo(n: number, memo: Map<number, number> = new Map()): number {
  if (n <= 1) return n;
  if (memo.has(n)) return memo.get(n)!;
  const result = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, result);
  return result;
}

// Bottom-up with tabulation
function fibTab(n: number): number {
  if (n <= 1) return n;
  const dp = new Array(n + 1);
  dp[0] = 0;
  dp[1] = 1;
  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }
  return dp[n];
}

// Space-optimized
function fibOptimal(n: number): number {
  if (n <= 1) return n;
  let prev2 = 0, prev1 = 1;
  for (let i = 2; i <= n; i++) {
    const curr = prev1 + prev2;
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}

House Robber Pattern (Non-Adjacent Selection) The house robber pattern appears whenever you must select elements from a sequence with the constraint that no two selected elements are adjacent. public class HouseRobber {
    /**
     * Maximum sum of non-adjacent elements.
     * dp[i] = max(dp[i-1], dp[i-2] + nums[i])
     * Either skip current house (take dp[i-1]) or rob it (dp[i-2] + nums[i]).
     * Time: O(n), Space: O(1)
     */
    public static int rob(int[] nums) {
        if (nums.length == 0) return 0;
        if (nums.length == 1) return nums[0];

        int prev2 = 0;  // dp[i-2]
        int prev1 = 0;  // dp[i-1]

        for (int num : nums) {
            int curr = Math.max(prev1, prev2 + num);
            prev2 = prev1;
            prev1 = curr;
        }
        return prev1;
    }

    /**
     * House Robber II: houses arranged in a circle.
     * Cannot rob both first and last house.
     * Solution: max(rob(0..n-2), rob(1..n-1))
     */
    public static int robCircular(int[] nums) {
        if (nums.length == 1) return nums[0];
        return Math.max(
            robRange(nums, 0, nums.length - 2),
            robRange(nums, 1, nums.length - 1)
        );
    }

    private static int robRange(int[] nums, int start, int end) {
        int prev2 = 0, prev1 = 0;
        for (int i = start; i <= end; i++) {
            int curr = Math.max(prev1, prev2 + nums[i]);
            prev2 = prev1;
            prev1 = curr;
        }
        return prev1;
    }
}

Longest Increasing Subsequence Two approaches: O(n²) basic DP and O(n log n) patience sorting with binary search. public class LIS {
    /**
     * O(n^2) DP approach.
     * dp[i] = length of longest increasing subsequence ending at index i.
     * For each i, check all j < i where nums[j] < nums[i].
     */
    public static int lisQuadratic(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        Arrays.fill(dp, 1);  // Each element is a subsequence of length 1
        int maxLen = 1;

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
            maxLen = Math.max(maxLen, dp[i]);
        }
        return maxLen;
    }

    /**
     * O(n log n) patience sorting approach.
     * Maintain array 'tails' where tails[i] = smallest tail element
     * for increasing subsequence of length i+1.
     * Use binary search to find position for each new element.
     */
    public static int lisOptimal(int[] nums) {
        List<Integer> tails = new ArrayList<>();

        for (int num : nums) {
            int pos = Collections.binarySearch(tails, num);
            if (pos < 0) pos = -(pos + 1);  // Insertion point

            if (pos == tails.size()) {
                tails.add(num);  // Extend longest subsequence
            } else {
                tails.set(pos, num);  // Replace with smaller tail
            }
        }
        return tails.size();
    }
} import java.util.*;

public class LISOptimal {
    /**
     * Longest increasing subsequence in O(n log n) time.
     * Uses patience sorting: maintain tails array where tails[i]
     * is the smallest tail element for increasing subsequence of length i+1.
     */
    public static int lisLength(int[] nums) {
        List<Integer> tails = new ArrayList<>();

        for (int num : nums) {
            int pos = Collections.binarySearch(tails, num);
            if (pos < 0) pos = -(pos + 1); // insertion point
            if (pos == tails.size()) {
                tails.add(num);
            } else {
                tails.set(pos, num);
            }
        }
        return tails.size();
    }

    /**
     * LIS with actual subsequence reconstruction. O(n^2) time.
     */
    public static List<Integer> lisWithReconstruction(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        int[] parent = new int[n];
        Arrays.fill(dp, 1);
        Arrays.fill(parent, -1);

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i] && dp[j] + 1 > dp[i]) {
                    dp[i] = dp[j] + 1;
                    parent[i] = j;
                }
            }
        }

        // Find the index of maximum length
        int maxIdx = 0;
        for (int i = 1; i < n; i++) {
            if (dp[i] > dp[maxIdx]) maxIdx = i;
        }

        // Reconstruct the subsequence
        LinkedList<Integer> result = new LinkedList<>();
        while (maxIdx != -1) {
            result.addFirst(nums[maxIdx]);
            maxIdx = parent[maxIdx];
        }
        return result;
    }
}

Unique Paths and Minimum Path Sum The foundational grid DP problems: counting paths and finding minimum-cost paths through a grid with constrained movement. public class GridDP {
    /**
     * Count unique paths from top-left to bottom-right.
     * Can only move right or down.
     * dp[j] = number of paths to reach cell (current_row, j).
     * Time: O(m*n), Space: O(n)
     */
    public static int uniquePaths(int m, int n) {
        int[] dp = new int[n];
        Arrays.fill(dp, 1);  // First row: only one way (all right moves)

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[j] += dp[j - 1];  // dp[j] (from above) + dp[j-1] (from left)
            }
        }
        return dp[n - 1];
    }

    /**
     * Unique paths with obstacles. Cells with obstacles cannot be traversed.
     * Time: O(m*n), Space: O(n)
     */
    public static int uniquePathsWithObstacles(int[][] grid) {
        int n = grid[0].length;
        int[] dp = new int[n];
        dp[0] = grid[0][0] == 0 ? 1 : 0;

        for (int[] row : grid) {
            for (int j = 0; j < n; j++) {
                if (row[j] == 1) {
                    dp[j] = 0;  // Obstacle: no paths through here
                } else if (j > 0) {
                    dp[j] += dp[j - 1];
                }
            }
        }
        return dp[n - 1];
    }

    /**
     * Minimum path sum from top-left to bottom-right.
     * dp[j] = minimum cost to reach cell (current_row, j).
     * Time: O(m*n), Space: O(n)
     */
    public static int minPathSum(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] dp = new int[n];
        dp[0] = grid[0][0];

        // Initialize first row
        for (int j = 1; j < n; j++) {
            dp[j] = dp[j - 1] + grid[0][j];
        }

        for (int i = 1; i < m; i++) {
            dp[0] += grid[i][0];  // First column: can only come from above
            for (int j = 1; j < n; j++) {
                dp[j] = Math.min(dp[j], dp[j - 1]) + grid[i][j];
            }
        }
        return dp[n - 1];
    }
} function uniquePaths(m: number, n: number): number {
  const dp = new Array(n).fill(1);
  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      dp[j] += dp[j - 1];
    }
  }
  return dp[n - 1];
}

function minPathSum(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  const dp = [...grid[0]];
  for (let j = 1; j < n; j++) dp[j] += dp[j - 1];

  for (let i = 1; i < m; i++) {
    dp[0] += grid[i][0];
    for (let j = 1; j < n; j++) {
      dp[j] = Math.min(dp[j], dp[j - 1]) + grid[i][j];
    }
  }
  return dp[n - 1];
}

Maximal Square in Binary Matrix Finding the largest square containing only 1s in a binary matrix, using the elegant min-of-three-neighbors recurrence. public class MaximalSquare {
    /**
     * Find the area of the largest square of 1s in a binary matrix.
     * dp[j] = side length of largest square with bottom-right corner at (i, j).
     * Recurrence: dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
     * Time: O(m*n), Space: O(n)
     */
    public static int maximalSquare(char[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        int[] dp = new int[n];
        int maxSide = 0;
        int prev = 0;  // Stores dp[i-1][j-1]

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int temp = dp[j];  // Save before overwriting (becomes prev for next j)
                if (matrix[i][j] == '1') {
                    if (i == 0 || j == 0) {
                        dp[j] = 1;
                    } else {
                        dp[j] = Math.min(Math.min(dp[j], dp[j - 1]), prev) + 1;
                    }
                    maxSide = Math.max(maxSide, dp[j]);
                } else {
                    dp[j] = 0;
                }
                prev = temp;
            }
        }
        return maxSide * maxSide;
    }
}

Matrix Chain Multiplication The classic interval DP problem: find the optimal way to parenthesize a chain of matrix multiplications to minimize total scalar multiplications. public class MatrixChain {
    /**
     * Minimum cost to multiply chain of matrices.
     * dimensions[i] = rows of matrix i, dimensions[i+1] = cols of matrix i.
     * dp[i][j] = minimum multiplications to compute product of matrices i..j.
     * Try all split points k: dp[i][j] = min(dp[i][k] + dp[k+1][j] + cost(i,k,j))
     * Time: O(n³), Space: O(n²)
     */
    public static int matrixChainOrder(int[] dimensions) {
        int n = dimensions.length - 1;  // Number of matrices
        int[][] dp = new int[n][n];

        // Fill by increasing chain length
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;

                // Try all split points
                for (int k = i; k < j; k++) {
                    int cost = dp[i][k] + dp[k + 1][j]
                        + dimensions[i] * dimensions[k + 1] * dimensions[j + 1];
                    dp[i][j] = Math.min(dp[i][j], cost);
                }
            }
        }
        return dp[0][n - 1];
    }

    /**
     * With parenthesization reconstruction.
     */
    public static String optimalParenthesization(int[] dimensions) {
        int n = dimensions.length - 1;
        int[][] dp = new int[n][n];
        int[][] split = new int[n][n];

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    int cost = dp[i][k] + dp[k + 1][j]
                        + dimensions[i] * dimensions[k + 1] * dimensions[j + 1];
                    if (cost < dp[i][j]) {
                        dp[i][j] = cost;
                        split[i][j] = k;
                    }
                }
            }
        }

        return buildParens(split, 0, n - 1);
    }

    private static String buildParens(int[][] split, int i, int j) {
        if (i == j) return "M" + i;
        return "(" + buildParens(split, i, split[i][j]) + " × "
            + buildParens(split, split[i][j] + 1, j) + ")";
    }
} public class GridDP {
    /**
     * Minimum path sum from top-left to bottom-right.
     * Space-optimized to O(n) using single row.
     */
    public static int minPathSum(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] dp = new int[n];
        dp[0] = grid[0][0];
        for (int j = 1; j < n; j++) {
            dp[j] = dp[j - 1] + grid[0][j];
        }

        for (int i = 1; i < m; i++) {
            dp[0] += grid[i][0];
            for (int j = 1; j < n; j++) {
                dp[j] = Math.min(dp[j], dp[j - 1]) + grid[i][j];
            }
        }
        return dp[n - 1];
    }

    /**
     * Minimum scalar multiplications for matrix chain.
     * dims[i] x dims[i+1] are dimensions of matrix i.
     * Time: O(n^3), Space: O(n^2)
     */
    public static int matrixChainOrder(int[] dims) {
        int n = dims.length - 1;
        int[][] dp = new int[n][n];

        for (int length = 2; length <= n; length++) {
            for (int i = 0; i <= n - length; i++) {
                int j = i + length - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    int cost = dp[i][k] + dp[k + 1][j]
                        + dims[i] * dims[k + 1] * dims[j + 1];
                    dp[i][j] = Math.min(dp[i][j], cost);
                }
            }
        }
        return dp[0][n - 1];
    }
}

0/1 Knapsack The classic optimization problem: select items to maximize value without exceeding weight capacity, where each item can be used at most once. public class Knapsack {
    /**
     * 0/1 Knapsack: maximize value within weight capacity.
     * dp[w] = maximum value achievable with capacity w.
     * Process items in outer loop, capacity in REVERSE (to prevent reuse).
     * Time: O(n*W), Space: O(W)
     */
    public static int knapsack01(int[] weights, int[] values, int capacity) {
        int[] dp = new int[capacity + 1];

        for (int i = 0; i < weights.length; i++) {
            // Iterate capacity in reverse to ensure each item used at most once
            for (int w = capacity; w >= weights[i]; w--) {
                dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
            }
        }
        return dp[capacity];
    }

    /**
     * 0/1 Knapsack with item selection tracking.
     * Returns both maximum value and selected item indices.
     */
    public static int[] knapsackWithItems(int[] weights, int[] values, int capacity) {
        int n = weights.length;
        int[][] dp = new int[n + 1][capacity + 1];

        for (int i = 1; i <= n; i++) {
            for (int w = 0; w <= capacity; w++) {
                dp[i][w] = dp[i - 1][w];  // Don't take item i
                if (weights[i - 1] <= w) {
                    dp[i][w] = Math.max(dp[i][w],
                        dp[i - 1][w - weights[i - 1]] + values[i - 1]);
                }
            }
        }

        // Backtrack to find selected items
        List<Integer> selected = new ArrayList<>();
        int w = capacity;
        for (int i = n; i > 0; i--) {
            if (dp[i][w] != dp[i - 1][w]) {
                selected.add(i - 1);
                w -= weights[i - 1];
            }
        }
        return selected.stream().mapToInt(Integer::intValue).toArray();
    }
} function knapsack01(weights: number[], values: number[], capacity: number): number {
  const dp = new Array(capacity + 1).fill(0);

  for (let i = 0; i < weights.length; i++) {
    // Reverse iteration prevents using same item twice
    for (let w = capacity; w >= weights[i]; w--) {
      dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
    }
  }
  return dp[capacity];
}

Coin Change Variants Two classic variants: minimum number of coins to make an amount (optimization), and number of ways to make an amount (counting). public class CoinChange {
    /**
     * Minimum coins to make amount (unbounded knapsack variant).
     * dp[i] = minimum coins needed to make amount i.
     * Time: O(coins.length * amount), Space: O(amount)
     */
    public static int minCoins(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);  // Use amount+1 as "infinity"
        dp[0] = 0;

        for (int i = 1; i <= amount; i++) {
            for (int coin : coins) {
                if (coin <= i && dp[i - coin] + 1 < dp[i]) {
                    dp[i] = dp[i - coin] + 1;
                }
            }
        }
        return dp[amount] > amount ? -1 : dp[amount];
    }

    /**
     * Count number of ways to make amount (combinations, not permutations).
     * Outer loop over coins ensures each combination counted once.
     * Time: O(coins.length * amount), Space: O(amount)
     */
    public static int countWays(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        dp[0] = 1;  // One way to make amount 0: use no coins

        // Coins in outer loop = combinations (order doesn't matter)
        for (int coin : coins) {
            for (int i = coin; i <= amount; i++) {
                dp[i] += dp[i - coin];
            }
        }
        return dp[amount];
    }

    /**
     * Count permutations (order matters) — different from combinations.
     * Amount in outer loop allows reordering.
     */
    public static int countPermutations(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        dp[0] = 1;

        // Amount in outer loop = permutations (order matters)
        for (int i = 1; i <= amount; i++) {
            for (int coin : coins) {
                if (coin <= i) {
                    dp[i] += dp[i - coin];
                }
            }
        }
        return dp[amount];
    }
}

Subset Sum and Partition Problems Determining whether a subset exists that sums to a target, and partitioning arrays into equal-sum halves. public class SubsetSum {
    /**
     * Can any subset of nums sum to target?
     * dp[s] = true if some subset sums to s.
     * Time: O(n * target), Space: O(target)
     */
    public static boolean canSum(int[] nums, int target) {
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;

        for (int num : nums) {
            // Reverse to prevent using same element twice
            for (int s = target; s >= num; s--) {
                dp[s] = dp[s] || dp[s - num];
            }
        }
        return dp[target];
    }

    /**
     * Can array be partitioned into two subsets with equal sum?
     * Reduces to: does a subset sum to totalSum / 2?
     */
    public static boolean canPartition(int[] nums) {
        int total = Arrays.stream(nums).sum();
        if (total % 2 != 0) return false;
        return canSum(nums, total / 2);
    }

    /**
     * Target Sum: assign + or - to each number to reach target.
     * Reduces to subset sum: find subset summing to (total + target) / 2.
     * If we assign + to subset P and - to subset N:
     *   P - N = target, P + N = total → P = (total + target) / 2
     */
    public static int findTargetSumWays(int[] nums, int target) {
        int total = Arrays.stream(nums).sum();
        if ((total + target) % 2 != 0 || Math.abs(target) > total) return 0;
        int subsetTarget = (total + target) / 2;

        int[] dp = new int[subsetTarget + 1];
        dp[0] = 1;

        for (int num : nums) {
            for (int s = subsetTarget; s >= num; s--) {
                dp[s] += dp[s - num];
            }
        }
        return dp[subsetTarget];
    }
} public class KnapsackVariants {
    /**
     * Can array be split into two equal-sum subsets?
     * Reduces to subset sum with target = totalSum / 2.
     * Time: O(n * sum/2), Space: O(sum/2)
     */
    public static boolean canPartition(int[] nums) {
        int total = 0;
        for (int num : nums) total += num;
        if (total % 2 != 0) return false;

        int target = total / 2;
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;

        for (int num : nums) {
            for (int s = target; s >= num; s--) {
                dp[s] = dp[s] || dp[s - num];
            }
        }
        return dp[target];
    }

    /**
     * Minimum coins to make amount. Returns -1 if impossible.
     * Unbounded knapsack variant (coins can be reused).
     * Time: O(coins * amount), Space: O(amount)
     */
    public static int minCoins(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= amount; i++) {
            for (int coin : coins) {
                if (coin <= i && dp[i - coin] != Integer.MAX_VALUE) {
                    dp[i] = Math.min(dp[i], dp[i - coin] + 1);
                }
            }
        }
        return dp[amount] == Integer.MAX_VALUE ? -1 : dp[amount];
    }
}

Longest Common Subsequence The foundational 2D DP problem. LCS finds the longest sequence that appears in both strings (not necessarily contiguous). public class LCS {
    /**
     * Longest Common Subsequence length.
     * dp[i][j] = LCS length of first i chars of s1 and first j chars of s2.
     * Time: O(n*m), Space: O(n*m), optimizable to O(min(n,m))
     */
    public static int lcsLength(String s1, String s2) {
        int n = s1.length(), m = s2.length();
        int[][] dp = new int[n + 1][m + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;  // Characters match
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);  // Skip one
                }
            }
        }
        return dp[n][m];
    }

    /**
     * Reconstruct the actual LCS string by backtracking through the table.
     */
    public static String lcsString(String s1, String s2) {
        int n = s1.length(), m = s2.length();
        int[][] dp = new int[n + 1][m + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // Backtrack to find the actual subsequence
        StringBuilder lcs = new StringBuilder();
        int i = n, j = m;
        while (i > 0 && j > 0) {
            if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                lcs.append(s1.charAt(i - 1));
                i--;
                j--;
            } else if (dp[i - 1][j] > dp[i][j - 1]) {
                i--;
            } else {
                j--;
            }
        }
        return lcs.reverse().toString();
    }

    /**
     * Space-optimized LCS using two rows.
     * O(min(n,m)) space.
     */
    public static int lcsOptimized(String s1, String s2) {
        if (s1.length() < s2.length()) { String tmp = s1; s1 = s2; s2 = tmp; }
        int m = s2.length();
        int[] prev = new int[m + 1];
        int[] curr = new int[m + 1];

        for (int i = 1; i <= s1.length(); i++) {
            for (int j = 1; j <= m; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    curr[j] = prev[j - 1] + 1;
                } else {
                    curr[j] = Math.max(prev[j], curr[j - 1]);
                }
            }
            int[] tmp = prev; prev = curr; curr = tmp;
            Arrays.fill(curr, 0);
        }
        return prev[m];
    }
} /**
 * Space-optimized LCS using two rows.
 * Swaps shorter string to inner loop for O(min(n,m)) space.
 */
public class LCSOptimized {
    public static int lcsLength(String s1, String s2) {
        // Ensure s2 is the shorter string for space optimization
        if (s1.length() < s2.length()) {
            String temp = s1; s1 = s2; s2 = temp;
        }

        int m = s2.length();
        int[] prev = new int[m + 1];
        int[] curr = new int[m + 1];

        for (int i = 1; i <= s1.length(); i++) {
            for (int j = 1; j <= m; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    curr[j] = prev[j - 1] + 1;
                } else {
                    curr[j] = Math.max(prev[j], curr[j - 1]);
                }
            }
            int[] temp = prev; prev = curr; curr = new int[m + 1];
        }
        return prev[m];
    }
}

Edit Distance (Levenshtein Distance) Minimum number of operations (insert, delete, replace) to transform one string into another. Foundation for spell checkers and fuzzy matching. public class EditDistance {
    /**
     * Minimum edit distance between two strings.
     * dp[i][j] = min operations to convert s1[0..i-1] to s2[0..j-1].
     * Operations: insert (dp[i][j-1]+1), delete (dp[i-1][j]+1),
     *             replace (dp[i-1][j-1] + (s1[i-1]!=s2[j-1] ? 1 : 0))
     * Time: O(n*m), Space: O(m) with optimization
     */
    public static int minDistance(String s1, String s2) {
        int n = s1.length(), m = s2.length();
        int[] prev = new int[m + 1];
        int[] curr = new int[m + 1];

        // Base case: transforming empty string to s2[0..j-1] requires j insertions
        for (int j = 0; j <= m; j++) prev[j] = j;

        for (int i = 1; i <= n; i++) {
            curr[0] = i;  // Deleting i characters from s1
            for (int j = 1; j <= m; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    curr[j] = prev[j - 1];  // No operation needed
                } else {
                    curr[j] = 1 + Math.min(
                        prev[j - 1],  // Replace
                        Math.min(prev[j], curr[j - 1])  // Delete, Insert
                    );
                }
            }
            int[] tmp = prev; prev = curr; curr = tmp;
        }
        return prev[m];
    }

    /**
     * Edit distance with operation tracking for producing the edit script.
     * Returns the sequence of operations to transform s1 into s2.
     */
    public static List<String> editScript(String s1, String s2) {
        int n = s1.length(), m = s2.length();
        int[][] dp = new int[n + 1][m + 1];

        for (int i = 0; i <= n; i++) dp[i][0] = i;
        for (int j = 0; j <= m; j++) dp[0][j] = j;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    dp[i][j] = 1 + Math.min(dp[i - 1][j - 1],
                        Math.min(dp[i - 1][j], dp[i][j - 1]));
                }
            }
        }

        // Backtrack to produce edit script
        List<String> ops = new ArrayList<>();
        int i = n, j = m;
        while (i > 0 || j > 0) {
            if (i > 0 && j > 0 && s1.charAt(i - 1) == s2.charAt(j - 1)) {
                i--; j--;
            } else if (i > 0 && j > 0 && dp[i][j] == dp[i - 1][j - 1] + 1) {
                ops.add("Replace '" + s1.charAt(i - 1) + "' with '" + s2.charAt(j - 1) + "'");
                i--; j--;
            } else if (j > 0 && dp[i][j] == dp[i][j - 1] + 1) {
                ops.add("Insert '" + s2.charAt(j - 1) + "'");
                j--;
            } else {
                ops.add("Delete '" + s1.charAt(i - 1) + "'");
                i--;
            }
        }
        Collections.reverse(ops);
        return ops;
    }
} function editDistance(s1: string, s2: string): number {
  const n = s1.length, m = s2.length;
  let prev = Array.from({ length: m + 1 }, (_, j) => j);
  let curr = new Array(m + 1).fill(0);

  for (let i = 1; i <= n; i++) {
    curr[0] = i;
    for (let j = 1; j <= m; j++) {
      if (s1[i - 1] === s2[j - 1]) {
        curr[j] = prev[j - 1];
      } else {
        curr[j] = 1 + Math.min(prev[j - 1], prev[j], curr[j - 1]);
      }
    }
    [prev, curr] = [curr, prev];
  }
  return prev[m];
}

Longest Palindromic Subsequence Finding the longest subsequence that reads the same forwards and backwards, using the insight that it equals LCS of the string with its reverse. public class PalindromeDP {
    /**
     * Longest Palindromic Subsequence.
     * dp[i][j] = length of longest palindromic subsequence in s[i..j].
     * If s[i] == s[j]: dp[i][j] = dp[i+1][j-1] + 2
     * Else: dp[i][j] = max(dp[i+1][j], dp[i][j-1])
     * Time: O(n²), Space: O(n) with optimization
     */
    public static int longestPalindromeSubseq(String s) {
        int n = s.length();
        int[] dp = new int[n];
        Arrays.fill(dp, 1);  // Single characters are palindromes of length 1

        for (int i = n - 2; i >= 0; i--) {
            int prev = 0;  // Represents dp[i+1][j-1] from previous iteration
            for (int j = i + 1; j < n; j++) {
                int temp = dp[j];  // Save current dp[j] before overwriting
                if (s.charAt(i) == s.charAt(j)) {
                    dp[j] = prev + 2;
                } else {
                    dp[j] = Math.max(dp[j], dp[j - 1]);
                }
                prev = temp;
            }
        }
        return dp[n - 1];
    }

    /**
     * Minimum insertions to make a string palindrome.
     * Answer = string length - longest palindromic subsequence length.
     */
    public static int minInsertions(String s) {
        return s.length() - longestPalindromeSubseq(s);
    }
}

Example 1: Single Loops void foo(int[] array) {
    int sum = 0;
    int product = 1;
    for (int i = 0; i < array.length; i++) {
        sum += array[i];
    }
    for (int i = 0; i < array.length; i++) {
        product *= array[i];
    }
    System.out.println(sum + ", " + product);
} Explanation and Runtime: The algorithm has two loops, each iterating through the array N times. While there are two separate loops, they don't affect each other in terms of scaling, so the time complexity remains O(N).

Example 2: Nested Loops void printPairs(int[] array) {
    for (int i = 0; i < array.length; i++) {
        for (int j = 0; j < array.length; j++) {
            System.out.println(array[i] + "," + array[j]);
        }
    }
} Explanation and Runtime: The outer loop runs N times, and for each iteration of the outer loop, the inner loop also runs N times. The total number of iterations is N × N, so the overall time complexity is O(N²).

Example 3: Nested Loops (Non-Overlapping Pairs) void printUnorderedPairs(int[] array) {
    for (int i = 0; i < array.length; i++) {
        for (int j = i + 1; j < array.length; j++) {
            System.out.println(array[i] + "," + array[j]);
        }
    }
} Explanation and Runtime: The number of iterations reduces with each step: the outer loop runs N times, and the inner loop runs N-1, N-2, etc. times. The total number of iterations sums up to N(N-1)/2, which simplifies to O(N²).

Example 4: Two Arrays void printUnorderedPairs(int[] arrayA, int[] arrayB) {
    for (int i = 0; i < arrayA.length; i++) {
        for (int j = 0; j < arrayB.length; j++) {
            if (arrayA[i] < arrayB[j]) {
                System.out.println(arrayA[i] + "," + arrayB[j]);
            }
        }
    }
} Explanation and Runtime: If arrayA has a elements and arrayB has b elements, the total number of iterations is a × b. Big O Notation: O(a × b).

Example 5: Constant Work in Nested Loops void printUnorderedPairs(int[] arrayA, int[] arrayB) {
    for (int i = 0; i < arrayA.length; i++) {
        for (int j = 0; j < arrayB.length; j++) {
            for (int k = 0; k < 100000; k++) {
                System.out.println(arrayA[i] + "," + arrayB[j]);
            }
        }
    }
} Explanation and Runtime: The innermost loop runs 100,000 times for each pair, but since the constant factor doesn't depend on the input size, it doesn't affect the overall time complexity. Big O Notation: O(a × b) (constant factors like 100,000 are ignored).

Example 6: Reversing an Array void reverse(int[] array) {
    for (int i = 0; i < array.length / 2; i++) {
        int other = array.length - i - 1;
        int temp = array[i];
        array[i] = array[other];
        array[other] = temp;
    }
} Explanation and Runtime: The algorithm iterates through only half of the array. Since the array has N elements, the number of iterations is N/2, which simplifies to O(N).

Example 9: Recursive Sum of a Binary Tree int sum(Node node) {
    if (node == null) return 0;
    return sum(node.left) + node.value + sum(node.right);
} Explanation: Each node is visited once and the work done per node is constant. O(N).

Example 10: Prime Checking boolean isPrime(int n) {
    for (int x = 2; x * x <= n; x++) {
        if (n % x == 0) return false;
    }
    return true;
} Explanation: The loop checks divisibility up to √n. O(√n).

Example 11: Factorial Calculation int factorial(int n) {
    if (n < 0) return -1;
    else if (n == 0) return 1;
    else return n * factorial(n - 1);
} Explanation: Makes n recursive calls. O(n).

Example 12: String Permutations void permutation(String str) {
    permutation(str, "");
}

void permutation(String str, String prefix) {
    if (str.length() == 0) {
        System.out.println(prefix);
    } else {
        for (int i = 0; i < str.length(); i++) {
            String rem = str.substring(0, i) + str.substring(i + 1);
            permutation(rem, prefix + str.charAt(i));
        }
    }
} Explanation: For a string of length n, there are n! permutations. Each takes O(n) to print. O(n × n!).

Example 13: Fibonacci Calculation int fib(int n) {
    if (n <= 0) return 0;
    else if (n == 1) return 1;
    return fib(n - 1) + fib(n - 2);
} Explanation: Two recursive calls per invocation, growing exponentially. O(2ⁿ).

Example 14: Printing All Fibonacci Numbers void allFib(int n) {
    for (int i = 0; i < n; i++) {
        System.out.println(i + ": " + fib(i));
    }
} Explanation: The total work is dominated by the largest term fib(n), which is O(2ⁿ). O(2ⁿ).

Example 15: Fibonacci Numbers with Memoization void allFib(int n) {
    int[] memo = new int[n + 1];
    for (int i = 0; i < n; i++) {
        System.out.println(i + ": " + fib(i, memo));
    }
}

int fib(int n, int[] memo) {
    if (n <= 0) return 0;
    else if (n == 1) return 1;
    else if (memo[n] > 0) return memo[n];

    memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
    return memo[n];
} Explanation: Each Fibonacci number is calculated only once. Total calls: O(n).

Example 16: Printing Powers of 2 int powersOf2(int n) {
    if (n < 1) {
        return 0;
    } else if (n == 1) {
        System.out.println(1);
        return 1;
    } else {
        int prev = powersOf2(n / 2);
        int curr = prev * 2;
        System.out.println(curr);
        return curr;
    }
} Explanation: The number of times n can be halved until it reaches 1 is log₂(n). O(log n).

Key Concepts Recursive Calls and Stack Space: Each recursive call adds a new frame to the stack. int sum(int n) {
