Basic Hash Table Implementation (Separate Chaining) This implementation demonstrates the core mechanics of a hash table: hashing keys to bucket indices, handling collisions with linked lists, and resizing when the load factor is exceeded. public class HashTable<K, V> {
    private static final int INITIAL_CAPACITY = 16;
    private static final double LOAD_FACTOR = 0.75;

    private LinkedList<Entry<K, V>>[] buckets;
    private int size;

    @SuppressWarnings("unchecked")
    public HashTable() {
        buckets = new LinkedList[INITIAL_CAPACITY];
        for (int i = 0; i < INITIAL_CAPACITY; i++) {
            buckets[i] = new LinkedList<>();
        }
        size = 0;
    }

    public void put(K key, V value) {
        if ((double) size / buckets.length >= LOAD_FACTOR) {
            resize();
        }
        int index = getBucketIndex(key);
        for (Entry<K, V> entry : buckets[index]) {
            if (entry.key.equals(key)) {
                entry.value = value;
                return;
            }
        }
        buckets[index].add(new Entry<>(key, value));
        size++;
    }

    public V get(K key) {
        int index = getBucketIndex(key);
        for (Entry<K, V> entry : buckets[index]) {
            if (entry.key.equals(key)) {
                return entry.value;
            }
        }
        return null;
    }

    private int getBucketIndex(K key) {
        return Math.abs(key.hashCode() % buckets.length);
    }

    @SuppressWarnings("unchecked")
    private void resize() {
        LinkedList<Entry<K, V>>[] oldBuckets = buckets;
        buckets = new LinkedList[oldBuckets.length * 2];
        for (int i = 0; i < buckets.length; i++) {
            buckets[i] = new LinkedList<>();
        }
        size = 0;
        for (LinkedList<Entry<K, V>> bucket : oldBuckets) {
            for (Entry<K, V> entry : bucket) {
                put(entry.key, entry.value);
            }
        }
    }

    private static class Entry<K, V> {
        K key;
        V value;
        Entry(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }
}

Open Addressing with Linear Probing (Python) Open addressing stores all entries directly in the bucket array. When a collision occurs, the algorithm probes subsequent slots until an empty one is found. This approach has better cache locality than chaining but is more sensitive to clustering. /**
 * Linear probing hash table implementation.
 * Uses tombstone markers for lazy deletion.
 */
public class LinearProbingHashTable<K, V> {
    private static final int DEFAULT_CAPACITY = 16;
    private static final double LOAD_FACTOR = 0.7;

    private Object[] keys;
    private Object[] values;
    private boolean[] deleted;
    private int capacity;
    private int size;

    public LinearProbingHashTable() {
        this(DEFAULT_CAPACITY);
    }

    public LinearProbingHashTable(int capacity) {
        this.capacity = capacity;
        this.keys = new Object[capacity];
        this.values = new Object[capacity];
        this.deleted = new boolean[capacity];
        this.size = 0;
    }

    private int hash(K key) {
        return (key.hashCode() & 0x7FFFFFFF) % capacity;
    }

    @SuppressWarnings("unchecked")
    public void put(K key, V value) {
        if (size >= capacity * LOAD_FACTOR) resize();
        int index = hash(key);
        while (keys[index] != null && !deleted[index]) {
            if (keys[index].equals(key)) {
                values[index] = value;
                return;
            }
            index = (index + 1) % capacity;
        }
        keys[index] = key;
        values[index] = value;
        deleted[index] = false;
        size++;
    }

    @SuppressWarnings("unchecked")
    public V get(K key) {
        int index = hash(key);
        while (keys[index] != null || deleted[index]) {
            if (!deleted[index] && keys[index].equals(key)) {
                return (V) values[index];
            }
            index = (index + 1) % capacity;
        }
        return null;
    }

    public boolean delete(K key) {
        int index = hash(key);
        while (keys[index] != null || deleted[index]) {
            if (!deleted[index] && keys[index].equals(key)) {
                deleted[index] = true;
                values[index] = null;
                size--;
                return true;
            }
            index = (index + 1) % capacity;
        }
        return false;
    }

    @SuppressWarnings("unchecked")
    private void resize() {
        Object[] oldKeys = keys;
        Object[] oldValues = values;
        boolean[] oldDeleted = deleted;
        int oldCapacity = capacity;

        capacity *= 2;
        keys = new Object[capacity];
        values = new Object[capacity];
        deleted = new boolean[capacity];
        size = 0;

        for (int i = 0; i < oldCapacity; i++) {
            if (oldKeys[i] != null && !oldDeleted[i]) {
                put((K) oldKeys[i], (V) oldValues[i]);
            }
        }
    }
}

Two-Sum Problem Using Hash Table The classic interview problem demonstrating how hash tables convert an O(n²) brute-force search into O(n) by storing complements. public int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (seen.containsKey(complement)) {
            return new int[]{seen.get(complement), i};
        }
        seen.put(nums[i], i);
    }
    return new int[]{-1, -1};
}

Consistent Hashing (Distributed Systems) Consistent hashing distributes keys across nodes in a ring, minimizing redistribution when nodes are added or removed. This is foundational to distributed caches like Memcached and databases like DynamoDB. import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;

/**
 * Consistent hash ring for distributed systems.
 * Uses virtual nodes to ensure even distribution across physical nodes.
 */
public class ConsistentHashRing {
    private final int virtualNodes;
    private final TreeMap<Long, String> ring = new TreeMap<>();

    public ConsistentHashRing(int virtualNodes) {
        this.virtualNodes = virtualNodes;
    }

    public ConsistentHashRing(List<String> nodes, int virtualNodes) {
        this.virtualNodes = virtualNodes;
        for (String node : nodes) {
            addNode(node);
        }
    }

    private long hash(String key) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(key.getBytes());
            return ((long) (digest[0] & 0xFF) << 24)
                 | ((long) (digest[1] & 0xFF) << 16)
                 | ((long) (digest[2] & 0xFF) << 8)
                 | ((long) (digest[3] & 0xFF));
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public void addNode(String node) {
        for (int i = 0; i < virtualNodes; i++) {
            String virtualKey = node + ":" + i;
            ring.put(hash(virtualKey), node);
        }
    }

    public void removeNode(String node) {
        for (int i = 0; i < virtualNodes; i++) {
            String virtualKey = node + ":" + i;
            ring.remove(hash(virtualKey));
        }
    }

    public String getNode(String key) {
        if (ring.isEmpty()) return null;
        long hashVal = hash(key);
        Map.Entry<Long, String> entry = ring.ceilingEntry(hashVal);
        if (entry == null) {
            entry = ring.firstEntry(); // Wrap around the ring
        }
        return entry.getValue();
    }
}

