Example: public void heapSort(int[] arr) {
    int n = arr.length;

    // Build max heap
    for (int i = n / 2 - 1; i >= 0; i--) {
        heapify(arr, n, i);
    }

    // Extract elements from heap one by one
    for (int i = n - 1; i > 0; i--) {
        // Move current root to end
        int temp = arr[0];
        arr[0] = arr[i];
        arr[i] = temp;

        // Heapify the reduced heap
        heapify(arr, i, 0);
    }
}

void heapify(int[] arr, int n, int i) {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < n && arr[left] > arr[largest]) {
        largest = left;
    }

    if (right < n && arr[right] > arr[largest]) {
        largest = right;
    }

    if (largest != i) {
        int swap = arr[i];
        arr[i] = arr[largest];
        arr[largest] = swap;

        heapify(arr, n, largest);
    }
}

Singly Linked List Implementation A complete singly linked list with insert, delete, search, and reverse operations. This demonstrates the core pointer manipulation patterns that appear in interview problems. public class SinglyLinkedList<T> {
    private Node<T> head;
    private int size;

    private static class Node<T> {
        T data;
        Node<T> next;

        Node(T data) {
            this.data = data;
            this.next = null;
        }
    }

    public void insertAtHead(T data) {
        Node<T> newNode = new Node<>(data);
        newNode.next = head;
        head = newNode;
        size++;
    }

    public void insertAtTail(T data) {
        Node<T> newNode = new Node<>(data);
        if (head == null) {
            head = newNode;
        } else {
            Node<T> current = head;
            while (current.next != null) {
                current = current.next;
            }
            current.next = newNode;
        }
        size++;
    }

    public boolean delete(T data) {
        if (head == null) return false;
        if (head.data.equals(data)) {
            head = head.next;
            size--;
            return true;
        }
        Node<T> current = head;
        while (current.next != null) {
            if (current.next.data.equals(data)) {
                current.next = current.next.next;
                size--;
                return true;
            }
            current = current.next;
        }
        return false;
    }

    public Node<T> reverse() {
        Node<T> prev = null;
        Node<T> current = head;
        while (current != null) {
            Node<T> next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }
        head = prev;
        return head;
    }

    public int size() {
        return size;
    }
}

Doubly Linked List with Sentinel Nodes (Python) Sentinel nodes (dummy head and tail) eliminate edge cases for empty lists and boundary operations. This pattern is used in production implementations like Java's LinkedList and Linux kernel's list_head. /**
 * Doubly linked list with sentinel nodes.
 * Sentinel head and tail eliminate edge cases for boundary operations.
 * Used in production implementations like Java's LinkedList and LRU caches.
 */
public class DoublyLinkedList<T> {
    private static class Node<T> {
        T data;
        Node<T> prev;
        Node<T> next;

        Node(T data) {
            this.data = data;
        }
    }

    private final Node<T> head;  // Sentinel head
    private final Node<T> tail;  // Sentinel tail
    private int size;

    public DoublyLinkedList() {
        head = new Node<>(null);
        tail = new Node<>(null);
        head.next = tail;
        tail.prev = head;
        size = 0;
    }

    /** Insert new node after the given node in O(1). */
    private Node<T> insertAfter(Node<T> node, T data) {
        Node<T> newNode = new Node<>(data);
        newNode.prev = node;
        newNode.next = node.next;
        node.next.prev = newNode;
        node.next = newNode;
        size++;
        return newNode;
    }

    public Node<T> insertAtHead(T data) {
        return insertAfter(head, data);
    }

    public Node<T> insertAtTail(T data) {
        return insertAfter(tail.prev, data);
    }

    /** Remove the given node in O(1). Node must not be a sentinel. */
    public T remove(Node<T> node) {
        if (node == head || node == tail) {
            throw new IllegalArgumentException("Cannot remove sentinel nodes");
        }
        node.prev.next = node.next;
        node.next.prev = node.prev;
        size--;
        return node.data;
    }

    /** Move existing node to front in O(1) — used in LRU caches. */
    public void moveToFront(Node<T> node) {
        remove(node);
        insertAfter(head, node.data);
    }

    public int size() { return size; }
}

Floyd's Cycle Detection Algorithm The tortoise and hare algorithm detects cycles in O(n) time with O(1) space. This is a fundamental linked list technique that appears in many interview problems. public class CycleDetection {
    public boolean hasCycle(ListNode head) {
        if (head == null || head.next == null) return false;
        ListNode slow = head;
        ListNode fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) return true;
        }
        return false;
    }

    public ListNode findCycleStart(ListNode head) {
        ListNode slow = head, fast = head;
        // Phase 1: Detect cycle
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) break;
        }
        if (fast == null || fast.next == null) return null;
        // Phase 2: Find cycle start
        slow = head;
        while (slow != fast) {
            slow = slow.next;
            fast = fast.next;
        }
        return slow;
    }
}

LRU Cache Using Doubly Linked List + Hash Map The combination of a doubly linked list (for O(1) ordering operations) and a hash map (for O(1) key lookup) creates an O(1) LRU cache. This is one of the most common interview problems and a real production pattern. public class LRUCache {
    private final int capacity;
    private final Map<Integer, Node> map;
    private final Node head, tail;  // Sentinels

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.map = new HashMap<>();
        head = new Node(0, 0);
        tail = new Node(0, 0);
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        if (!map.containsKey(key)) return -1;
        Node node = map.get(key);
        removeNode(node);
        addToFront(node);
        return node.value;
    }

    public void put(int key, int value) {
        if (map.containsKey(key)) {
            Node node = map.get(key);
            node.value = value;
            removeNode(node);
            addToFront(node);
        } else {
            if (map.size() == capacity) {
                Node lru = tail.prev;
                removeNode(lru);
                map.remove(lru.key);
            }
            Node newNode = new Node(key, value);
            map.put(key, newNode);
            addToFront(newNode);
        }
    }

    private void addToFront(Node node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    private void removeNode(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private static class Node {
        int key, value;
        Node prev, next;
        Node(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }
}

