    public Backend getBackend() { return backend; }
    public int getWeight() { return weight; }
    public boolean isHealthy() { return healthy; }
}

Consistent Hashing Load Balancer with Virtual Nodes import * as crypto from 'crypto';

interface Backend {
  id: string;
  address: string;
  weight: number;
}

class ConsistentHashBalancer {
  private ring: Map<number, string> = new Map(); // hash -> backendId
  private sortedHashes: number[] = [];
  private backends: Map<string, Backend> = new Map();
  private readonly virtualNodesPerUnit: number;

  constructor(virtualNodesPerUnit: number = 150) {
    this.virtualNodesPerUnit = virtualNodesPerUnit;
  }

  /**
   * Add a backend to the hash ring.
   * Virtual nodes are proportional to weight for weighted distribution.
   */
  addBackend(backend: Backend): void {
    this.backends.set(backend.id, backend);
    const virtualNodes = this.virtualNodesPerUnit * backend.weight;

    for (let i = 0; i < virtualNodes; i++) {
      const hash = this.hash(`${backend.id}:${i}`);
      this.ring.set(hash, backend.id);
    }

    this.rebuildSortedHashes();
  }

  /**
   * Remove a backend from the hash ring.
   * Keys previously routed to this backend will be redistributed
   * to the next backend on the ring (minimal disruption).
   */
  removeBackend(backendId: string): void {
    const backend = this.backends.get(backendId);
    if (!backend) return;

    const virtualNodes = this.virtualNodesPerUnit * backend.weight;
    for (let i = 0; i < virtualNodes; i++) {
      const hash = this.hash(`${backendId}:${i}`);
      this.ring.delete(hash);
    }

    this.backends.delete(backendId);
    this.rebuildSortedHashes();
  }

  /**
   * Route a key to a backend using consistent hashing.
   * The key is hashed and mapped to the next clockwise node on the ring.
   */
  getBackend(key: string): Backend | null {
    if (this.sortedHashes.length === 0) return null;

    const hash = this.hash(key);
    // Binary search for the first hash >= key hash
    let index = this.binarySearchCeil(hash);

    // Wrap around to the first node if past the end
    if (index >= this.sortedHashes.length) {
      index = 0;
    }

    const backendId = this.ring.get(this.sortedHashes[index])!;
    return this.backends.get(backendId) || null;
  }

  /**
   * Get N distinct backends for replication.
   * Walks clockwise from the key's position, skipping duplicate backends.
   */
  getBackends(key: string, count: number): Backend[] {
    if (this.sortedHashes.length === 0) return [];

    const hash = this.hash(key);
    let index = this.binarySearchCeil(hash);
    const result: Backend[] = [];
    const seen = new Set<string>();

    for (let i = 0; i < this.sortedHashes.length && result.length < count; i++) {
      const wrappedIndex = (index + i) % this.sortedHashes.length;
      const backendId = this.ring.get(this.sortedHashes[wrappedIndex])!;

      if (!seen.has(backendId)) {
        seen.add(backendId);
        const backend = this.backends.get(backendId);
        if (backend) result.push(backend);
      }
    }

    return result;
  }

  private hash(key: string): number {
    const md5 = crypto.createHash('md5').update(key).digest();
    return md5.readUInt32BE(0);
  }

  private binarySearchCeil(target: number): number {
    let low = 0;
    let high = this.sortedHashes.length - 1;

    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      if (this.sortedHashes[mid] < target) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    return low;
  }

  private rebuildSortedHashes(): void {
    this.sortedHashes = Array.from(this.ring.keys()).sort((a, b) => a - b);
  }

  getStats(): { backendId: string; keyCount: number; percentage: number }[] {
    const counts = new Map<string, number>();
    // Sample 10000 random keys to estimate distribution
    for (let i = 0; i < 10000; i++) {
      const backend = this.getBackend(`sample-key-${i}`);
      if (backend) {
        counts.set(backend.id, (counts.get(backend.id) || 0) + 1);
      }
    }
    return Array.from(counts.entries()).map(([id, count]) => ({
      backendId: id,
      keyCount: count,
      percentage: (count / 10000) * 100
    }));
  }
}

Health Check System with Circuit Breaking public class HealthChecker {
    private final ScheduledExecutorService scheduler;
    private final Map<String, BackendHealth> healthStates = new ConcurrentHashMap<>();
    private final HealthCheckConfig config;
    private final LoadBalancer loadBalancer;

    public HealthChecker(LoadBalancer loadBalancer, HealthCheckConfig config) {
        this.loadBalancer = loadBalancer;
        this.config = config;
        this.scheduler = Executors.newScheduledThreadPool(4);
    }

    public void startMonitoring(List<Backend> backends) {
        for (Backend backend : backends) {
            healthStates.put(backend.getId(), new BackendHealth(backend));
            scheduler.scheduleAtFixedRate(
                () -> checkHealth(backend),
                0,
                config.getCheckInterval().toMillis(),
                TimeUnit.MILLISECONDS
            );
        }
    }

    private void checkHealth(Backend backend) {
        BackendHealth health = healthStates.get(backend.getId());

        try {
            HttpResponse response = sendHealthProbe(backend);
            long latency = response.getLatencyMs();

            if (response.getStatusCode() == 200 && latency < config.getLatencyThreshold()) {
                health.recordSuccess(latency);
                if (!health.isHealthy() && health.getConsecutiveSuccesses()
                        >= config.getHealthyThreshold()) {
                    // Backend recovered: add back to rotation
                    health.markHealthy();
                    loadBalancer.addBackend(backend);
                    logEvent("Backend recovered", backend, health);
                }
            } else {
                health.recordFailure(response.getStatusCode(), latency);
                handleFailure(backend, health);
            }
        } catch (Exception e) {
            health.recordFailure(-1, -1);
            handleFailure(backend, health);
        }
    }

    private void handleFailure(Backend backend, BackendHealth health) {
        if (health.isHealthy() && health.getConsecutiveFailures()
                >= config.getUnhealthyThreshold()) {
            // Backend failed: remove from rotation
            health.markUnhealthy();
            loadBalancer.removeBackend(backend);
            logEvent("Backend removed", backend, health);
        }
    }

    private HttpResponse sendHealthProbe(Backend backend) {
        // Send HTTP GET to backend's health endpoint with timeout
        String url = backend.getAddress() + config.getHealthPath();
        return httpClient.get(url)
            .timeout(config.getProbeTimeout())
            .execute();
    }

    public Map<String, BackendHealthStatus> getHealthReport() {
        Map<String, BackendHealthStatus> report = new LinkedHashMap<>();
        for (Map.Entry<String, BackendHealth> entry : healthStates.entrySet()) {
            BackendHealth health = entry.getValue();
            report.put(entry.getKey(), new BackendHealthStatus(
                health.isHealthy(),
                health.getAverageLatency(),
                health.getSuccessRate(),
                health.getLastCheckTime(),
                health.getConsecutiveFailures()
            ));
        }
        return report;
    }
}

class BackendHealth {
    private final Backend backend;
    private volatile boolean healthy = true;
    private final AtomicInteger consecutiveSuccesses = new AtomicInteger(0);
    private final AtomicInteger consecutiveFailures = new AtomicInteger(0);
    private final SlidingWindowCounter successCounter;
    private final SlidingWindowCounter totalCounter;
    private final MovingAverage latencyAverage;
    private volatile Instant lastCheckTime;

    public BackendHealth(Backend backend) {
        this.backend = backend;
        this.successCounter = new SlidingWindowCounter(Duration.ofMinutes(5));
        this.totalCounter = new SlidingWindowCounter(Duration.ofMinutes(5));
        this.latencyAverage = new MovingAverage(100); // Last 100 samples
    }

    public void recordSuccess(long latencyMs) {
        consecutiveSuccesses.incrementAndGet();
        consecutiveFailures.set(0);
        successCounter.increment();
        totalCounter.increment();
        latencyAverage.add(latencyMs);
        lastCheckTime = Instant.now();
    }

    public void recordFailure(int statusCode, long latencyMs) {
        consecutiveFailures.incrementAndGet();
        consecutiveSuccesses.set(0);
        totalCounter.increment();
        if (latencyMs > 0) latencyAverage.add(latencyMs);
        lastCheckTime = Instant.now();
    }

    public double getSuccessRate() {
        long total = totalCounter.getCount();
        return total == 0 ? 1.0 : (double) successCounter.getCount() / total;
    }

    public void markHealthy() { this.healthy = true; }
    public void markUnhealthy() { this.healthy = false; }
    public boolean isHealthy() { return healthy; }
    public int getConsecutiveSuccesses() { return consecutiveSuccesses.get(); }
    public int getConsecutiveFailures() { return consecutiveFailures.get(); }
    public double getAverageLatency() { return latencyAverage.getAverage(); }
    public Instant getLastCheckTime() { return lastCheckTime; }
}

Quorum-Based Read/Write Coordinator import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

/**
 * Coordinator that implements quorum reads and writes with configurable
 * consistency levels. Handles timeouts, read repair, and response merging.
 */
public class QuorumCoordinator {
    private final List<ReplicaNode> replicas;
    private final int readQuorum;   // R
    private final int writeQuorum;  // W
    private final int replicaCount; // N
    private final ExecutorService executor;
    private final long timeoutMs;

    public QuorumCoordinator(List<ReplicaNode> replicas, int readQuorum,
                             int writeQuorum, long timeoutMs) {
        this.replicas = replicas;
        this.replicaCount = replicas.size();
        this.readQuorum = readQuorum;
        this.writeQuorum = writeQuorum;
        this.timeoutMs = timeoutMs;
        this.executor = Executors.newFixedThreadPool(replicas.size());

        // Validate quorum overlap for strong consistency
        if (readQuorum + writeQuorum <= replicaCount) {
            System.err.println("WARNING: R + W <= N — strong consistency NOT guaranteed");
        }
    }

    /**
     * Quorum write: send write to all replicas, wait for W acknowledgments.
     * Returns success if at least W replicas confirm the write.
     */
    public WriteResult write(String key, byte[] value, long timestamp) {
        List<Future<WriteAck>> futures = new ArrayList<>();

        // Send write to ALL replicas (not just W)
        for (ReplicaNode replica : replicas) {
            futures.add(executor.submit(() -> replica.write(key, value, timestamp)));
        }

        // Wait for W acknowledgments within timeout
        int acks = 0;
        List<String> failedNodes = new ArrayList<>();

        for (int i = 0; i < futures.size(); i++) {
            try {
                WriteAck ack = futures.get(i).get(timeoutMs, TimeUnit.MILLISECONDS);
                if (ack.isSuccess()) {
                    acks++;
                } else {
                    failedNodes.add(replicas.get(i).getNodeId());
                }
            } catch (TimeoutException | InterruptedException | ExecutionException e) {
                failedNodes.add(replicas.get(i).getNodeId());
            }
        }

        if (acks >= writeQuorum) {
            return new WriteResult(true, acks, failedNodes);
        } else {
            return new WriteResult(false, acks, failedNodes);
        }
    }

    /**
     * Quorum read with read repair: query all replicas, wait for R responses,
     * return the value with the highest timestamp, and repair stale replicas.
     */
    public ReadResult read(String key) {
        List<Future<ReadResponse>> futures = new ArrayList<>();

        // Query ALL replicas
        for (ReplicaNode replica : replicas) {
            futures.add(executor.submit(() -> replica.read(key)));
        }

        // Collect R responses
        List<ReadResponse> responses = new ArrayList<>();
        for (int i = 0; i < futures.size(); i++) {
            try {
                ReadResponse response = futures.get(i).get(timeoutMs, TimeUnit.MILLISECONDS);
                responses.add(response);
            } catch (TimeoutException | InterruptedException | ExecutionException e) {
                // Node didn't respond in time — skip
            }

            // Once we have R responses, we can return (but continue collecting for repair)
            if (responses.size() == readQuorum) {
                break;
            }
        }

        if (responses.size() < readQuorum) {
            return new ReadResult(null, false, "Insufficient replicas responded");
        }

        // Find the most recent value (highest timestamp wins)
        ReadResponse latest = responses.stream()
            .filter(r -> r.getValue() != null)
            .max(Comparator.comparingLong(ReadResponse::getTimestamp))
            .orElse(responses.get(0));

        // Trigger async read repair for stale replicas
        triggerReadRepair(key, latest, responses);

        return new ReadResult(latest.getValue(), true, null);
    }

    /**
     * Read repair: asynchronously update replicas that returned stale data.
     * This is a background operation — it does not block the read response.
     */
    private void triggerReadRepair(String key, ReadResponse latest,
                                   List<ReadResponse> responses) {
        executor.submit(() -> {
            for (ReadResponse response : responses) {
                if (response.getTimestamp() < latest.getTimestamp()) {
                    try {
                        response.getSourceNode().write(
                            key, latest.getValue(), latest.getTimestamp()
                        );
                    } catch (Exception e) {
                        // Read repair is best-effort; log and continue
                        System.err.println("Read repair failed for node "
                            + response.getSourceNode().getNodeId() + ": " + e.getMessage());
                    }
                }
            }
        });
    }
}

Sloppy Quorum with Hinted Handoff interface HintedWrite {
  key: string;
  value: Buffer;
  timestamp: number;
  targetNodeId: string;  // The node this write is intended for
  createdAt: number;     // When the hint was created
  ttlMs: number;         // How long to keep the hint before discarding
}

/**
 * Implements sloppy quorum with hinted handoff.
 * When a designated replica is unreachable, a "next-in-line" node
 * accepts the write and stores a hint for later delivery.
 */
class SloppyQuorumCoordinator {
  private preferenceList: Map<string, string[]>;  // key range → ordered node list
  private hintedStore: Map<string, HintedWrite[]> = new Map();  // nodeId → pending hints
  private readonly N: number;  // Replication factor
  private readonly W: number;  // Write quorum
  private readonly hintTtlMs: number = 3 * 60 * 60 * 1000;  // 3 hours default

  constructor(
    private nodes: Map<string, ReplicaNode>,
    private ring: ConsistentHashRing,
    config: { N: number; W: number }
  ) {
    this.N = config.N;
    this.W = config.W;
    this.preferenceList = new Map();
  }

  /**
   * Write with sloppy quorum: if designated replicas are down,
   * accept writes on any reachable node (with hints for delivery later).
   */
  async write(key: string, value: Buffer, timestamp: number): Promise<WriteResult> {
    const designatedNodes = this.ring.getNodes(key, this.N);
    let acks = 0;
    const hints: HintedWrite[] = [];

    for (const nodeId of designatedNodes) {
      const node = this.nodes.get(nodeId);
      if (node && node.isReachable()) {
        try {
          await node.write(key, value, timestamp);
          acks++;
        } catch (err) {
          // Node became unreachable during write — try handoff
          const handoffNode = this.findHandoffNode(designatedNodes);
          if (handoffNode) {
            await this.writeWithHint(handoffNode, key, value, timestamp, nodeId);
            acks++;
          }
        }
      } else {
        // Node unreachable — use hinted handoff
        const handoffNode = this.findHandoffNode(designatedNodes);
        if (handoffNode) {
          await this.writeWithHint(handoffNode, key, value, timestamp, nodeId);
          acks++;  // Sloppy quorum counts handoff nodes
        }
      }

      if (acks >= this.W) break;
    }

    return { success: acks >= this.W, acks, hints: hints.length };
  }

  /**
   * Write data to a handoff node with a hint indicating the intended target.
   * The handoff node stores the data and periodically attempts delivery.
   */
  private async writeWithHint(
    handoffNode: ReplicaNode,
    key: string,
    value: Buffer,
    timestamp: number,
    targetNodeId: string
  ): Promise<void> {
    // Store the actual data on the handoff node
    await handoffNode.write(key, value, timestamp);

    // Store the hint for later delivery
    const hint: HintedWrite = {
      key,
      value,
      timestamp,
      targetNodeId,
      createdAt: Date.now(),
      ttlMs: this.hintTtlMs,
    };

    const nodeHints = this.hintedStore.get(handoffNode.nodeId) || [];
    nodeHints.push(hint);
    this.hintedStore.set(handoffNode.nodeId, nodeHints);
  }

  /**
   * Periodically called to deliver hints to recovered nodes.
   * Once delivered, the hint and temporary data are deleted from the handoff node.
   */
  async deliverHints(handoffNodeId: string): Promise<number> {
    const hints = this.hintedStore.get(handoffNodeId) || [];
    let delivered = 0;

    const remaining: HintedWrite[] = [];
    for (const hint of hints) {
      // Check if hint has expired
      if (Date.now() - hint.createdAt > hint.ttlMs) {
        continue;  // Discard expired hints
      }

      const targetNode = this.nodes.get(hint.targetNodeId);
      if (targetNode && targetNode.isReachable()) {
        try {
          await targetNode.write(hint.key, hint.value, hint.timestamp);
          delivered++;
          // Delete temporary data from handoff node
          const handoffNode = this.nodes.get(handoffNodeId);
          if (handoffNode) await handoffNode.deleteHintedData(hint.key, hint.timestamp);
        } catch {
          remaining.push(hint);  // Retry later
        }
      } else {
        remaining.push(hint);  // Target still down
      }
    }

    this.hintedStore.set(handoffNodeId, remaining);
    return delivered;
  }

  private findHandoffNode(excludeNodes: string[]): ReplicaNode | null {
    const excludeSet = new Set(excludeNodes);
    for (const [nodeId, node] of this.nodes) {
      if (!excludeSet.has(nodeId) && node.isReachable()) {
        return node;
      }
    }
    return null;
  }
}

Orchestration-Based Saga (Order Fulfillment) import java.util.*;
import java.util.concurrent.CompletableFuture;

/**
 * Saga orchestrator for order fulfillment.
 * Coordinates: Inventory → Payment → Shipping
 * Each step has a corresponding compensation action.
 */
public class OrderSagaOrchestrator {
    private final InventoryService inventoryService;
    private final PaymentService paymentService;
    private final ShippingService shippingService;
    private final SagaLog sagaLog;

    public OrderSagaOrchestrator(InventoryService inventoryService,
                                  PaymentService paymentService,
                                  ShippingService shippingService,
                                  SagaLog sagaLog) {
        this.inventoryService = inventoryService;
        this.paymentService = paymentService;
        this.shippingService = shippingService;
        this.sagaLog = sagaLog;
    }

    /**
     * Execute the order saga. Each step is a local transaction.
     * If any step fails, compensate all previously completed steps in reverse order.
     */
    public SagaResult executeOrderSaga(Order order) {
        String sagaId = UUID.randomUUID().toString();
        sagaLog.start(sagaId, "order-fulfillment", order.getOrderId());

        List<CompensationAction> completedSteps = new ArrayList<>();

        try {
            // Step 1: Reserve inventory
            sagaLog.stepStarted(sagaId, "reserve-inventory");
            ReservationResult reservation = inventoryService.reserveItems(
                order.getOrderId(), order.getItems()
            );
            sagaLog.stepCompleted(sagaId, "reserve-inventory", reservation.getReservationId());
            completedSteps.add(() -> inventoryService.releaseReservation(reservation.getReservationId()));

            // Step 2: Process payment (PIVOT POINT — after this, prefer forward recovery)
            sagaLog.stepStarted(sagaId, "process-payment");
            PaymentResult payment = paymentService.charge(
                order.getOrderId(), order.getCustomerId(), order.getTotalAmount()
            );
            sagaLog.stepCompleted(sagaId, "process-payment", payment.getTransactionId());
            completedSteps.add(() -> paymentService.refund(payment.getTransactionId()));

            // Step 3: Create shipment
            sagaLog.stepStarted(sagaId, "create-shipment");
            ShipmentResult shipment = shippingService.createShipment(
                order.getOrderId(), order.getShippingAddress(), reservation.getWarehouseId()
            );
            sagaLog.stepCompleted(sagaId, "create-shipment", shipment.getShipmentId());
            // No compensation needed for shipment if saga completes successfully

            // All steps succeeded
            sagaLog.completed(sagaId);
            return SagaResult.success(sagaId, shipment.getTrackingNumber());

        } catch (RetryableException e) {
            // Recoverable failure: retry the failed step (with backoff)
            sagaLog.stepFailed(sagaId, e.getStepName(), e.getMessage(), true);
            return retryFailedStep(sagaId, order, e, completedSteps);

        } catch (SagaStepException e) {
            // Non-recoverable failure: compensate all completed steps
            sagaLog.stepFailed(sagaId, e.getStepName(), e.getMessage(), false);
            compensate(sagaId, completedSteps);
            return SagaResult.failed(sagaId, e.getMessage());
        }
    }

    /**
     * Execute compensating transactions in reverse order.
     * Each compensation is idempotent and retried on failure.
     */
    private void compensate(String sagaId, List<CompensationAction> completedSteps) {
        sagaLog.compensationStarted(sagaId);

        // Compensate in reverse order
        Collections.reverse(completedSteps);
        for (int i = 0; i < completedSteps.size(); i++) {
            CompensationAction action = completedSteps.get(i);
            int maxRetries = 3;
            for (int attempt = 1; attempt <= maxRetries; attempt++) {
                try {
                    action.execute();
                    sagaLog.compensationStepCompleted(sagaId, i);
                    break;
                } catch (Exception e) {
                    if (attempt == maxRetries) {
                        // Compensation failed after retries — alert for manual intervention
                        sagaLog.compensationStepFailed(sagaId, i, e.getMessage());
                        alertOperations(sagaId, i, e);
                    } else {
                        sleep(exponentialBackoff(attempt));
                    }
                }
            }
        }

        sagaLog.compensationCompleted(sagaId);
    }

    private SagaResult retryFailedStep(String sagaId, Order order,
                                        RetryableException e,
                                        List<CompensationAction> completedSteps) {
        // Retry logic with exponential backoff (simplified)
        for (int attempt = 1; attempt <= 3; attempt++) {
            try {
                sleep(exponentialBackoff(attempt));
                // Re-execute from the failed step (implementation depends on step)
                return executeOrderSaga(order);  // Simplified: restart entire saga
            } catch (Exception retryEx) {
                if (attempt == 3) {
                    compensate(sagaId, completedSteps);
                    return SagaResult.failed(sagaId, "Exhausted retries: " + e.getMessage());
                }
            }
        }
        return SagaResult.failed(sagaId, "Retry exhausted");
    }

    private long exponentialBackoff(int attempt) {
        return (long) Math.pow(2, attempt) * 1000;  // 2s, 4s, 8s
    }

    private void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException ignored) {}
    }

    private void alertOperations(String sagaId, int stepIndex, Exception e) {
        // Send alert to operations team for manual resolution
    }
}

