Choreography-Based Saga with Event-Driven Communication import { EventEmitter } from 'events';

// Domain events that drive the choreography
interface OrderCreatedEvent {
  type: 'OrderCreated';
  orderId: string;
  customerId: string;
  items: Array<{ productId: string; quantity: number; price: number }>;
  totalAmount: number;
}

interface InventoryReservedEvent {
  type: 'InventoryReserved';
  orderId: string;
  reservationId: string;
  warehouseId: string;
}

interface InventoryReservationFailedEvent {
  type: 'InventoryReservationFailed';
  orderId: string;
  reason: string;
}

interface PaymentProcessedEvent {
  type: 'PaymentProcessed';
  orderId: string;
  transactionId: string;
}

interface PaymentFailedEvent {
  type: 'PaymentFailed';
  orderId: string;
  reason: string;
}

type SagaEvent =
  | OrderCreatedEvent
  | InventoryReservedEvent
  | InventoryReservationFailedEvent
  | PaymentProcessedEvent
  | PaymentFailedEvent;

/**
 * Inventory service participating in a choreography-based saga.
 * Reacts to OrderCreated events and emits reservation results.
 * Listens for PaymentFailed to trigger compensation.
 */
class InventoryServiceHandler {
  constructor(
    private eventBus: EventEmitter,
    private inventoryRepo: InventoryRepository
  ) {
    // React to order creation
    this.eventBus.on('OrderCreated', this.handleOrderCreated.bind(this));
    // React to payment failure — compensate by releasing reservation
    this.eventBus.on('PaymentFailed', this.handlePaymentFailed.bind(this));
  }

  private async handleOrderCreated(event: OrderCreatedEvent): Promise<void> {
    try {
      const reservation = await this.inventoryRepo.reserve(
        event.orderId,
        event.items
      );

      this.eventBus.emit('InventoryReserved', {
        type: 'InventoryReserved',
        orderId: event.orderId,
        reservationId: reservation.id,
        warehouseId: reservation.warehouseId,
      } as InventoryReservedEvent);
    } catch (error) {
      this.eventBus.emit('InventoryReservationFailed', {
        type: 'InventoryReservationFailed',
        orderId: event.orderId,
        reason: (error as Error).message,
      } as InventoryReservationFailedEvent);
    }
  }

  /**
   * Compensating action: release inventory when payment fails.
   * Must be idempotent — may be called multiple times for the same order.
   */
  private async handlePaymentFailed(event: PaymentFailedEvent): Promise<void> {
    await this.inventoryRepo.releaseByOrderId(event.orderId);
    // Idempotent: if already released, this is a no-op
  }
}

/**
 * Payment service participating in the choreography.
 * Reacts to InventoryReserved events.
 */
class PaymentServiceHandler {
  constructor(
    private eventBus: EventEmitter,
    private paymentGateway: PaymentGateway
  ) {
    this.eventBus.on('InventoryReserved', this.handleInventoryReserved.bind(this));
  }

  private async handleInventoryReserved(event: InventoryReservedEvent): Promise<void> {
    try {
      const result = await this.paymentGateway.charge(event.orderId);

      this.eventBus.emit('PaymentProcessed', {
        type: 'PaymentProcessed',
        orderId: event.orderId,
        transactionId: result.transactionId,
      } as PaymentProcessedEvent);
    } catch (error) {
      this.eventBus.emit('PaymentFailed', {
        type: 'PaymentFailed',
        orderId: event.orderId,
        reason: (error as Error).message,
      } as PaymentFailedEvent);
    }
  }
}

/**
 * Saga state tracker for monitoring and debugging choreography-based sagas.
 * Listens to all events and maintains a view of each saga's progress.
 */
class SagaStateTracker {
  private sagaStates: Map<string, SagaState> = new Map();

  constructor(private eventBus: EventEmitter) {
    const events = [
      'OrderCreated', 'InventoryReserved', 'InventoryReservationFailed',
      'PaymentProcessed', 'PaymentFailed'
    ];
    events.forEach(event => {
      this.eventBus.on(event, (e: SagaEvent) => this.trackEvent(e));
    });
  }

  private trackEvent(event: SagaEvent): void {
    const orderId = event.orderId;
    const state = this.sagaStates.get(orderId) || { steps: [], status: 'in-progress' };
    state.steps.push({ event: event.type, timestamp: Date.now() });

    if (event.type === 'PaymentProcessed') state.status = 'completed';
    if (event.type === 'InventoryReservationFailed') state.status = 'failed';
    if (event.type === 'PaymentFailed') state.status = 'compensating';

    this.sagaStates.set(orderId, state);
  }

  getState(orderId: string): SagaState | undefined {
    return this.sagaStates.get(orderId);
  }
}

interface SagaState {
  steps: Array<{ event: string; timestamp: number }>;
  status: 'in-progress' | 'completed' | 'failed' | 'compensating';
}

Auto-Scaling Decision Engine public class AutoScaler {
    private final MetricsClient metricsClient;
    private final InstanceManager instanceManager;
    private final ScalingPolicy policy;
    private Instant lastScaleAction = Instant.EPOCH;

    public AutoScaler(MetricsClient metricsClient, InstanceManager instanceManager,
                      ScalingPolicy policy) {
        this.metricsClient = metricsClient;
        this.instanceManager = instanceManager;
        this.policy = policy;
    }

    /**
     * Evaluate scaling decision based on current metrics.
     * Implements cooldown period to prevent thrashing.
     */
    public ScalingDecision evaluate() {
        // Respect cooldown period
        Duration sinceLastAction = Duration.between(lastScaleAction, Instant.now());
        if (sinceLastAction.compareTo(policy.getCooldownPeriod()) < 0) {
            return ScalingDecision.noAction("Cooldown period active");
        }

        int currentInstances = instanceManager.getActiveInstanceCount();
        AggregatedMetrics metrics = metricsClient.getAggregatedMetrics(
            policy.getMetricWindow()
        );

        // Scale-out decision: based on leading indicators
        if (shouldScaleOut(metrics, currentInstances)) {
            int targetInstances = calculateScaleOutTarget(metrics, currentInstances);
            targetInstances = Math.min(targetInstances, policy.getMaxInstances());
            lastScaleAction = Instant.now();
            return ScalingDecision.scaleOut(targetInstances - currentInstances);
        }

        // Scale-in decision: more conservative, uses trailing indicators
        if (shouldScaleIn(metrics, currentInstances)) {
            int targetInstances = calculateScaleInTarget(metrics, currentInstances);
            targetInstances = Math.max(targetInstances, policy.getMinInstances());
            lastScaleAction = Instant.now();
            return ScalingDecision.scaleIn(currentInstances - targetInstances);
        }

        return ScalingDecision.noAction("Metrics within acceptable range");
    }

    private boolean shouldScaleOut(AggregatedMetrics metrics, int currentInstances) {
        return metrics.getAvgCpuUtilization() > policy.getScaleOutCpuThreshold()
            || metrics.getP99Latency() > policy.getScaleOutLatencyThreshold()
            || metrics.getQueueDepth() > policy.getScaleOutQueueThreshold();
    }

    private boolean shouldScaleIn(AggregatedMetrics metrics, int currentInstances) {
        return currentInstances > policy.getMinInstances()
            && metrics.getAvgCpuUtilization() < policy.getScaleInCpuThreshold()
            && metrics.getP99Latency() < policy.getScaleInLatencyThreshold()
            && metrics.getQueueDepth() < policy.getScaleInQueueThreshold();
    }

    private int calculateScaleOutTarget(AggregatedMetrics metrics, int current) {
        // Target: bring CPU utilization to 60% (leaving headroom for spikes)
        double targetUtilization = 0.6;
        double currentLoad = metrics.getAvgCpuUtilization() * current;
        return (int) Math.ceil(currentLoad / targetUtilization);
    }

    private int calculateScaleInTarget(AggregatedMetrics metrics, int current) {
        // Conservative: remove at most 25% of instances per scale-in event
        int maxRemoval = Math.max(1, current / 4);
        double targetUtilization = 0.7;
        double currentLoad = metrics.getAvgCpuUtilization() * current;
        int target = (int) Math.ceil(currentLoad / targetUtilization);
        return Math.max(target, current - maxRemoval);
    }
}

Connection Pool with Health Checking interface PoolConfig {
  minConnections: number;
  maxConnections: number;
  acquireTimeout: number;      // ms to wait for available connection
  idleTimeout: number;         // ms before idle connection is closed
  healthCheckInterval: number; // ms between health checks
  maxLifetime: number;         // ms before connection is recycled
}

class ConnectionPool {
  private available: Connection[] = [];
  private inUse: Set<Connection> = new Set();
  private waitQueue: Array<{
    resolve: (conn: Connection) => void;
    reject: (err: Error) => void;
    timer: NodeJS.Timeout;
  }> = [];
  private config: PoolConfig;
  private healthCheckTimer: NodeJS.Timeout | null = null;

  constructor(config: PoolConfig) {
    this.config = config;
    this.initialize();
  }

  private async initialize(): Promise<void> {
    // Pre-warm minimum connections
    for (let i = 0; i < this.config.minConnections; i++) {
      const conn = await this.createConnection();
      this.available.push(conn);
    }
    // Start periodic health checks
    this.healthCheckTimer = setInterval(
      () => this.healthCheck(),
      this.config.healthCheckInterval
    );
  }

  async acquire(): Promise<Connection> {
    // Try to get an available connection
    while (this.available.length > 0) {
      const conn = this.available.pop()!;
      if (this.isHealthy(conn) && !this.isExpired(conn)) {
        this.inUse.add(conn);
        return conn;
      }
      // Connection is unhealthy or expired, discard it
      conn.destroy();
    }

    // Create new connection if under max limit
    const totalConnections = this.inUse.size + this.available.length;
    if (totalConnections < this.config.maxConnections) {
      const conn = await this.createConnection();
      this.inUse.add(conn);
      return conn;
    }

    // All connections in use and at max: wait in queue
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        const index = this.waitQueue.findIndex(w => w.resolve === resolve);
        if (index !== -1) this.waitQueue.splice(index, 1);
        reject(new Error(
          `Connection acquire timeout after ${this.config.acquireTimeout}ms. ` +
          `Pool: ${this.inUse.size} active, ${this.available.length} idle, ` +
          `${this.waitQueue.length} waiting`
        ));
      }, this.config.acquireTimeout);

      this.waitQueue.push({ resolve, reject, timer });
    });
  }

  release(conn: Connection): void {
    this.inUse.delete(conn);

    // If waiters exist, give connection directly to next waiter
    if (this.waitQueue.length > 0) {
      const waiter = this.waitQueue.shift()!;
      clearTimeout(waiter.timer);
      this.inUse.add(conn);
      waiter.resolve(conn);
      return;
    }

    // Return to available pool if healthy
    if (this.isHealthy(conn) && !this.isExpired(conn)) {
      conn.lastUsed = Date.now();
      this.available.push(conn);
    } else {
      conn.destroy();
    }

    // Maintain minimum pool size
    this.replenishPool();
  }

  private async healthCheck(): Promise<void> {
    const now = Date.now();
    const toRemove: Connection[] = [];

    for (const conn of this.available) {
      // Remove idle connections beyond minimum
      if (now - conn.lastUsed > this.config.idleTimeout
          && this.available.length > this.config.minConnections) {
        toRemove.push(conn);
      }
      // Remove expired connections
      else if (this.isExpired(conn)) {
        toRemove.push(conn);
      }
    }

    for (const conn of toRemove) {
      const index = this.available.indexOf(conn);
      if (index !== -1) this.available.splice(index, 1);
      conn.destroy();
    }

    await this.replenishPool();
  }

  private isExpired(conn: Connection): boolean {
    return Date.now() - conn.createdAt > this.config.maxLifetime;
  }

  private isHealthy(conn: Connection): boolean {
    return conn.isConnected && !conn.hasError;
  }

  private async replenishPool(): Promise<void> {
    const total = this.inUse.size + this.available.length;
    const deficit = this.config.minConnections - total;
    for (let i = 0; i < deficit; i++) {
      try {
        const conn = await this.createConnection();
        this.available.push(conn);
      } catch {
        break; // Stop trying if connection creation fails
      }
    }
  }

  private async createConnection(): Promise<Connection> {
    // Implementation depends on the database driver
    const conn = await Connection.create();
    conn.createdAt = Date.now();
    conn.lastUsed = Date.now();
    return conn;
  }

  getStats(): PoolStats {
    return {
      active: this.inUse.size,
      idle: this.available.length,
      waiting: this.waitQueue.length,
      total: this.inUse.size + this.available.length
    };
  }
}

Stateless Service Design with External Session Store /**
 * Demonstrates stateless service design where all session state
 * is externalized to Redis, allowing any instance to handle any request.
 */
@RestController
public class OrderController {
    private final RedisTemplate<String, CartState> sessionStore;
    private final OrderService orderService;
    private final String instanceId;

    public OrderController(RedisTemplate<String, CartState> sessionStore,
                           OrderService orderService) {
        this.sessionStore = sessionStore;
        this.orderService = orderService;
        this.instanceId = UUID.randomUUID().toString().substring(0, 8);
    }

    @PostMapping("/cart/{sessionId}/items")
    public ResponseEntity<CartState> addItem(
            @PathVariable String sessionId,
            @RequestBody AddItemRequest request) {

        // Load state from external store (any instance can serve this)
        String key = "cart:" + sessionId;
        CartState cart = sessionStore.opsForValue().get(key);
        if (cart == null) {
            cart = new CartState(sessionId);
        }

        // Apply business logic
        cart.addItem(request.getProductId(), request.getQuantity(), request.getPrice());
        cart.setLastModified(Instant.now());
        cart.setLastServedBy(instanceId); // For debugging routing

        // Persist state back to external store
        sessionStore.opsForValue().set(key, cart, Duration.ofHours(24));

        return ResponseEntity.ok(cart);
    }

    @PostMapping("/cart/{sessionId}/checkout")
    public ResponseEntity<OrderConfirmation> checkout(@PathVariable String sessionId) {
        String key = "cart:" + sessionId;
        CartState cart = sessionStore.opsForValue().get(key);

        if (cart == null || cart.getItems().isEmpty()) {
            return ResponseEntity.badRequest().build();
        }

        // Process order (idempotent via order ID)
        OrderConfirmation confirmation = orderService.placeOrder(cart);

        // Clear cart state after successful checkout
        sessionStore.delete(key);

        return ResponseEntity.ok(confirmation);
    }

    @GetMapping("/health/ready")
    public ResponseEntity<Map<String, Object>> readiness() {
        // Readiness depends on external dependencies being available
        boolean redisHealthy = checkRedisConnection();
        boolean dbHealthy = checkDatabaseConnection();

        Map<String, Object> status = Map.of(
            "instance", instanceId,
            "redis", redisHealthy,
            "database", dbHealthy,
            "ready", redisHealthy && dbHealthy
        );

        return (redisHealthy && dbHealthy)
            ? ResponseEntity.ok(status)
            : ResponseEntity.status(503).body(status);
    }
}

Vector Clock Implementation with Conflict Detection import java.util.*;
import java.util.stream.Collectors;

/**
 * Vector clock implementation for tracking causality in a distributed system.
 * Each node maintains its own vector clock and updates it on local events
 * and message exchanges.
 */
public class VectorClock {
    private final Map<String, Long> clock;  // nodeId → counter

    public VectorClock() {
        this.clock = new HashMap<>();
    }

    public VectorClock(Map<String, Long> clock) {
        this.clock = new HashMap<>(clock);
    }

    /**
     * Increment this node's counter (called on local write/event).
     */
    public VectorClock increment(String nodeId) {
        Map<String, Long> newClock = new HashMap<>(this.clock);
        newClock.merge(nodeId, 1L, Long::sum);
        return new VectorClock(newClock);
    }

    /**
     * Merge with another vector clock (called on receiving a message/update).
     * Takes the component-wise maximum of both clocks, then increments own counter.
     */
    public VectorClock merge(VectorClock other, String localNodeId) {
        Map<String, Long> merged = new HashMap<>(this.clock);
        for (Map.Entry<String, Long> entry : other.clock.entrySet()) {
            merged.merge(entry.getKey(), entry.getValue(), Math::max);
        }
        // Increment local counter after merge
        merged.merge(localNodeId, 1L, Long::sum);
        return new VectorClock(merged);
    }

    /**
     * Compare two vector clocks to determine causal relationship.
     * Returns: BEFORE, AFTER, CONCURRENT, or EQUAL
     */
    public CausalRelation compareTo(VectorClock other) {
        boolean thisLessOrEqual = true;
        boolean otherLessOrEqual = true;

        Set<String> allNodes = new HashSet<>();
        allNodes.addAll(this.clock.keySet());
        allNodes.addAll(other.clock.keySet());

        for (String node : allNodes) {
            long thisValue = this.clock.getOrDefault(node, 0L);
            long otherValue = other.clock.getOrDefault(node, 0L);

            if (thisValue > otherValue) otherLessOrEqual = false;
            if (otherValue > thisValue) thisLessOrEqual = false;
        }

        if (thisLessOrEqual && otherLessOrEqual) return CausalRelation.EQUAL;
        if (thisLessOrEqual) return CausalRelation.BEFORE;  // this happened before other
        if (otherLessOrEqual) return CausalRelation.AFTER;   // this happened after other
        return CausalRelation.CONCURRENT;  // Conflict!
    }

    /**
     * Check if this clock dominates (is strictly after) another.
     */
    public boolean dominates(VectorClock other) {
        return compareTo(other) == CausalRelation.AFTER;
    }

    /**
     * Check if two clocks are concurrent (conflict exists).
     */
    public boolean isConcurrentWith(VectorClock other) {
        return compareTo(other) == CausalRelation.CONCURRENT;
    }

    public Map<String, Long> toMap() {
        return Collections.unmodifiableMap(clock);
    }

    @Override
    public String toString() {
        return clock.entrySet().stream()
            .sorted(Map.Entry.comparingByKey())
            .map(e -> e.getKey() + ":" + e.getValue())
            .collect(Collectors.joining(", ", "[", "]"));
    }
}

public enum CausalRelation {
    BEFORE,      // This happened before the other
    AFTER,       // This happened after the other
    CONCURRENT,  // Neither happened before the other (conflict)
    EQUAL        // Same logical time
}

/**
 * Versioned value store using vector clocks for conflict detection.
 * Maintains multiple concurrent versions (siblings) until resolved.
 */
public class VersionedStore<T> {
    private final Map<String, List<VersionedValue<T>>> store = new HashMap<>();

    /**
     * Write a value with a context vector clock.
     * The context is the vector clock of the value being updated (read-before-write).
     */
    public VectorClock put(String key, T value, VectorClock context, String nodeId) {
        VectorClock newClock = context.increment(nodeId);
        VersionedValue<T> newVersion = new VersionedValue<>(value, newClock);

        List<VersionedValue<T>> existing = store.getOrDefault(key, new ArrayList<>());
        List<VersionedValue<T>> surviving = new ArrayList<>();

        for (VersionedValue<T> v : existing) {
            CausalRelation relation = newClock.compareTo(v.getClock());
            if (relation == CausalRelation.BEFORE || relation == CausalRelation.EQUAL) {
                // New write is outdated or same — keep existing, discard new
                surviving.add(v);
            } else if (relation == CausalRelation.CONCURRENT) {
                // Conflict — keep both as siblings
                surviving.add(v);
            }
            // If AFTER — new write supersedes existing, don't keep existing
        }

        surviving.add(newVersion);
        store.put(key, surviving);
        return newClock;
    }

    /**
     * Read a value. Returns all concurrent versions (siblings) if conflicts exist.
     * The client must resolve conflicts and write back a merged value.
     */
    public ReadResult<T> get(String key) {
        List<VersionedValue<T>> versions = store.getOrDefault(key, Collections.emptyList());
        if (versions.isEmpty()) {
            return new ReadResult<>(Collections.emptyList(), new VectorClock(), false);
        }
        if (versions.size() == 1) {
            return new ReadResult<>(
                List.of(versions.get(0).getValue()),
                versions.get(0).getClock(),
                false
            );
        }
        // Multiple siblings — conflict exists
        // Return merged context clock for the client to use in resolution write
        VectorClock mergedContext = versions.stream()
            .map(VersionedValue::getClock)
            .reduce(new VectorClock(), (a, b) -> componentWiseMax(a, b));

        List<T> values = versions.stream()
            .map(VersionedValue::getValue)
            .collect(Collectors.toList());

        return new ReadResult<>(values, mergedContext, true);
    }

    private VectorClock componentWiseMax(VectorClock a, VectorClock b) {
        Map<String, Long> merged = new HashMap<>(a.toMap());
        for (Map.Entry<String, Long> entry : b.toMap().entrySet()) {
            merged.merge(entry.getKey(), entry.getValue(), Math::max);
        }
        return new VectorClock(merged);
    }
}

Conflict Resolution Strategies /**
 * Demonstrates different conflict resolution strategies for concurrent updates
 * detected via vector clocks.
 */

interface VersionedValue<T> {
  value: T;
  clock: Record<string, number>;  // Vector clock as nodeId → counter
  timestamp: number;               // Wall clock (for LWW fallback)
  nodeId: string;                  // Which node wrote this version
}

interface ConflictSet<T> {
  key: string;
  siblings: VersionedValue<T>[];   // All concurrent versions
}

// --- Strategy 1: Last-Writer-Wins (LWW) ---

/**
 * LWW: Pick the value with the highest wall-clock timestamp.
 * Simple but can silently discard valid updates.
 * Used by: Cassandra, DynamoDB (default behavior).
 */
function resolveWithLWW<T>(conflict: ConflictSet<T>): T {
  const winner = conflict.siblings.reduce((latest, current) =>
    current.timestamp > latest.timestamp ? current : latest
  );
  return winner.value;
}

// --- Strategy 2: Application-Specific Merge ---

interface ShoppingCart {
  items: Map<string, number>;  // productId → quantity
}

/**
 * Merge shopping carts by taking the union of items with max quantities.
 * This is a CRDT-like merge that preserves all additions.
 * Used by: Amazon (original Dynamo paper shopping cart example).
 */
function mergeShoppingCarts(conflict: ConflictSet<ShoppingCart>): ShoppingCart {
  const merged: Map<string, number> = new Map();

  for (const sibling of conflict.siblings) {
    for (const [productId, quantity] of sibling.value.items) {
      const current = merged.get(productId) || 0;
      merged.set(productId, Math.max(current, quantity));
    }
  }

  return { items: merged };
}

// --- Strategy 3: Multi-Value Register (Return All to Client) ---

/**
 * Don't resolve automatically — return all siblings to the client.
 * The client displays options or applies domain-specific logic.
 * Used by: Riak (returns siblings to application).
 */
function returnSiblings<T>(conflict: ConflictSet<T>): {
  values: T[];
  requiresResolution: true;
  mergedContext: Record<string, number>;
} {
  // Compute merged context for the resolution write
  const mergedContext: Record<string, number> = {};
  for (const sibling of conflict.siblings) {
    for (const [nodeId, counter] of Object.entries(sibling.clock)) {
      mergedContext[nodeId] = Math.max(mergedContext[nodeId] || 0, counter);
    }
  }

  return {
    values: conflict.siblings.map(s => s.value),
    requiresResolution: true,
    mergedContext,
  };
}

// --- Strategy 4: Dotted Version Vectors (Accurate Sibling Detection) ---

interface DottedVersionVector {
  versionVector: Record<string, number>;  // Base version vector
  dot: { nodeId: string; counter: number };  // The specific event that created this version
}

/**
 * Dotted version vectors improve on plain vector clocks by precisely
 * tracking which node created each sibling, preventing false conflicts
 * (sibling explosion) that occur with plain vector clocks during
 * concurrent reads and writes.
 */
class DottedVersionVectorStore<T> {
  private data: Map<string, Array<{ value: T; dvv: DottedVersionVector }>> = new Map();

  put(key: string, value: T, context: DottedVersionVector, nodeId: string): void {
    const newCounter = (context.versionVector[nodeId] || 0) + 1;
    const newDvv: DottedVersionVector = {
      versionVector: { ...context.versionVector, [nodeId]: newCounter },
      dot: { nodeId, counter: newCounter },
    };

    const existing = this.data.get(key) || [];
    // Remove versions that are dominated by the new version vector
    const surviving = existing.filter(entry => {
      const dominated = Object.entries(entry.dvv.versionVector).every(
        ([nid, cnt]) => (newDvv.versionVector[nid] || 0) >= cnt
      );
      return !dominated;
    });

    surviving.push({ value, dvv: newDvv });
    this.data.set(key, surviving);
  }
}

RESTful API with Proper Error Handling and Pagination @RestController
@RequestMapping("/api/v1/orders")
