    public ResponseEntity<PagedResponse<OrderSummaryDto>> listOrders(
            @RequestParam(defaultValue = "20") @Max(100) int limit,
            @RequestParam(required = false) String cursor,
            @RequestParam(required = false) OrderStatus status,
            @RequestParam(defaultValue = "created_at:desc") String sort,
            @AuthenticationPrincipal UserPrincipal user) {

        CursorPageRequest pageRequest = CursorPageRequest.builder()
            .cursor(cursor)
            .limit(limit)
            .filter(OrderFilter.builder().status(status).userId(user.getId()).build())
            .sort(Sort.parse(sort))
            .build();

        CursorPage<Order> page = orderService.findOrders(pageRequest);

        PagedResponse<OrderSummaryDto> response = PagedResponse.<OrderSummaryDto>builder()
            .data(page.getItems().stream().map(mapper::toSummaryDto).toList())
            .pagination(PaginationMeta.builder()
                .hasNext(page.hasNext())
                .nextCursor(page.getNextCursor())
                .totalEstimate(page.getTotalEstimate())
                .build())
            .links(PaginationLinks.builder()
                .self(buildPageLink(limit, cursor, status, sort))
                .next(page.hasNext()
                    ? buildPageLink(limit, page.getNextCursor(), status, sort)
                    : null)
                .build())
            .build();

        return ResponseEntity.ok()
            .header("X-Total-Count-Estimate", String.valueOf(page.getTotalEstimate()))
            .body(response);
    }

    /**
     * Create order with idempotency key to prevent duplicate orders on retry.
     * The idempotency key is stored for 24 hours; duplicate requests return
     * the original response without re-executing the operation.
     */
    @PostMapping
    public ResponseEntity<OrderDto> createOrder(
            @Valid @RequestBody CreateOrderRequest request,
            @RequestHeader("Idempotency-Key") String idempotencyKey,
            @AuthenticationPrincipal UserPrincipal user) {

        // Check for existing idempotent response
        Optional<IdempotentResponse> existing = orderService
            .findIdempotentResponse(idempotencyKey);
        if (existing.isPresent()) {
            return ResponseEntity.status(existing.get().getStatusCode())
                .body(existing.get().getBody(OrderDto.class));
        }

        Order order = orderService.createOrder(user.getId(), request, idempotencyKey);
        OrderDto dto = mapper.toDto(order);

        URI location = ServletUriComponentsBuilder.fromCurrentRequest()
            .path("/{id}")
            .buildAndExpand(order.getId())
            .toUri();

        return ResponseEntity.created(location)
            .header("Idempotency-Key", idempotencyKey)
            .body(dto);
    }

    /**
     * Partial update using JSON Patch (RFC 6902) for fine-grained modifications.
     * Supports optimistic concurrency via ETag/If-Match headers.
     */
    @PatchMapping(value = "/{orderId}", consumes = "application/json-patch+json")
    public ResponseEntity<OrderDto> patchOrder(
            @PathVariable UUID orderId,
            @RequestBody JsonPatch patch,
            @RequestHeader("If-Match") String etag,
            @AuthenticationPrincipal UserPrincipal user) {

        Order order = orderService.findById(orderId)
            .orElseThrow(() -> new ResourceNotFoundException("Order", orderId));

        // Verify ownership
        if (!order.getUserId().equals(user.getId())) {
            throw new ForbiddenException("Cannot modify another user's order");
        }

        // Optimistic concurrency check
        if (!order.getVersion().toString().equals(etag.replace("\"", ""))) {
            throw new ConflictException("Order has been modified since last read");
        }

        Order updated = orderService.applyPatch(order, patch);
        OrderDto dto = mapper.toDto(updated);

        return ResponseEntity.ok()
            .eTag("\"" + updated.getVersion() + "\"")
            .body(dto);
    }

    /**
     * Structured error handling with consistent error response format.
     */
    @ExceptionHandler(ResourceNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleNotFound(ResourceNotFoundException ex) {
        ErrorResponse error = ErrorResponse.builder()
            .status(404)
            .code("RESOURCE_NOT_FOUND")
            .message(ex.getMessage())
            .details(List.of(
                ErrorDetail.builder()
                    .field(ex.getResourceType().toLowerCase() + "_id")
                    .message(ex.getResourceType() + " with ID " + ex.getResourceId() + " not found")
                    .build()
            ))
            .timestamp(Instant.now())
            .requestId(MDC.get("requestId"))
            .build();

        return ResponseEntity.status(404).body(error);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
        List<ErrorDetail> details = ex.getBindingResult().getFieldErrors().stream()
            .map(fe -> ErrorDetail.builder()
                .field(fe.getField())
                .message(fe.getDefaultMessage())
                .rejectedValue(fe.getRejectedValue())
                .build())
            .toList();

        ErrorResponse error = ErrorResponse.builder()
            .status(422)
            .code("VALIDATION_ERROR")
            .message("Request validation failed")
            .details(details)
            .timestamp(Instant.now())
            .requestId(MDC.get("requestId"))
            .build();

        return ResponseEntity.status(422).body(error);
    }
}

GraphQL Schema with DataLoader Pattern import { ApolloServer } from '@apollo/server';
import DataLoader from 'dataloader';

// Type definitions with clear domain modeling
const typeDefs = `#graphql
  type Query {
    order(id: ID!): Order
    orders(
      first: Int = 20
      after: String
      filter: OrderFilterInput
    ): OrderConnection!
    user(id: ID!): User
  }

  type Mutation {
    createOrder(input: CreateOrderInput!): CreateOrderPayload!
    cancelOrder(id: ID!, reason: String!): CancelOrderPayload!
  }

  """Relay-style connection for cursor-based pagination"""
  type OrderConnection {
    edges: [OrderEdge!]!
    pageInfo: PageInfo!
    totalCount: Int!
  }

  type OrderEdge {
    node: Order!
    cursor: String!
  }

  type PageInfo {
    hasNextPage: Boolean!
    hasPreviousPage: Boolean!
    startCursor: String
    endCursor: String
  }

  type Order {
    id: ID!
    status: OrderStatus!
    items: [OrderItem!]!
    customer: User!
    shippingAddress: Address!
    totalAmount: Money!
    createdAt: DateTime!
    updatedAt: DateTime!
    timeline: [OrderEvent!]!
  }

  type OrderItem {
    id: ID!
    product: Product!
    quantity: Int!
    unitPrice: Money!
    lineTotal: Money!
  }

  type Money {
    amount: Int!          # Amount in smallest currency unit (cents)
    currency: String!     # ISO 4217 currency code
    formatted: String!    # Human-readable format
  }

  input CreateOrderInput {
    items: [OrderItemInput!]!
    shippingAddressId: ID!
    paymentMethodId: ID!
    idempotencyKey: String!
  }

  type CreateOrderPayload {
    order: Order
    errors: [UserError!]!
  }

  type UserError {
    field: [String!]
    message: String!
    code: ErrorCode!
  }

  enum OrderStatus {
    PENDING
    CONFIRMED
    PROCESSING
    SHIPPED
    DELIVERED
    CANCELLED
  }

  enum ErrorCode {
    INVALID_INPUT
    INSUFFICIENT_STOCK
    PAYMENT_FAILED
    NOT_FOUND
    UNAUTHORIZED
  }
`;

// Resolvers with DataLoader for N+1 prevention
const resolvers = {
  Query: {
    order: async (_: unknown, { id }: { id: string }, context: GraphQLContext) => {
      return context.dataloaders.orders.load(id);
    },

    orders: async (
      _: unknown,
      args: { first: number; after?: string; filter?: OrderFilter },
      context: GraphQLContext
    ) => {
      const { first, after, filter } = args;
      const userId = context.currentUser.id;

      const result = await context.services.orders.findPaginated({
        userId,
        limit: Math.min(first, 100), // Cap at 100 to prevent abuse
        cursor: after ? decodeCursor(after) : undefined,
        filter,
      });

      return {
        edges: result.items.map(order => ({
          node: order,
          cursor: encodeCursor({ id: order.id, createdAt: order.createdAt }),
        })),
        pageInfo: {
          hasNextPage: result.hasNext,
          hasPreviousPage: !!after,
          startCursor: result.items.length > 0
            ? encodeCursor({ id: result.items[0].id, createdAt: result.items[0].createdAt })
            : null,
          endCursor: result.items.length > 0
            ? encodeCursor({
                id: result.items[result.items.length - 1].id,
                createdAt: result.items[result.items.length - 1].createdAt,
              })
            : null,
        },
        totalCount: result.totalCount,
      };
    },
  },

  Order: {
    // DataLoader batches multiple customer lookups into a single query
    customer: (order: Order, _: unknown, context: GraphQLContext) => {
      return context.dataloaders.users.load(order.customerId);
    },

    items: (order: Order, _: unknown, context: GraphQLContext) => {
      return context.dataloaders.orderItems.load(order.id);
    },

    timeline: (order: Order, _: unknown, context: GraphQLContext) => {
      return context.dataloaders.orderEvents.load(order.id);
    },
  },

  Mutation: {
    createOrder: async (
      _: unknown,
      { input }: { input: CreateOrderInput },
      context: GraphQLContext
    ) => {
      // Idempotency check
      const existing = await context.services.idempotency.find(input.idempotencyKey);
      if (existing) return existing;

      try {
        const order = await context.services.orders.create({
          userId: context.currentUser.id,
          ...input,
        });

        const payload = { order, errors: [] };
        await context.services.idempotency.store(input.idempotencyKey, payload);
        return payload;
      } catch (error) {
        if (error instanceof InsufficientStockError) {
          return {
            order: null,
            errors: [{
              field: ['items'],
              message: `Insufficient stock for product ${error.productId}`,
              code: 'INSUFFICIENT_STOCK',
            }],
          };
        }
        throw error;
      }
    },
  },
};

// DataLoader factory: creates batched loaders per request
function createDataLoaders(services: Services): DataLoaders {
  return {
    orders: new DataLoader(async (ids: readonly string[]) => {
      const orders = await services.orders.findByIds([...ids]);
      const orderMap = new Map(orders.map(o => [o.id, o]));
      return ids.map(id => orderMap.get(id) || null);
    }),

    users: new DataLoader(async (ids: readonly string[]) => {
      const users = await services.users.findByIds([...ids]);
      const userMap = new Map(users.map(u => [u.id, u]));
      return ids.map(id => userMap.get(id) || null);
    }),

    orderItems: new DataLoader(async (orderIds: readonly string[]) => {
      const items = await services.orderItems.findByOrderIds([...orderIds]);
      const grouped = groupBy(items, 'orderId');
      return orderIds.map(id => grouped[id] || []);
    }),

    orderEvents: new DataLoader(async (orderIds: readonly string[]) => {
      const events = await services.orderEvents.findByOrderIds([...orderIds]);
      const grouped = groupBy(events, 'orderId');
      return orderIds.map(id => grouped[id] || []);
    }),
  };
}

API Versioning Strategy /**
 * API versioning with content negotiation and transformation layers.
 * Supports multiple active versions simultaneously with minimal code duplication.
 */
import { Router, Request, Response, NextFunction } from 'express';

interface VersionConfig {
  version: number;
  deprecated?: boolean;
  sunsetDate?: string;
  transformResponse: (data: any) => any;
  transformRequest: (data: any) => any;
}

const versionConfigs: Map<number, VersionConfig> = new Map([
  [1, {
    version: 1,
    deprecated: true,
    sunsetDate: '2025-06-01',
    transformResponse: (order: InternalOrder) => ({
      id: order.id,
      status: order.status,
      total: order.totalCents / 100, // V1 used dollars (breaking change in V2)
      currency: order.currency,
      items: order.items.map(item => ({
        product_id: item.productId, // V1 used snake_case
        quantity: item.quantity,
        price: item.unitPriceCents / 100,
      })),
      created_at: order.createdAt.toISOString(),
    }),
    transformRequest: (data: any) => ({
      ...data,
      totalCents: Math.round(data.total * 100),
      items: data.items?.map((item: any) => ({
        productId: item.product_id,
        quantity: item.quantity,
        unitPriceCents: Math.round(item.price * 100),
      })),
    }),
  }],
  [2, {
    version: 2,
    transformResponse: (order: InternalOrder) => ({
      id: order.id,
      status: order.status,
      totalAmount: {
        cents: order.totalCents,       // V2 uses cents (no floating point)
        currency: order.currency,
        formatted: formatMoney(order.totalCents, order.currency),
      },
      items: order.items.map(item => ({
        productId: item.productId,     // V2 uses camelCase
        quantity: item.quantity,
        unitPrice: {
          cents: item.unitPriceCents,
          currency: order.currency,
          formatted: formatMoney(item.unitPriceCents, order.currency),
        },
      })),
      createdAt: order.createdAt.toISOString(),
      _links: {                        // V2 adds HATEOAS links
        self: { href: `/api/v2/orders/${order.id}` },
        cancel: order.status === 'PENDING'
          ? { href: `/api/v2/orders/${order.id}/cancel`, method: 'POST' }
          : undefined,
        customer: { href: `/api/v2/users/${order.customerId}` },
      },
    }),
    transformRequest: (data: any) => data, // V2 matches internal format
  }],
]);

/**
 * Version extraction middleware.
 * Supports URL path versioning (/v1/, /v2/) and Accept header versioning.
 */
function extractVersion(req: Request, res: Response, next: NextFunction): void {
  // Try URL path first: /api/v2/orders
  const pathMatch = req.path.match(/\/v(\d+)\//);
  if (pathMatch) {
    req.apiVersion = parseInt(pathMatch[1]);
    next();
    return;
  }

  // Fall back to Accept header: application/vnd.myapi+json;version=2
  const accept = req.headers.accept || '';
  const headerMatch = accept.match(/version=(\d+)/);
  if (headerMatch) {
    req.apiVersion = parseInt(headerMatch[1]);
    next();
    return;
  }

  // Default to latest version
  req.apiVersion = 2;
  next();
}

/**
 * Response transformation middleware.
 * Applies version-specific transformations and adds deprecation headers.
 */
function versionedResponse(req: Request, res: Response, next: NextFunction): void {
  const originalJson = res.json.bind(res);

  res.json = (data: any) => {
    const config = versionConfigs.get(req.apiVersion);
    if (!config) {
      return originalJson({ error: 'Unsupported API version' });
    }

    // Add deprecation headers for old versions
    if (config.deprecated) {
      res.setHeader('Deprecation', 'true');
      res.setHeader('Sunset', config.sunsetDate!);
      res.setHeader('Link', `</api/v2${req.path}>; rel="successor-version"`);
    }

    // Add version header
    res.setHeader('X-API-Version', config.version.toString());

    // Transform response data
    const transformed = Array.isArray(data)
      ? data.map(config.transformResponse)
      : config.transformResponse(data);

    return originalJson(transformed);
  };

  next();
}

URL Shortener Service /**
 * URL shortener with distributed ID generation and analytics.
 * Uses a counter-based approach with base62 encoding for short, predictable URLs.
 * Handles 10,000 writes/sec and 1,000,000 reads/sec.
 */
@Service
public class UrlShortenerService {
    private final UrlRepository urlRepository;
    private final RedisTemplate<String, String> cache;
    private final DistributedIdGenerator idGenerator;
    private final AnalyticsPublisher analytics;
    private static final String BASE62_CHARS =
        "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    private static final int SHORT_URL_LENGTH = 7; // 62^7 = 3.5 trillion combinations

    /**
     * Create a short URL. Uses distributed counter for globally unique IDs.
     * Counter ranges are pre-allocated to each instance to avoid coordination.
     */
    public ShortUrlResponse createShortUrl(CreateShortUrlRequest request) {
        // Validate URL
        if (!isValidUrl(request.getLongUrl())) {
            throw new InvalidUrlException("Invalid URL format: " + request.getLongUrl());
        }

        // Check for existing mapping (deduplication)
        Optional<UrlMapping> existing = urlRepository.findByLongUrl(request.getLongUrl());
        if (existing.isPresent()) {
            return toResponse(existing.get());
        }

        // Generate unique short code using distributed counter
        long uniqueId = idGenerator.nextId(); // Snowflake-like ID
        String shortCode = encodeBase62(uniqueId);

        // Ensure exactly SHORT_URL_LENGTH characters
        shortCode = padOrTruncate(shortCode, SHORT_URL_LENGTH);

        UrlMapping mapping = UrlMapping.builder()
            .shortCode(shortCode)
            .longUrl(request.getLongUrl())
            .userId(request.getUserId())
            .expiresAt(request.getExpiresAt())
            .createdAt(Instant.now())
            .build();

        urlRepository.save(mapping);

        // Pre-warm cache for immediate reads
        cache.opsForValue().set(
            "url:" + shortCode,
            request.getLongUrl(),
            Duration.ofDays(30)
        );

        return toResponse(mapping);
    }

    /**
     * Resolve short URL to long URL with caching and analytics.
     * Read path is optimized for extreme throughput (1M+ reads/sec).
     */
    public ResolveResult resolve(String shortCode, HttpServletRequest httpRequest) {
        // L1: Check Redis cache (sub-millisecond)
        String cachedUrl = cache.opsForValue().get("url:" + shortCode);
        if (cachedUrl != null) {
            // Async analytics: don't block the redirect
            publishAnalyticsAsync(shortCode, httpRequest);
            return new ResolveResult(cachedUrl, true);
        }

        // L2: Database lookup
        UrlMapping mapping = urlRepository.findByShortCode(shortCode)
            .orElseThrow(() -> new ShortUrlNotFoundException(shortCode));

        // Check expiration
        if (mapping.getExpiresAt() != null && mapping.getExpiresAt().isBefore(Instant.now())) {
            throw new ShortUrlExpiredException(shortCode);
        }

        // Populate cache for future reads
        cache.opsForValue().set(
            "url:" + shortCode,
            mapping.getLongUrl(),
            Duration.ofDays(30)
        );

        publishAnalyticsAsync(shortCode, httpRequest);
        return new ResolveResult(mapping.getLongUrl(), false);
    }

    /**
     * Base62 encoding: converts numeric ID to alphanumeric string.
     * 62^7 gives 3.5 trillion unique codes, sufficient for most use cases.
     */
    private String encodeBase62(long number) {
        StringBuilder sb = new StringBuilder();
        while (number > 0) {
            sb.append(BASE62_CHARS.charAt((int) (number % 62)));
            number /= 62;
        }
        return sb.reverse().toString();
    }

    private void publishAnalyticsAsync(String shortCode, HttpServletRequest request) {
        CompletableFuture.runAsync(() -> {
            analytics.publish(ClickEvent.builder()
                .shortCode(shortCode)
                .timestamp(Instant.now())
                .userAgent(request.getHeader("User-Agent"))
                .referer(request.getHeader("Referer"))
                .ipAddress(request.getRemoteAddr())
                .country(geoIpService.getCountry(request.getRemoteAddr()))
                .build());
        });
    }
}

/**
 * Distributed ID generator using Snowflake-like approach.
 * Each instance gets a unique worker ID and generates IDs locally
 * without coordination, ensuring global uniqueness.
 */
public class DistributedIdGenerator {
    private static final long EPOCH = 1704067200000L; // 2024-01-01
    private static final int WORKER_ID_BITS = 10;     // 1024 workers
    private static final int SEQUENCE_BITS = 12;      // 4096 per millisecond

    private final long workerId;
    private long lastTimestamp = -1L;
    private long sequence = 0L;

    public DistributedIdGenerator(long workerId) {
        if (workerId < 0 || workerId >= (1L << WORKER_ID_BITS)) {
            throw new IllegalArgumentException("Worker ID out of range");
        }
        this.workerId = workerId;
    }

    public synchronized long nextId() {
        long timestamp = System.currentTimeMillis();

        if (timestamp == lastTimestamp) {
            sequence = (sequence + 1) & ((1L << SEQUENCE_BITS) - 1);
            if (sequence == 0) {
                // Sequence exhausted: wait for next millisecond
                timestamp = waitNextMillis(lastTimestamp);
            }
        } else {
            sequence = 0;
        }

        if (timestamp < lastTimestamp) {
            throw new RuntimeException("Clock moved backwards");
        }

        lastTimestamp = timestamp;

        return ((timestamp - EPOCH) << (WORKER_ID_BITS + SEQUENCE_BITS))
            | (workerId << SEQUENCE_BITS)
            | sequence;
    }

    private long waitNextMillis(long lastTimestamp) {
        long timestamp = System.currentTimeMillis();
        while (timestamp <= lastTimestamp) {
            timestamp = System.currentTimeMillis();
        }
        return timestamp;
    }
}

Real-Time Chat System import { WebSocket, WebSocketServer } from 'ws';
import { Redis } from 'ioredis';

/**
 * Distributed chat system supporting 1:1 and group messaging.
 * Uses WebSocket for real-time delivery with Redis Pub/Sub for
 * cross-instance message routing.
 */
interface ChatMessage {
  messageId: string;
  conversationId: string;
  senderId: string;
  content: string;
  type: 'text' | 'image' | 'file';
  timestamp: number;
  sequenceNumber: number; // Per-conversation ordering
}

interface UserConnection {
  userId: string;
  socket: WebSocket;
  deviceId: string;
  connectedAt: number;
}

class ChatServer {
  private connections: Map<string, UserConnection[]> = new Map(); // userId -> connections
  private redis: Redis;
  private redisSub: Redis;
  private serverId: string;

  constructor(redis: Redis) {
    this.redis = redis;
    this.redisSub = redis.duplicate();
    this.serverId = generateServerId();
    this.subscribeToMessages();
  }

  /**
   * Handle new WebSocket connection.
   * Authenticates user, registers connection, and delivers offline messages.
   */
  async handleConnection(socket: WebSocket, token: string): Promise<void> {
    const user = await this.authenticate(token);
    if (!user) {
      socket.close(4001, 'Authentication failed');
      return;
    }

    const connection: UserConnection = {
      userId: user.id,
      socket,
      deviceId: user.deviceId,
      connectedAt: Date.now(),
    };

    // Register connection locally and in Redis (for cross-instance routing)
    this.addConnection(user.id, connection);
    await this.redis.sadd(`user:${user.id}:servers`, this.serverId);
    await this.redis.set(`user:${user.id}:online`, '1', 'EX', 300);

    // Deliver offline messages
    const offlineMessages = await this.getOfflineMessages(user.id);
    for (const msg of offlineMessages) {
      socket.send(JSON.stringify({ type: 'message', data: msg }));
    }
    await this.clearOfflineMessages(user.id);

    // Publish presence update
    await this.publishPresence(user.id, 'online');

    // Handle incoming messages
    socket.on('message', (data) => this.handleIncomingMessage(user.id, data));
    socket.on('close', () => this.handleDisconnect(user.id, connection));

    // Start heartbeat for presence detection
    this.startHeartbeat(user.id, socket);
  }

  /**
   * Send message to a conversation (1:1 or group).
   * Ensures ordering via per-conversation sequence numbers.
   */
  async sendMessage(senderId: string, request: SendMessageRequest): Promise<ChatMessage> {
    // Generate globally unique message ID and per-conversation sequence number
    const messageId = generateId();
    const sequenceNumber = await this.redis.incr(
      `conversation:${request.conversationId}:seq`
    );

    const message: ChatMessage = {
      messageId,
      conversationId: request.conversationId,
      senderId,
      content: request.content,
      type: request.type || 'text',
      timestamp: Date.now(),
      sequenceNumber,
    };

    // Persist message (write to database)
    await this.persistMessage(message);

    // Get all members of the conversation
    const members = await this.getConversationMembers(request.conversationId);

    // Deliver to each member
    for (const memberId of members) {
      if (memberId === senderId) continue; // Don't echo back to sender

      const isOnline = await this.isUserOnline(memberId);
      if (isOnline) {
        // Publish via Redis Pub/Sub for cross-instance delivery
        await this.redis.publish(
          `user:${memberId}:messages`,
          JSON.stringify(message)
        );
      } else {
        // Store for offline delivery
        await this.storeOfflineMessage(memberId, message);
        // Trigger push notification
        await this.triggerPushNotification(memberId, message);
      }
    }

    // Send delivery receipt to sender
    return message;
  }

  /**
   * Subscribe to Redis Pub/Sub for cross-instance message delivery.
   * When a message is published for a user connected to this instance,
   * deliver it via their WebSocket connection.
   */
  private subscribeToMessages(): void {
    this.redisSub.psubscribe('user:*:messages');
    this.redisSub.on('pmessage', (pattern, channel, data) => {
      const userId = channel.split(':')[1];
      const connections = this.connections.get(userId);

      if (connections) {
        const message = JSON.parse(data);
        for (const conn of connections) {
          if (conn.socket.readyState === WebSocket.OPEN) {
            conn.socket.send(JSON.stringify({ type: 'message', data: message }));
          }
        }
      }
    });
  }

  /**
   * Heartbeat-based presence detection.
   * If heartbeat is missed for 30 seconds, mark user as offline.
   */
  private startHeartbeat(userId: string, socket: WebSocket): void {
    const interval = setInterval(async () => {
      if (socket.readyState !== WebSocket.OPEN) {
        clearInterval(interval);
        return;
      }

      // Refresh presence TTL
      await this.redis.set(`user:${userId}:online`, '1', 'EX', 30);
      socket.ping();
    }, 10000); // Ping every 10 seconds

    socket.on('close', () => clearInterval(interval));
  }

  private async handleDisconnect(userId: string, connection: UserConnection): Promise<void> {
    this.removeConnection(userId, connection);

    // Check if user has any remaining connections
    const remaining = this.connections.get(userId);
    if (!remaining || remaining.length === 0) {
      await this.redis.srem(`user:${userId}:servers`, this.serverId);

      // Check if user is connected to any other server
      const serverCount = await this.redis.scard(`user:${userId}:servers`);
      if (serverCount === 0) {
        await this.redis.del(`user:${userId}:online`);
        await this.publishPresence(userId, 'offline');
      }
    }
  }

  private addConnection(userId: string, conn: UserConnection): void {
    const existing = this.connections.get(userId) || [];
    existing.push(conn);
    this.connections.set(userId, existing);
  }

  private removeConnection(userId: string, conn: UserConnection): void {
    const existing = this.connections.get(userId) || [];
    const filtered = existing.filter(c => c.deviceId !== conn.deviceId);
    if (filtered.length === 0) {
      this.connections.delete(userId);
    } else {
      this.connections.set(userId, filtered);
    }
  }
}

News Feed Generation with Hybrid Fan-Out /**
 * News feed service using hybrid fan-out strategy.
 * Fan-out-on-write for normal users (pre-compute feeds).
 * Fan-out-on-read for celebrity users (compute at read time).
 * Threshold: users with >10,000 followers use fan-out-on-read.
 */
@Service
public class NewsFeedService {
    private final RedisTemplate<String, String> redis;
    private final PostRepository postRepository;
    private final FollowerRepository followerRepository;
    private final RankingService rankingService;
    private static final int CELEBRITY_THRESHOLD = 10_000;
    private static final int FEED_CACHE_SIZE = 500;
    private static final int FEED_PAGE_SIZE = 20;

    /**
     * Publish a new post: fan-out to followers' feeds.
     * For normal users: write to all followers' cached feeds immediately.
     * For celebrities: skip fan-out; their posts are merged at read time.
     */
    public void publishPost(Post post) {
        // Persist the post
        postRepository.save(post);

        long followerCount = followerRepository.countFollowers(post.getAuthorId());

        if (followerCount <= CELEBRITY_THRESHOLD) {
            // Fan-out-on-write: push to all followers' feeds
            fanOutOnWrite(post);
        } else {
            // Celebrity: only add to their own timeline
            // Followers will pull this at read time
            redis.opsForZSet().add(
                "timeline:" + post.getAuthorId(),
                post.getId(),
                post.getCreatedAt().toEpochMilli()
            );
        }
    }

    /**
     * Fan-out-on-write: push post to each follower's feed cache.
     * Uses async processing to avoid blocking the publisher.
     */
    private void fanOutOnWrite(Post post) {
        // Process in batches to avoid memory issues with large follower lists
        long offset = 0;
        int batchSize = 1000;

        while (true) {
            List<String> followerBatch = followerRepository
                .getFollowerIds(post.getAuthorId(), offset, batchSize);

            if (followerBatch.isEmpty()) break;

            // Async fan-out to each follower's feed
            for (String followerId : followerBatch) {
                CompletableFuture.runAsync(() -> {
                    String feedKey = "feed:" + followerId;
                    redis.opsForZSet().add(feedKey, post.getId(),
                        post.getCreatedAt().toEpochMilli());

                    // Trim feed to prevent unbounded growth
                    redis.opsForZSet().removeRange(feedKey, 0,
                        -(FEED_CACHE_SIZE + 1));
                });
            }

            offset += batchSize;
        }
    }

    /**
     * Get user's feed: merge pre-computed feed with celebrity posts.
     * Applies ranking algorithm to determine final ordering.
     */
    public FeedResponse getFeed(String userId, String cursor, int limit) {
        limit = Math.min(limit, FEED_PAGE_SIZE);

        // Get pre-computed feed entries (from fan-out-on-write)
        double maxScore = cursor != null ? Double.parseDouble(cursor) : Double.MAX_VALUE;
        Set<String> feedPostIds = redis.opsForZSet().reverseRangeByScore(
            "feed:" + userId, 0, maxScore, 0, limit + 10 // Fetch extra for merging
        );

        // Get posts from celebrities this user follows (fan-out-on-read)
        List<String> celebrityFollowing = followerRepository
            .getCelebrityFollowing(userId, CELEBRITY_THRESHOLD);

        Set<String> celebrityPostIds = new HashSet<>();
        for (String celebrityId : celebrityFollowing) {
            Set<String> posts = redis.opsForZSet().reverseRangeByScore(
                "timeline:" + celebrityId, 0, maxScore, 0, limit
            );
            celebrityPostIds.addAll(posts);
        }

        // Merge and deduplicate
        Set<String> allPostIds = new LinkedHashSet<>();
        allPostIds.addAll(feedPostIds);
        allPostIds.addAll(celebrityPostIds);

        // Fetch full post objects
        List<Post> posts = postRepository.findByIds(new ArrayList<>(allPostIds));

        // Apply ranking (engagement score, recency, relevance)
        List<RankedPost> rankedPosts = rankingService.rank(posts, userId);

        // Paginate
        List<RankedPost> page = rankedPosts.stream()
            .limit(limit)
            .toList();

        String nextCursor = page.isEmpty() ? null :
            String.valueOf(page.get(page.size() - 1).getPost().getCreatedAt().toEpochMilli());

        return new FeedResponse(
            page.stream().map(this::toFeedItem).toList(),
            nextCursor,
            page.size() == limit
        );
    }

    /**
     * Ranking service: scores posts based on multiple signals.
     * Combines recency, engagement, and user affinity.
     */
    @Service
    static class RankingService {
        public List<RankedPost> rank(List<Post> posts, String userId) {
            return posts.stream()
                .map(post -> {
                    double score = calculateScore(post, userId);
                    return new RankedPost(post, score);
                })
                .sorted(Comparator.comparingDouble(RankedPost::getScore).reversed())
                .toList();
        }

        private double calculateScore(Post post, String userId) {
            double recencyScore = calculateRecency(post.getCreatedAt());
            double engagementScore = calculateEngagement(post);
            double affinityScore = calculateAffinity(post.getAuthorId(), userId);

            // Weighted combination
            return 0.3 * recencyScore + 0.4 * engagementScore + 0.3 * affinityScore;
        }

        private double calculateRecency(Instant createdAt) {
            long ageHours = Duration.between(createdAt, Instant.now()).toHours();
            return Math.exp(-ageHours / 24.0); // Exponential decay over 24 hours
        }

        private double calculateEngagement(Post post) {
            // Normalize engagement metrics
            double likes = Math.log1p(post.getLikeCount());
            double comments = Math.log1p(post.getCommentCount()) * 2; // Comments weighted higher
            double shares = Math.log1p(post.getShareCount()) * 3;
            return (likes + comments + shares) / 10.0;
        }

        private double calculateAffinity(String authorId, String userId) {
            // Based on historical interaction frequency
            // (simplified: would use ML model in production)
            return 0.5; // Placeholder
        }
    }
}

Apache Kafka Streams — Real-Time Event Processing // Kafka Streams topology for real-time order analytics
@Configuration
public class OrderAnalyticsTopology {

    @Bean
    public KStream<String, OrderEvent> orderAnalyticsStream(StreamsBuilder builder) {
        // Source: order events topic
        KStream<String, OrderEvent> orders = builder.stream(
            "order-events",
            Consumed.with(Serdes.String(), orderEventSerde())
        );

        // Branch: separate completed orders from cancellations
        Map<String, KStream<String, OrderEvent>> branches = orders
            .split(Named.as("order-"))
            .branch((key, event) -> event.getStatus() == OrderStatus.COMPLETED,
                    Branched.as("completed"))
            .branch((key, event) -> event.getStatus() == OrderStatus.CANCELLED,
                    Branched.as("cancelled"))
            .defaultBranch(Branched.as("other"));

        KStream<String, OrderEvent> completedOrders = branches.get("order-completed");

        // Windowed aggregation: revenue per category per 5-minute window
        KTable<Windowed<String>, RevenueAggregate> revenueByCategory = completedOrders
            .groupBy((key, order) -> order.getCategory(),
                     Grouped.with(Serdes.String(), orderEventSerde()))
            .windowedBy(TimeWindows.ofSizeWithNoGrace(Duration.ofMinutes(5)))
            .aggregate(
                RevenueAggregate::new,
                (category, order, aggregate) -> aggregate.add(order.getAmount()),
                Materialized.<String, RevenueAggregate, WindowStore<Bytes, byte[]>>as(
                    "revenue-by-category-store")
                    .withKeySerde(Serdes.String())
                    .withValueSerde(revenueAggregateSerde())
            );

        // Sink: write aggregated results to output topic
        revenueByCategory.toStream()
            .map((windowedKey, aggregate) -> KeyValue.pair(
                windowedKey.key(),
                new CategoryRevenue(
                    windowedKey.key(),
                    aggregate.getTotalRevenue(),
                    aggregate.getOrderCount(),
                    windowedKey.window().startTime(),
                    windowedKey.window().endTime()
                )))
            .to("category-revenue", Produced.with(Serdes.String(), categoryRevenueSerde()));

        // Enrichment: join orders with customer data
        GlobalKTable<String, CustomerProfile> customers = builder.globalTable(
            "customer-profiles",
            Consumed.with(Serdes.String(), customerProfileSerde())
        );

        KStream<String, EnrichedOrder> enrichedOrders = completedOrders.join(
            customers,
            (key, order) -> order.getCustomerId(),
            (order, customer) -> EnrichedOrder.builder()
                .orderId(order.getOrderId())
                .customerTier(customer.getTier())
                .customerRegion(customer.getRegion())
                .amount(order.getAmount())
                .category(order.getCategory())
                .build()
        );

        enrichedOrders.to("enriched-orders",
            Produced.with(Serdes.String(), enrichedOrderSerde()));

        return orders;
    }
}

Apache Flink — Stateful Stream Processing with Exactly-Once // Flink job for fraud detection with complex event processing
public class FraudDetectionJob {

    public static void main(String[] args) throws Exception {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Enable exactly-once checkpointing
        env.enableCheckpointing(60_000, CheckpointingMode.EXACTLY_ONCE);
        env.getCheckpointConfig().setMinPauseBetweenCheckpoints(30_000);
        env.getCheckpointConfig().setCheckpointTimeout(120_000);
        env.getCheckpointConfig().setMaxConcurrentCheckpoints(1);
        env.getCheckpointConfig().setExternalizedCheckpointCleanup(
            ExternalizedCheckpointCleanup.RETAIN_ON_CANCELLATION);

        // Source: Kafka transactions topic
        KafkaSource<Transaction> source = KafkaSource.<Transaction>builder()
            .setBootstrapServers("kafka:9092")
            .setTopics("transactions")
            .setGroupId("fraud-detection")
            .setStartingOffsets(OffsetsInitializer.committedOffsets(OffsetResetStrategy.EARLIEST))
            .setDeserializer(new TransactionDeserializer())
            .build();

        DataStream<Transaction> transactions = env.fromSource(
            source, WatermarkStrategy
                .<Transaction>forBoundedOutOfOrderness(Duration.ofSeconds(5))
                .withTimestampAssigner((txn, ts) -> txn.getTimestamp()),
            "Kafka Transactions"
        );

        // Pattern: detect rapid successive transactions from same account
        Pattern<Transaction, ?> fraudPattern = Pattern.<Transaction>begin("first")
            .where(new SimpleCondition<Transaction>() {
                @Override
                public boolean filter(Transaction txn) {
                    return txn.getAmount() > 1000;
                }
            })
            .next("second")
            .where(new SimpleCondition<Transaction>() {
                @Override
                public boolean filter(Transaction txn) {
                    return txn.getAmount() > 1000;
                }
            })
            .within(Duration.ofMinutes(5));

        DataStream<Transaction> keyedTransactions = transactions
            .keyBy(Transaction::getAccountId);

        PatternStream<Transaction> patternStream = CEP.pattern(
            keyedTransactions, fraudPattern);

        DataStream<FraudAlert> alerts = patternStream.process(
            new PatternProcessFunction<Transaction, FraudAlert>() {
                @Override
                public void processMatch(Map<String, List<Transaction>> match,
                                         Context ctx, Collector<FraudAlert> out) {
                    Transaction first = match.get("first").get(0);
                    Transaction second = match.get("second").get(0);
                    out.collect(new FraudAlert(
                        first.getAccountId(),
                        first.getAmount() + second.getAmount(),
                        "Rapid high-value transactions detected",
                        Instant.now()
                    ));
                }
            });

        // Sink: write alerts to Kafka and Elasticsearch
        alerts.sinkTo(KafkaSink.<FraudAlert>builder()
            .setBootstrapServers("kafka:9092")
            .setRecordSerializer(new FraudAlertSerializer("fraud-alerts"))
            .setDeliveryGuarantee(DeliveryGuarantee.EXACTLY_ONCE)
            .build());

        env.execute("Fraud Detection Pipeline");
    }
}

