Code Examples // Production WebSocket server with rooms, heartbeat, and graceful shutdown
import { WebSocketServer, WebSocket } from 'ws';
import { createServer } from 'https';
import { readFileSync } from 'fs';
import { randomUUID } from 'crypto';

interface Client {
  id: string;
  ws: WebSocket;
  rooms: Set<string>;
  lastPong: number;
  metadata: Record<string, unknown>;
}

class WebSocketBroker {
  private wss: WebSocketServer;
  private clients: Map<string, Client> = new Map();
  private rooms: Map<string, Set<string>> = new Map();
  private heartbeatInterval: NodeJS.Timeout | null = null;
  private isShuttingDown = false;

  constructor(port: number) {
    const server = createServer({
      cert: readFileSync('server.crt'),
      key: readFileSync('server.key'),
    });

    this.wss = new WebSocketServer({ 
      server,
      maxPayload: 1024 * 1024, // 1MB max message size
      perMessageDeflate: {
        zlibDeflateOptions: { chunkSize: 1024, memLevel: 7, level: 3 },
        threshold: 128, // Only compress messages > 128 bytes
      },
    });

    this.wss.on('connection', (ws, req) => this.handleConnection(ws, req));
    server.listen(port, () => console.log(`WSS listening on port ${port}`));

    // Start heartbeat checker
    this.heartbeatInterval = setInterval(() => this.checkHeartbeats(), 30000);
  }

  private handleConnection(ws: WebSocket, req: any): void {
    if (this.isShuttingDown) {
      ws.close(1012, 'Server restarting');
      return;
    }

    const clientId = randomUUID();
    const client: Client = {
      id: clientId,
      ws,
      rooms: new Set(),
      lastPong: Date.now(),
      metadata: { ip: req.socket.remoteAddress, connectedAt: Date.now() },
    };

    this.clients.set(clientId, client);
    console.log(`Client connected: ${clientId} (total: ${this.clients.size})`);

    // Send connection acknowledgment
    this.send(ws, { type: 'connected', clientId, timestamp: Date.now() });

    ws.on('pong', () => {
      client.lastPong = Date.now();
    });

    ws.on('message', (data) => {
      try {
        const message = JSON.parse(data.toString());
        this.handleMessage(client, message);
      } catch (err) {
        this.send(ws, { type: 'error', message: 'Invalid JSON' });
      }
    });

    ws.on('close', (code, reason) => {
      console.log(`Client disconnected: ${clientId} (code: ${code})`);
      this.removeClient(clientId);
    });

    ws.on('error', (err) => {
      console.error(`WebSocket error for ${clientId}:`, err.message);
      this.removeClient(clientId);
    });
  }

  private handleMessage(client: Client, message: any): void {
    switch (message.type) {
      case 'join':
        this.joinRoom(client, message.room);
        break;
      case 'leave':
        this.leaveRoom(client, message.room);
        break;
      case 'broadcast':
        this.broadcastToRoom(message.room, {
          type: 'message',
          from: client.id,
          room: message.room,
          payload: message.payload,
          timestamp: Date.now(),
        }, client.id);
        break;
      case 'direct':
        this.sendToClient(message.targetId, {
          type: 'direct',
          from: client.id,
          payload: message.payload,
          timestamp: Date.now(),
        });
        break;
    }
  }

  private joinRoom(client: Client, room: string): void {
    client.rooms.add(room);
    if (!this.rooms.has(room)) {
      this.rooms.set(room, new Set());
    }
    this.rooms.get(room)!.add(client.id);
    this.send(client.ws, { type: 'joined', room, members: this.rooms.get(room)!.size });
  }

  private leaveRoom(client: Client, room: string): void {
    client.rooms.delete(room);
    this.rooms.get(room)?.delete(client.id);
    if (this.rooms.get(room)?.size === 0) {
      this.rooms.delete(room);
    }
  }

  private broadcastToRoom(room: string, message: any, excludeId?: string): void {
    const members = this.rooms.get(room);
    if (!members) return;

    const payload = JSON.stringify(message);
    for (const memberId of members) {
      if (memberId === excludeId) continue;
      const client = this.clients.get(memberId);
      if (client?.ws.readyState === WebSocket.OPEN) {
        client.ws.send(payload);
      }
    }
  }

  private sendToClient(targetId: string, message: any): void {
    const client = this.clients.get(targetId);
    if (client?.ws.readyState === WebSocket.OPEN) {
      this.send(client.ws, message);
    }
  }

  private send(ws: WebSocket, message: any): void {
    if (ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify(message));
    }
  }

  private removeClient(clientId: string): void {
    const client = this.clients.get(clientId);
    if (!client) return;

    // Remove from all rooms
    for (const room of client.rooms) {
      this.rooms.get(room)?.delete(clientId);
      if (this.rooms.get(room)?.size === 0) {
        this.rooms.delete(room);
      }
    }
    this.clients.delete(clientId);
  }

  private checkHeartbeats(): void {
    const now = Date.now();
    const timeout = 60000; // 60 seconds without pong = dead

    for (const [id, client] of this.clients) {
      if (now - client.lastPong > timeout) {
        console.log(`Heartbeat timeout for ${id}`);
        client.ws.terminate(); // Force close without close handshake
        this.removeClient(id);
      } else {
        client.ws.ping(); // Send ping, expect pong
      }
    }
  }

  async gracefulShutdown(): Promise<void> {
    this.isShuttingDown = true;
    if (this.heartbeatInterval) clearInterval(this.heartbeatInterval);

    // Notify all clients of impending shutdown
    for (const [, client] of this.clients) {
      client.ws.close(1012, 'Server shutting down');
    }

    // Wait for connections to close (max 30 seconds)
    await new Promise<void>((resolve) => {
      const check = setInterval(() => {
        if (this.clients.size === 0) {
          clearInterval(check);
          resolve();
        }
      }, 100);
      setTimeout(() => { clearInterval(check); resolve(); }, 30000);
    });

    this.wss.close();
  }
} // WebSocket client with automatic reconnection, exponential backoff, and message queuing

interface ReconnectConfig {
  initialDelay: number;   // seconds
  maxDelay: number;       // seconds
  multiplier: number;
  jitter: number;         // Random jitter factor
  maxAttempts: number;    // 0 = unlimited
}

interface WebSocketMessage {
  type: string;
  payload: unknown;
  timestamp: number;
}

type EventHandler = (data: unknown) => void | Promise<void>;

class ResilientWebSocketClient {
  /** WebSocket client with automatic reconnection and message queuing. */

  private url: string;
  private config: ReconnectConfig;
  private ws: WebSocket | null = null;
  private running = false;
  private reconnectAttempt = 0;
  private messageQueue: string[] = [];
  private readonly maxQueueSize = 1000;
  private handlers: Map<string, EventHandler[]> = new Map();
  private connectedResolve: (() => void) | null = null;

  constructor(url: string, config?: Partial<ReconnectConfig>) {
    this.url = url;
    this.config = {
      initialDelay: config?.initialDelay ?? 1.0,
      maxDelay: config?.maxDelay ?? 60.0,
      multiplier: config?.multiplier ?? 2.0,
      jitter: config?.jitter ?? 0.5,
      maxAttempts: config?.maxAttempts ?? 0,
    };
  }

  /** Register event handler for message types. */
  on(eventType: string, handler: EventHandler): void {
    if (!this.handlers.has(eventType)) {
      this.handlers.set(eventType, []);
    }
    this.handlers.get(eventType)!.push(handler);
  }

  /** Start the connection with automatic reconnection. */
  async connect(): Promise<void> {
    this.running = true;

    while (this.running) {
      try {
        await this.attemptConnection();
      } catch (error) {
        const reason = error instanceof Error ? error.message : String(error);
        console.log(`Connection failed: ${reason}`);
        this.emit('error', { error: reason });
      }

      this.ws = null;

      if (!this.running) break;

      // Exponential backoff with jitter
      const delay = this.calculateBackoff();
      console.log(`Reconnecting in ${delay.toFixed(1)}s (attempt ${this.reconnectAttempt + 1})`);
      await this.sleep(delay * 1000);
      this.reconnectAttempt++;

      if (this.config.maxAttempts > 0 && this.reconnectAttempt >= this.config.maxAttempts) {
        console.log('Max reconnection attempts reached');
        this.running = false;
        break;
      }
    }
  }

  private attemptConnection(): Promise<void> {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.url);

      this.ws.onopen = () => {
        this.reconnectAttempt = 0;
        console.log(`Connected to ${this.url}`);
        this.emit('connected', {});

        // Flush queued messages
        this.flushQueue();
      };

      this.ws.onmessage = (event: MessageEvent) => {
        this.handleMessage(event.data as string);
      };

      this.ws.onclose = (event: CloseEvent) => {
        console.log(`Connection closed: code=${event.code} reason=${event.reason}`);
        this.emit('disconnected', { code: event.code, reason: event.reason });
        resolve();
      };

      this.ws.onerror = (event: Event) => {
        reject(new Error('WebSocket error'));
      };
    });
  }

  /** Send message, queuing if disconnected. */
  async send(messageType: string, payload: unknown): Promise<void> {
    const message = JSON.stringify({
      type: messageType,
      payload,
      timestamp: Date.now() / 1000,
    } satisfies WebSocketMessage);

    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      try {
        this.ws.send(message);
      } catch {
        this.enqueue(message);
      }
    } else {
      this.enqueue(message);
    }
  }

  /** Send message and wait for a specific response type. */
  async sendAndWait(messageType: string, payload: unknown,
                    responseType: string, timeout = 10000): Promise<unknown> {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.removeHandler(responseType, handler);
        reject(new Error(`No ${responseType} response within ${timeout}ms`));
      }, timeout);

      const handler: EventHandler = (data) => {
        clearTimeout(timer);
        this.removeHandler(responseType, handler);
        resolve(data);
      };

      this.on(responseType, handler);
      this.send(messageType, payload);
    });
  }

  /** Gracefully close the connection. */
  async close(): Promise<void> {
    this.running = false;
    if (this.ws) {
      this.ws.close(1000, 'Client closing');
    }
  }

  /** Exponential backoff with full jitter. */
  private calculateBackoff(): number {
    const delay = Math.min(
      this.config.initialDelay * (this.config.multiplier ** this.reconnectAttempt),
      this.config.maxDelay
    );
    // Full jitter: random value between 0 and calculated delay
    const jitter = Math.random() * delay * this.config.jitter;
    return delay + jitter;
  }

  /** Send all queued messages after reconnection. */
  private flushQueue(): void {
    while (this.messageQueue.length > 0 && this.ws?.readyState === WebSocket.OPEN) {
      const message = this.messageQueue.shift()!;
      try {
        this.ws.send(message);
      } catch {
        this.messageQueue.unshift(message);
        break;
      }
    }
  }

  /** Parse and dispatch incoming message to handlers. */
  private handleMessage(raw: string): void {
    try {
      const data = JSON.parse(raw) as WebSocketMessage;
      const msgType = data.type ?? 'unknown';
      this.emit(msgType, data.payload ?? data);
    } catch {
      this.emit('raw', raw);
    }
  }

  /** Emit event to registered handlers. */
  private emit(eventType: string, data: unknown): void {
    const handlers = [
      ...(this.handlers.get(eventType) ?? []),
      ...(this.handlers.get('*') ?? []),
    ];
    for (const handler of handlers) {
      handler(data);
    }
  }

  private enqueue(message: string): void {
    if (this.messageQueue.length >= this.maxQueueSize) {
      this.messageQueue.shift(); // Drop oldest
    }
    this.messageQueue.push(message);
  }

  private removeHandler(eventType: string, handler: EventHandler): void {
    const handlers = this.handlers.get(eventType);
    if (handlers) {
      const idx = handlers.indexOf(handler);
      if (idx !== -1) handlers.splice(idx, 1);
    }
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

// Usage
async function main() {
  const client = new ResilientWebSocketClient(
    'wss://api.example.com/ws',
    { initialDelay: 1, maxDelay: 30, jitter: 0.5 }
  );

  client.on('message', (data) => console.log(`Received: ${JSON.stringify(data)}`));
  client.on('connected', () => console.log('Connected!'));

  // Run connection in background
  client.connect();

  // Send messages (queued if not yet connected)
  await new Promise((r) => setTimeout(r, 2000));
  await client.send('subscribe', { channel: 'prices' });

  await new Promise((r) => setTimeout(r, 60000));
  await client.close();
}

main(); // Server-Sent Events (SSE) alternative for unidirectional streaming
package main

import (
    "fmt"
    "net/http"
    "time"
)

// SSEBroker manages SSE client connections and broadcasts
type SSEBroker struct {
    clients    map[chan string]struct{}
    register   chan chan string
    unregister chan chan string
    broadcast  chan string
}

func NewSSEBroker() *SSEBroker {
    b := &SSEBroker{
        clients:    make(map[chan string]struct{}),
        register:   make(chan chan string),
        unregister: make(chan chan string),
        broadcast:  make(chan string, 256),
    }
    go b.run()
    return b
}

func (b *SSEBroker) run() {
    for {
        select {
        case client := <-b.register:
            b.clients[client] = struct{}{}
            fmt.Printf("Client connected (total: %d)\n", len(b.clients))
        case client := <-b.unregister:
            delete(b.clients, client)
            close(client)
            fmt.Printf("Client disconnected (total: %d)\n", len(b.clients))
        case msg := <-b.broadcast:
            for client := range b.clients {
                select {
                case client <- msg:
                default:
                    // Client buffer full, skip (or disconnect)
                    delete(b.clients, client)
                    close(client)
                }
            }
        }
    }
}

func (b *SSEBroker) ServeHTTP(w http.ResponseWriter, r *http.Request) {
    // SSE requires streaming response
    flusher, ok := w.(http.Flusher)
    if !ok {
        http.Error(w, "Streaming not supported", http.StatusInternalServerError)
        return
    }

    // Set SSE headers
    w.Header().Set("Content-Type", "text/event-stream")
    w.Header().Set("Cache-Control", "no-cache")
    w.Header().Set("Connection", "keep-alive")
    w.Header().Set("X-Accel-Buffering", "no") // Disable nginx buffering

    // Register client
    messageChan := make(chan string, 64)
    b.register <- messageChan

    // Clean up on disconnect
    ctx := r.Context()
    defer func() { b.unregister <- messageChan }()

    // Send initial connection event
    fmt.Fprintf(w, "event: connected\ndata: {\"status\":\"ok\"}\n\n")
    flusher.Flush()

    for {
        select {
        case <-ctx.Done():
            return
        case msg, ok := <-messageChan:
            if !ok {
                return
            }
            // SSE format: "data: <payload>\n\n"
            fmt.Fprintf(w, "data: %s\n\n", msg)
            flusher.Flush()
        }
    }
}

func main() {
    broker := NewSSEBroker()

    // Simulate events
    go func() {
        ticker := time.NewTicker(time.Second)
        for t := range ticker.C {
            broker.broadcast <- fmt.Sprintf(
                `{"type":"tick","time":"%s"}`, t.Format(time.RFC3339))
        }
    }()

    http.Handle("/events", broker)
    http.ListenAndServe(":8080", nil)
}

Virtual Memory Page Table Walk Simulation (Java) public class PageTableSimulation {
    private static final int PAGE_SIZE = 4096;
    private static final int ENTRIES_PER_TABLE = 512;
    private static final long PTE_PRESENT = 1L;
    private static final long PTE_WRITABLE = 1L << 1;
    private static final long PTE_USER = 1L << 2;
    private static final long PTE_ACCESSED = 1L << 5;
    private static final long PTE_DIRTY = 1L << 6;
    private static final long PTE_ADDR_MASK = 0x000FFFFFFFFFF000L;

    // Simulated page table: each level is an array of 512 entries
    // Entry stores either a "pointer" (index into table pool) or physical address + flags
    private final long[][] tablePool;
    private int nextTable = 0;
    private long pageFaults = 0;
    private long translations = 0;

    public PageTableSimulation(int maxTables) {
        this.tablePool = new long[maxTables][ENTRIES_PER_TABLE];
    }

    // Extract indices from 48-bit virtual address
    static int pgdIndex(long va) { return (int) ((va >> 39) & 0x1FF); }
    static int pudIndex(long va) { return (int) ((va >> 30) & 0x1FF); }
    static int pmdIndex(long va) { return (int) ((va >> 21) & 0x1FF); }
    static int pteIndex(long va) { return (int) ((va >> 12) & 0x1FF); }
    static long pageOffset(long va) { return va & 0xFFF; }

    // Allocate a new page table, returns its index in the pool
    private int allocPageTable() {
        int idx = nextTable++;
        java.util.Arrays.fill(tablePool[idx], 0);
        return idx;
    }

    // Map a virtual page to a physical frame
    public void mapPage(int pgdIdx, long vaddr, long paddr, long flags) {
        long entry;

        // Walk/create PGD -> PUD
        entry = tablePool[pgdIdx][pgdIndex(vaddr)];
        int pudIdx;
        if ((entry & PTE_PRESENT) == 0) {
            pudIdx = allocPageTable();
            tablePool[pgdIdx][pgdIndex(vaddr)] = ((long) pudIdx << 12) | PTE_PRESENT | PTE_WRITABLE | PTE_USER;
        } else {
            pudIdx = (int) ((entry & PTE_ADDR_MASK) >> 12);
        }

        // Walk/create PUD -> PMD
        entry = tablePool[pudIdx][pudIndex(vaddr)];
        int pmdIdx;
        if ((entry & PTE_PRESENT) == 0) {
            pmdIdx = allocPageTable();
            tablePool[pudIdx][pudIndex(vaddr)] = ((long) pmdIdx << 12) | PTE_PRESENT | PTE_WRITABLE | PTE_USER;
        } else {
            pmdIdx = (int) ((entry & PTE_ADDR_MASK) >> 12);
        }

        // Walk/create PMD -> PTE
        entry = tablePool[pmdIdx][pmdIndex(vaddr)];
        int pteIdx;
        if ((entry & PTE_PRESENT) == 0) {
            pteIdx = allocPageTable();
            tablePool[pmdIdx][pmdIndex(vaddr)] = ((long) pteIdx << 12) | PTE_PRESENT | PTE_WRITABLE | PTE_USER;
        } else {
            pteIdx = (int) ((entry & PTE_ADDR_MASK) >> 12);
        }

        // Set the final PTE
        tablePool[pteIdx][pteIndex(vaddr)] = (paddr & PTE_ADDR_MASK) | flags | PTE_PRESENT;
    }

    // Translate virtual address to physical address
    public long translate(int pgdIdx, long vaddr) {
        translations++;

        long entry = tablePool[pgdIdx][pgdIndex(vaddr)];
        if ((entry & PTE_PRESENT) == 0) { pageFaults++; return 0; }

        int pudIdx = (int) ((entry & PTE_ADDR_MASK) >> 12);
        entry = tablePool[pudIdx][pudIndex(vaddr)];
        if ((entry & PTE_PRESENT) == 0) { pageFaults++; return 0; }

        int pmdIdx = (int) ((entry & PTE_ADDR_MASK) >> 12);
        entry = tablePool[pmdIdx][pmdIndex(vaddr)];
        if ((entry & PTE_PRESENT) == 0) { pageFaults++; return 0; }

        int pteIdx = (int) ((entry & PTE_ADDR_MASK) >> 12);
        entry = tablePool[pteIdx][pteIndex(vaddr)];
        if ((entry & PTE_PRESENT) == 0) { pageFaults++; return 0; }

        // Mark accessed
        tablePool[pteIdx][pteIndex(vaddr)] |= PTE_ACCESSED;

        return (entry & PTE_ADDR_MASK) | pageOffset(vaddr);
    }

    public long getPageFaults() { return pageFaults; }
    public long getTranslations() { return translations; }
}

Memory-Mapped File I/O (Java) import java.io.*;
import java.nio.*;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

// Memory-mapped file for a simple key-value store
public class MappedHashTable {
    private static final int KEY_SIZE = 64;
    private static final int VALUE_SIZE = 256;
    private static final int ENTRY_SIZE = KEY_SIZE + VALUE_SIZE + 4 + 1; // key + value + hash + occupied

    private final MappedByteBuffer buffer;
    private final int capacity;
    private final FileChannel channel;

    public MappedHashTable(Path path, int capacity, boolean create) throws IOException {
        this.capacity = capacity;
        long size = 8L + (long) capacity * ENTRY_SIZE; // count(4) + capacity(4) + entries

        if (create) {
            this.channel = FileChannel.open(path,
                    StandardOpenOption.CREATE, StandardOpenOption.READ, StandardOpenOption.WRITE);
            // Extend file to required size
            channel.truncate(size);
            // Force file to be the right size
            ByteBuffer zero = ByteBuffer.allocate(1);
            channel.write(zero, size - 1);
        } else {
            this.channel = FileChannel.open(path, StandardOpenOption.READ, StandardOpenOption.WRITE);
        }

        // Map file into memory
        this.buffer = channel.map(FileChannel.MapMode.READ_WRITE, 0, size);

        if (create) {
            buffer.putInt(0, 0);         // count = 0
            buffer.putInt(4, capacity);  // capacity
        }
    }

    public void put(String key, String value) {
        int hash = key.hashCode();
        int index = Math.abs(hash) % capacity;

        int offset = 8 + index * ENTRY_SIZE;
        byte[] keyBytes = new byte[KEY_SIZE];
        byte[] valBytes = new byte[VALUE_SIZE];
        System.arraycopy(key.getBytes(StandardCharsets.UTF_8), 0, keyBytes, 0,
                Math.min(key.length(), KEY_SIZE));
        System.arraycopy(value.getBytes(StandardCharsets.UTF_8), 0, valBytes, 0,
                Math.min(value.length(), VALUE_SIZE));

        buffer.position(offset);
        buffer.put(keyBytes);
        buffer.put(valBytes);
        buffer.putInt(hash);
        buffer.put((byte) 1); // occupied

        // Increment count
        buffer.putInt(0, buffer.getInt(0) + 1);
    }

    // Changes are automatically persisted to disk via page cache
    // Use force() for explicit durability guarantees
    public void sync() {
        buffer.force(); // Equivalent to msync - blocks until written to disk
    }

    public void close() throws IOException {
        channel.close();
    }
}

Custom Memory Allocator with Free List (Java) import java.nio.ByteBuffer;

public class ArenaAllocator {
    private static final int ARENA_SIZE = 1024 * 1024; // 1MB arena
    private static final int ALIGNMENT = 16;
    private static final int BLOCK_HEADER_SIZE = align(16); // size(8) + next(4) + free(1) padded

    private final ByteBuffer arena;
    private int freeListHead; // Offset of first free block
    private long allocated = 0;
    private long peakAllocated = 0;

    private static int align(int size) {
        return (size + (ALIGNMENT - 1)) & ~(ALIGNMENT - 1);
    }

    public ArenaAllocator() {
        // Allocate direct buffer (off-heap, similar to mmap anonymous)
        this.arena = ByteBuffer.allocateDirect(ARENA_SIZE);

        // Initialize free list with single large block
        freeListHead = 0;
        setBlockSize(0, ARENA_SIZE - BLOCK_HEADER_SIZE);
        setBlockNext(0, -1); // -1 = null
        setBlockFree(0, true);
    }

    // Block header layout: [size: long (8)] [next: int (4)] [free: byte (1)]
    private long getBlockSize(int offset) { return arena.getLong(offset); }
    private void setBlockSize(int offset, long size) { arena.putLong(offset, size); }
    private int getBlockNext(int offset) { return arena.getInt(offset + 8); }
    private void setBlockNext(int offset, int next) { arena.putInt(offset + 8, next); }
    private boolean isBlockFree(int offset) { return arena.get(offset + 12) != 0; }
    private void setBlockFree(int offset, boolean free) { arena.put(offset + 12, (byte) (free ? 1 : 0)); }

    public int alloc(int requestedSize) {
        int size = align(requestedSize);

        // First-fit search through free list
        int prev = -1;
        int curr = freeListHead;

        while (curr != -1) {
            if (isBlockFree(curr) && getBlockSize(curr) >= size) {
                long currSize = getBlockSize(curr);

                // Split block if remainder is large enough
                if (currSize >= size + BLOCK_HEADER_SIZE + ALIGNMENT) {
                    int newBlock = curr + BLOCK_HEADER_SIZE + size;
                    setBlockSize(newBlock, currSize - size - BLOCK_HEADER_SIZE);
                    setBlockNext(newBlock, getBlockNext(curr));
                    setBlockFree(newBlock, true);

                    setBlockSize(curr, size);
                    setBlockNext(curr, newBlock);
                }

                setBlockFree(curr, false);
                allocated += getBlockSize(curr);
                if (allocated > peakAllocated) peakAllocated = allocated;

                return curr + BLOCK_HEADER_SIZE; // Return offset past header
            }
            prev = curr;
            curr = getBlockNext(curr);
        }

        return -1; // Out of memory
    }

    public void free(int ptr) {
        if (ptr < 0) return;

        int block = ptr - BLOCK_HEADER_SIZE;
        setBlockFree(block, true);
        allocated -= getBlockSize(block);

        // Coalesce adjacent free blocks
        int curr = freeListHead;
        while (curr != -1) {
            int next = getBlockNext(curr);
            if (isBlockFree(curr) && next != -1 && isBlockFree(next)) {
                setBlockSize(curr, getBlockSize(curr) + BLOCK_HEADER_SIZE + getBlockSize(next));
                setBlockNext(curr, getBlockNext(next));
                continue; // Check again in case of multiple adjacent free blocks
            }
            curr = getBlockNext(curr);
        }
    }

    public long getAllocated() { return allocated; }
    public long getPeakAllocated() { return peakAllocated; }
}

LRU Page Replacement Simulation (Java) import java.util.*;

public class LRUPageCache {
    /**Simulates OS page cache with LRU eviction policy.*/

    enum PageState { CLEAN, DIRTY }

    static class PageFrame {
        final int pageNumber;
        PageState state;
        int accessCount;

        PageFrame(int pageNumber, PageState state) {
            this.pageNumber = pageNumber;
            this.state = state;
            this.accessCount = 1;
        }
    }

    private final int numFrames;
    private final LinkedHashMap<Integer, PageFrame> frames;
    private int pageFaults = 0;
    private int diskWrites = 0;
    private int totalAccesses = 0;

    public LRUPageCache(int numFrames) {
        this.numFrames = numFrames;
        // LinkedHashMap with accessOrder=true provides LRU ordering
        this.frames = new LinkedHashMap<>(numFrames, 0.75f, true);
    }

    /** Access a page. Returns true if page was in cache (hit). */
    public boolean access(int pageNumber, boolean write) {
        totalAccesses++;

        if (frames.containsKey(pageNumber)) {
            // Cache hit: LinkedHashMap moves to end on access (most recently used)
            PageFrame frame = frames.get(pageNumber);
            frame.accessCount++;
            if (write) frame.state = PageState.DIRTY;
            return true;
        }

        // Cache miss: page fault
        pageFaults++;

        // Evict LRU page if cache is full
        if (frames.size() >= numFrames) {
            evictLru();
        }

        // Load new page
        PageState state = write ? PageState.DIRTY : PageState.CLEAN;
        frames.put(pageNumber, new PageFrame(pageNumber, state));
        return false;
    }

    private void evictLru() {
        // The first entry in a LinkedHashMap with accessOrder=true is the LRU
        Iterator<Map.Entry<Integer, PageFrame>> iter = frames.entrySet().iterator();
        if (iter.hasNext()) {
            Map.Entry<Integer, PageFrame> entry = iter.next();
            if (entry.getValue().state == PageState.DIRTY) {
                diskWrites++; // Must write back dirty page
            }
            iter.remove();
        }
    }

    public double hitRate() {
        if (totalAccesses == 0) return 0.0;
        return 1.0 - ((double) pageFaults / totalAccesses);
    }

    public Map<String, Object> stats() {
        Map<String, Object> s = new LinkedHashMap<>();
        s.put("total_accesses", totalAccesses);
        s.put("page_faults", pageFaults);
        s.put("disk_writes", diskWrites);
        s.put("hit_rate", String.format("%.2f%%", hitRate() * 100));
        s.put("frames_used", frames.size());
        return s;
    }

    // Simulate a workload
    public static void main(String[] args) {
        LRUPageCache cache = new LRUPageCache(4);
        // Locality-heavy access pattern
        int[] accesses = {1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5, 1, 2, 3};
        for (int page : accesses) {
            boolean hit = cache.access(page, page % 2 == 0);
            String status = hit ? "HIT" : "MISS";
            System.out.printf("Access page %d: %s%n", page, status);
        }

        System.out.println("\nStats: " + cache.stats());
    }
}

Thread-Safe Producer-Consumer Queue with Condition Variables (Java) import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class BoundedBlockingQueue<T> {
    private final Queue<T> queue;
    private final int capacity;
    private final ReentrantLock lock;
    private final Condition notFull;
    private final Condition notEmpty;

    public BoundedBlockingQueue(int capacity) {
        this.capacity = capacity;
        this.queue = new LinkedList<>();
        this.lock = new ReentrantLock();
        this.notFull = lock.newCondition();
        this.notEmpty = lock.newCondition();
    }

    public void put(T item) throws InterruptedException {
        lock.lock();
        try {
            while (queue.size() == capacity) {
                notFull.await();  // Release lock and wait
            }
            queue.offer(item);
            notEmpty.signal();  // Wake one waiting consumer
        } finally {
            lock.unlock();
        }
    }

    public T take() throws InterruptedException {
        lock.lock();
        try {
            while (queue.isEmpty()) {
                notEmpty.await();  // Release lock and wait
            }
            T item = queue.poll();
            notFull.signal();  // Wake one waiting producer
            return item;
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return queue.size();
        } finally {
            lock.unlock();
        }
    }
}

Thread Creation and Parallel Computation (Java) import java.util.concurrent.*;

public class ParallelSum {
    private static final int NUM_THREADS = 4;
    private static final int WORK_ITEMS = 1000;

    static class ComputeTask implements Callable<Long> {
        final int threadId;
        final int start;
        final int end;

        ComputeTask(int threadId, int start, int end) {
            this.threadId = threadId;
            this.start = start;
            this.end = end;
        }

        @Override
        public Long call() {
            long sum = 0;
            for (int i = start; i < end; i++) {
                sum += (long) i * i; // Compute sum of squares
            }
            System.out.printf("Thread %d computed partial sum [%d, %d): %d%n",
                    threadId, start, end, sum);
            return sum;
        }
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS);
        int chunkSize = WORK_ITEMS / NUM_THREADS;

        // Submit tasks with divided work
        Future<Long>[] futures = new Future[NUM_THREADS];
        for (int i = 0; i < NUM_THREADS; i++) {
            int start = i * chunkSize;
            int end = (i == NUM_THREADS - 1) ? WORK_ITEMS : (i + 1) * chunkSize;
            futures[i] = executor.submit(new ComputeTask(i, start, end));
        }

        // Collect results and aggregate
        long total = 0;
        for (int i = 0; i < NUM_THREADS; i++) {
            total += futures[i].get(); // Blocks until thread completes
        }

        System.out.printf("Total sum of squares [0, %d): %d%n", WORK_ITEMS, total);
        executor.shutdown();
    }
}

Process Creation and IPC via Streams (Java) import java.io.*;

public class ProcessIPC {
    public static void main(String[] args) throws Exception {
        // Create a child process that reads from stdin and prints to stdout
        // This demonstrates IPC via process streams (equivalent to pipe + fork)
        ProcessBuilder pb = new ProcessBuilder("cat");
        pb.redirectErrorStream(true);
        Process child = pb.start();

        long parentPid = ProcessHandle.current().pid();
        long childPid = child.pid();

        // Parent process: write to child's stdin (equivalent to pipe write end)
        String message = "Hello from parent process!";
        try (OutputStream os = child.getOutputStream()) {
            os.write(message.getBytes());
            os.flush();
            System.out.printf("Parent (PID %d) sent message to child (PID %d)%n",
                    parentPid, childPid);
        }

        // Read child's stdout (equivalent to pipe read end)
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(child.getInputStream()))) {
            String line = reader.readLine();
            if (line != null) {
                System.out.printf("Child (PID %d) echoed: %s%n", childPid, line);
            }
        }

        // Wait for child to finish (prevents zombie equivalent)
        int exitCode = child.waitFor();
        System.out.printf("Child exited with status %d%n", exitCode);
    }
}

Thread Pool Implementation (Java) import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

public class SimpleThreadPool {
    /**Fixed-size thread pool with work queue.*/

    static class TaskFuture<T> {
        private T result;
        private Exception exception;
        private final CountDownLatch done = new CountDownLatch(1);

        void setResult(T result) {
            this.result = result;
            done.countDown();
        }

        void setException(Exception exc) {
            this.exception = exc;
            done.countDown();
        }

        T result(long timeoutMs) throws Exception {
            done.await(timeoutMs, TimeUnit.MILLISECONDS);
            if (exception != null) throw exception;
            return result;
        }

        T result() throws Exception {
            done.await();
            if (exception != null) throw exception;
            return result;
        }
    }

    private static class WorkItem<T> {
        final Callable<T> task;
        final TaskFuture<T> future;

        WorkItem(Callable<T> task, TaskFuture<T> future) {
            this.task = task;
            this.future = future;
        }
    }

    private final BlockingQueue<WorkItem<?>> workQueue;
    private final Thread[] workers;
    private final AtomicBoolean shutdown = new AtomicBoolean(false);

    public SimpleThreadPool(int numWorkers, int queueSize) {
        this.workQueue = new LinkedBlockingQueue<>(queueSize);
        this.workers = new Thread[numWorkers];

        for (int i = 0; i < numWorkers; i++) {
            workers[i] = new Thread(this::workerLoop, "pool-worker-" + i);
            workers[i].setDaemon(true);
            workers[i].start();
        }
    }

    @SuppressWarnings("unchecked")
    private void workerLoop() {
        while (!shutdown.get()) {
            try {
                WorkItem item = workQueue.poll(1, TimeUnit.SECONDS);
                if (item == null) continue;

                try {
                    Object result = item.task.call();
                    item.future.setResult(result);
                } catch (Exception e) {
                    item.future.setException(e);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    public <T> TaskFuture<T> submit(Callable<T> task) {
        if (shutdown.get()) throw new RejectedExecutionException("Pool is shut down");
        TaskFuture<T> future = new TaskFuture<>();
        try {
            workQueue.put(new WorkItem<>(task, future));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RejectedExecutionException("Interrupted while submitting", e);
        }
        return future;
    }

    public void shutdown(boolean wait) throws InterruptedException {
        shutdown.set(true);
        if (wait) {
            for (Thread worker : workers) {
                worker.join(5000);
            }
        }
    }

    // Usage
    public static void main(String[] args) throws Exception {
        SimpleThreadPool pool = new SimpleThreadPool(4, 1000);
        TaskFuture<?>[] futures = new TaskFuture[20];
        for (int i = 0; i < 20; i++) {
            futures[i] = pool.submit(() -> {
                Thread.sleep(100);
                return null;
            });
        }
        for (TaskFuture<?> f : futures) {
            f.result();
        }
        pool.shutdown(true);
    }
}

Mutex and Condition Variable: Bounded Queue (Java) import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class BoundedQueue<T> {
    private static final int QUEUE_CAPACITY = 64;

    private final Object[] items = new Object[QUEUE_CAPACITY];
    private int head = 0;
    private int tail = 0;
    private int count = 0;
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();
    private volatile boolean shutdown = false;

    // Blocking put - waits if queue is full
    public boolean put(T item) throws InterruptedException {
        lock.lock();
        try {
            while (count == QUEUE_CAPACITY && !shutdown) {
                // Atomically release lock and wait on condition
                // Re-acquires lock when signaled (may be spurious)
                notFull.await();
            }

            if (shutdown) {
                return false;
            }

            items[tail] = item;
            tail = (tail + 1) % QUEUE_CAPACITY;
            count++;

            // Signal one waiting consumer
            notEmpty.signal();
            return true;
        } finally {
            lock.unlock();
        }
    }

    // Blocking take - waits if queue is empty
    @SuppressWarnings("unchecked")
    public T take() throws InterruptedException {
        lock.lock();
        try {
            while (count == 0 && !shutdown) {
                notEmpty.await();
            }

            if (shutdown && count == 0) {
                return null;
            }

            T item = (T) items[head];
            items[head] = null; // Help GC
            head = (head + 1) % QUEUE_CAPACITY;
            count--;

            notFull.signal();
            return item;
        } finally {
            lock.unlock();
        }
    }

    // Graceful shutdown: wake all waiters
    public void shutdown() {
        lock.lock();
        try {
            shutdown = true;
            notFull.signalAll();
            notEmpty.signalAll();
        } finally {
            lock.unlock();
        }
    }
}

Lock-Free Stack (Treiber Stack) with CAS (Java) import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.atomic.AtomicInteger;

public class LockFreeStack<T> {

    private static class Node<T> {
        final T data;
        Node<T> next;

        Node(T data) {
            this.data = data;
        }
    }

    private final AtomicReference<Node<T>> top = new AtomicReference<>(null);
    private final AtomicInteger size = new AtomicInteger(0);

    public void push(T data) {
        Node<T> newNode = new Node<>(data);

        Node<T> oldTop;
        do {
            oldTop = top.get();
            newNode.next = oldTop;
            // CAS: if top still equals oldTop, set it to newNode
            // If another thread pushed/popped, oldTop changed, CAS fails, retry
        } while (!top.compareAndSet(oldTop, newNode));

        size.incrementAndGet();
    }

    public T pop() {
        Node<T> oldTop;
        Node<T> newTop;

        do {
            oldTop = top.get();
            if (oldTop == null) return null; // Stack empty
            newTop = oldTop.next;
            // CAS: if top still equals oldTop, set it to newTop
        } while (!top.compareAndSet(oldTop, newTop));

        size.decrementAndGet();

        // Note: In production, use hazard pointers or epoch-based reclamation
        // to safely reclaim oldTop (another thread might still be reading it).
        // Java's GC handles this naturally — the node is collected once unreachable.
        return oldTop.data;
    }

    public int size() {
        return size.get();
    }
}

Read-Write Lock with Writer Priority (Java) import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class WriterPriorityRWLock {
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition canRead = lock.newCondition();
    private final Condition canWrite = lock.newCondition();

    private int activeReaders = 0;
    private int activeWriters = 0;
    private int waitingWriters = 0;

    public void readLock() throws InterruptedException {
        lock.lock();
        try {
            // Wait if there's an active writer OR waiting writers (writer priority)
            while (activeWriters > 0 || waitingWriters > 0) {
                canRead.await();
            }
            activeReaders++;
        } finally {
            lock.unlock();
        }
    }

    public void readUnlock() {
        lock.lock();
        try {
            activeReaders--;
            if (activeReaders == 0 && waitingWriters > 0) {
                canWrite.signal();  // Wake one waiting writer
            }
        } finally {
            lock.unlock();
        }
    }

    public void writeLock() throws InterruptedException {
        lock.lock();
        try {
            waitingWriters++;
            while (activeReaders > 0 || activeWriters > 0) {
                canWrite.await();
            }
            waitingWriters--;
            activeWriters++;
        } finally {
            lock.unlock();
        }
    }

    public void writeUnlock() {
        lock.lock();
        try {
            activeWriters--;
            if (waitingWriters > 0) {
                canWrite.signal();  // Prefer writers
            } else {
                canRead.signalAll();  // Wake all waiting readers
            }
        } finally {
            lock.unlock();
        }
    }
}

Deadlock Detection with Wait-For Graph (Java) import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class DeadlockDetector {
    /**Detects deadlocks using wait-for graph cycle detection.*/

    enum LockState { FREE, HELD }

    static class LockInfo {
        final String name;
        LockState state = LockState.FREE;
        Long holder = null; // Thread ID
        final Set<Long> waiters = new HashSet<>();

        LockInfo(String name) { this.name = name; }
    }

    private final Map<String, LockInfo> locks = new ConcurrentHashMap<>();
    private final Map<Long, Set<String>> threadHolds = new ConcurrentHashMap<>();
    private final ReentrantLock monitorLock = new ReentrantLock();

    public void registerLock(String name) {
        locks.put(name, new LockInfo(name));
    }

    /** Attempt to acquire lock. Returns false if deadlock detected. */
    public boolean acquire(long threadId, String lockName) {
        monitorLock.lock();
        try {
            LockInfo lock = locks.get(lockName);

            if (lock.state == LockState.FREE) {
                lock.state = LockState.HELD;
                lock.holder = threadId;
                threadHolds.computeIfAbsent(threadId, k -> new HashSet<>()).add(lockName);
                return true;
            }

            // Lock is held by another thread - check for deadlock
            lock.waiters.add(threadId);

            List<Long> cycle = detectCycle(threadId);
            if (cycle != null) {
                lock.waiters.remove(threadId);
                System.out.println("DEADLOCK DETECTED! Cycle: " + cycle);
                return false;
            }

            return true; // Safe to wait (no deadlock)
        } finally {
            monitorLock.unlock();
        }
    }

    public void release(long threadId, String lockName) {
        monitorLock.lock();
        try {
            LockInfo lock = locks.get(lockName);
            lock.state = LockState.FREE;
            lock.holder = null;
            Set<String> held = threadHolds.get(threadId);
            if (held != null) held.remove(lockName);
        } finally {
            monitorLock.unlock();
        }
    }

    /** DFS on wait-for graph to find cycles. */
    private List<Long> detectCycle(long startThread) {
        // Build wait-for graph: thread A waits-for thread B
        // if A is waiting for a lock held by B
        Map<Long, Set<Long>> waitFor = new HashMap<>();

        for (LockInfo lock : locks.values()) {
            if (lock.holder != null) {
                for (long waiter : lock.waiters) {
                    waitFor.computeIfAbsent(waiter, k -> new HashSet<>()).add(lock.holder);
                }
            }
        }

        // DFS from startThread looking for cycle back to start
        Set<Long> visited = new HashSet<>();
        List<Long> path = new ArrayList<>();
        path.add(startThread);

        if (dfs(startThread, startThread, waitFor, visited, path)) {
            return path;
        }
        return null;
    }

    private boolean dfs(long node, long startThread, Map<Long, Set<Long>> waitFor,
                        Set<Long> visited, List<Long> path) {
        Set<Long> neighbors = waitFor.getOrDefault(node, Collections.emptySet());
        for (long neighbor : neighbors) {
            if (visited.contains(neighbor)) {
                if (neighbor == startThread) return true; // Cycle found
                continue;
            }
            visited.add(neighbor);
            path.add(neighbor);
            if (dfs(neighbor, startThread, waitFor, visited, path)) return true;
            path.remove(path.size() - 1);
        }
        return false;
    }

    // Usage example
    public static void main(String[] args) {
        DeadlockDetector detector = new DeadlockDetector();
        detector.registerLock("mutex_A");
        detector.registerLock("mutex_B");

        // Thread 1 holds A, wants B
        detector.acquire(1, "mutex_A");
        // Thread 2 holds B, wants A
        detector.acquire(2, "mutex_B");

        // This would detect deadlock:
        // detector.acquire(1, "mutex_B");  // Thread 1 waits for B (held by 2)
        // detector.acquire(2, "mutex_A");  // Thread 2 waits for A (held by 1) -> CYCLE
    }
}

Semaphore-Based Connection Pool (Java) import java.util.concurrent.Semaphore;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class ConnectionPool<T> {
    private final Semaphore available;
    private final ConcurrentLinkedQueue<T> pool;
    private final ConnectionFactory<T> factory;
    private final AtomicInteger totalCreated;
    private final int maxSize;
    private final long acquireTimeoutMs;

    @FunctionalInterface
    public interface ConnectionFactory<T> {
        T create() throws Exception;
    }

    public ConnectionPool(int maxSize, long acquireTimeoutMs, ConnectionFactory<T> factory) {
        this.maxSize = maxSize;
        this.acquireTimeoutMs = acquireTimeoutMs;
        this.factory = factory;
        this.available = new Semaphore(maxSize, true);  // Fair ordering
        this.pool = new ConcurrentLinkedQueue<>();
        this.totalCreated = new AtomicInteger(0);
    }

    public T acquire() throws Exception {
        // Semaphore limits concurrent checkouts to maxSize
        if (!available.tryAcquire(acquireTimeoutMs, TimeUnit.MILLISECONDS)) {
            throw new RuntimeException("Connection pool exhausted (timeout: " 
                + acquireTimeoutMs + "ms, pool size: " + maxSize + ")");
        }

        // Try to reuse existing connection
        T conn = pool.poll();
        if (conn != null) {
            return conn;
        }

        // Create new connection (lazy initialization)
        totalCreated.incrementAndGet();
        return factory.create();
    }

    public void release(T connection) {
        if (connection == null) return;
        pool.offer(connection);
        available.release();  // Increment semaphore, unblock one waiter
    }

    public int getAvailableCount() {
        return available.availablePermits();
    }

    public int getTotalCreated() {
        return totalCreated.get();
    }
}

File System Operations and Metadata Inspection (Java) import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;

public class FileSystemOps {

    // Demonstrate atomic file write using rename
    static boolean atomicWrite(Path path, byte[] data) throws IOException {
        Path tmpPath = path.resolveSibling(path.getFileName() + ".tmp." + ProcessHandle.current().pid());

        try {
            // Write to temporary file
            Files.write(tmpPath, data, StandardOpenOption.CREATE,
                    StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);

            // Force data to disk (not just OS buffers)
            try (FileOutputStream fos = new FileOutputStream(tmpPath.toFile())) {
                fos.getFD().sync();
            }

            // Atomic rename replaces old file
            Files.move(tmpPath, path, StandardCopyOption.ATOMIC_MOVE,
                    StandardCopyOption.REPLACE_EXISTING);

            return true;
        } catch (IOException e) {
            Files.deleteIfExists(tmpPath);
            return false;
        }
    }

    // Inspect file metadata (similar to inode info)
    static void printFileInfo(Path path) throws IOException {
        BasicFileAttributes attrs = Files.readAttributes(path, BasicFileAttributes.class);
        PosixFileAttributes posixAttrs = null;
        try {
            posixAttrs = Files.readAttributes(path, PosixFileAttributes.class);
        } catch (UnsupportedOperationException ignored) {}

        System.out.println("File: " + path);
        System.out.println("  Size: " + attrs.size() + " bytes");
        System.out.println("  Is regular file: " + attrs.isRegularFile());
        System.out.println("  Is directory: " + attrs.isDirectory());
        System.out.println("  Is symbolic link: " + attrs.isSymbolicLink());

        if (posixAttrs != null) {
            System.out.println("  Owner: " + posixAttrs.owner().getName());
            System.out.println("  Group: " + posixAttrs.group().getName());
            System.out.println("  Permissions: " + PosixFilePermissions.toString(posixAttrs.permissions()));
        }

        DateTimeFormatter fmt = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")
                .withZone(ZoneId.systemDefault());
        System.out.println("  Modified: " + fmt.format(attrs.lastModifiedTime().toInstant()));
        System.out.println("  Created: " + fmt.format(attrs.creationTime().toInstant()));
    }

    // Check filesystem capacity
    static void printFsStats(Path path) throws IOException {
        FileStore store = Files.getFileStore(path);

        long total = store.getTotalSpace();
        long free = store.getUnallocatedSpace();
        long usable = store.getUsableSpace(); // Available to non-root

        System.out.println("Filesystem stats for " + path + ":");
