  async loadSecrets(): Promise<void> {
    // Read from mounted volume (CSI driver) or environment
    const secretsPath = process.env.SECRETS_PATH || '/app/secrets';

    try {
      const files = await fs.readdir(secretsPath);
      for (const file of files) {
