Migration Testing import { GenericContainer, StartedTestContainer } from 'testcontainers';
import { Pool } from 'pg';
import { Umzug, SequelizeStorage } from 'umzug';

describe('Database Migration Tests', () => {
  let container: StartedTestContainer;
  let pool: Pool;

  beforeAll(async () => {
    container = await new GenericContainer('postgres:16-alpine')
      .withEnvironment({ POSTGRES_DB: 'migration_test', POSTGRES_USER: 'test', POSTGRES_PASSWORD: 'test' })
      .withExposedPorts(5432)
      .start();

    pool = new Pool({
      host: container.getHost(),
      port: container.getMappedPort(5432),
      database: 'migration_test',
      user: 'test',
      password: 'test'
    });
  });

  afterAll(async () => {
    await pool.end();
    await container.stop();
  });

  it('all migrations apply cleanly to empty database', async () => {
    const umzug = createMigrator(pool);
    const pending = await umzug.pending();

    expect(pending.length).toBeGreaterThan(0);

    // Apply all migrations
    const executed = await umzug.up();
    expect(executed).toHaveLength(pending.length);

    // Verify final schema
    const tables = await pool.query(
      `SELECT table_name FROM information_schema.tables WHERE table_schema = 'public'`
    );
    expect(tables.rows.map(r => r.table_name)).toContain('orders');
    expect(tables.rows.map(r => r.table_name)).toContain('order_items');
    expect(tables.rows.map(r => r.table_name)).toContain('customers');
  });

  it('migrations are reversible (up then down)', async () => {
    const umzug = createMigrator(pool);

    // Apply all
    await umzug.up();

    // Rollback all
    await umzug.down({ to: 0 });

    // Verify clean state
    const tables = await pool.query(
      `SELECT table_name FROM information_schema.tables
       WHERE table_schema = 'public' AND table_name != 'migrations'`
    );
    expect(tables.rows).toHaveLength(0);
  });

  it('migration handles existing data correctly', async () => {
    const umzug = createMigrator(pool);

    // Apply migrations up to the one before our new migration
    await umzug.up({ to: '20240301_add_orders_table' });

    // Insert data in the old schema
    await pool.query(`
      INSERT INTO orders (id, customer_id, total, created_at)
      VALUES ('ord-1', 'cust-1', 99.99, NOW())
    `);

    // Apply the new migration that adds a column with default
    await umzug.up({ to: '20240315_add_order_status' });

    // Verify existing data has the default value
    const result = await pool.query(`SELECT status FROM orders WHERE id = 'ord-1'`);
    expect(result.rows[0].status).toBe('pending');  // Default value applied
  });
});

MongoDB Integration Testing with Testcontainers import { MongoDBContainer, StartedMongoDBContainer } from '@testcontainers/mongodb';
import { MongoClient, Db, Collection } from 'mongodb';

describe('Product Catalog Repository (MongoDB)', () => {
  let container: StartedMongoDBContainer;
  let client: MongoClient;
  let db: Db;
  let collection: Collection;

  beforeAll(async () => {
    container = await new MongoDBContainer('mongo:7').start();
    client = new MongoClient(container.getConnectionString(), { directConnection: true });
    await client.connect();
    db = client.db('test_catalog');
    collection = db.collection('products');

    // Create indexes matching production
    await collection.createIndex({ category: 1, price: 1 });
    await collection.createIndex({ name: 'text', description: 'text' });
    await collection.createIndex({ sku: 1 }, { unique: true });
  }, 60000);

  afterAll(async () => {
    await client.close();
    await container.stop();
  });

  beforeEach(async () => {
    await collection.deleteMany({});
  });

  it('text search returns relevant products ranked by score', async () => {
    await collection.insertMany([
      { name: 'Wireless Bluetooth Headphones', category: 'audio', price: 79.99, sku: 'AUD-001' },
      { name: 'Wired Studio Headphones', category: 'audio', price: 149.99, sku: 'AUD-002' },
      { name: 'Bluetooth Speaker', category: 'audio', price: 49.99, sku: 'AUD-003' },
      { name: 'USB Keyboard', category: 'peripherals', price: 39.99, sku: 'PER-001' }
    ]);

    const results = await collection
      .find(
        { $text: { $search: 'bluetooth headphones' } },
        { score: { $meta: 'textScore' } }
      )
      .sort({ score: { $meta: 'textScore' } })
      .toArray();

    expect(results).toHaveLength(3);  // Matches bluetooth OR headphones
    expect(results[0].name).toContain('Bluetooth Headphones');  // Best match first
  });

  it('aggregation pipeline computes category statistics', async () => {
    await collection.insertMany([
      { name: 'Product A', category: 'electronics', price: 299.99, sku: 'E-1', soldCount: 150 },
      { name: 'Product B', category: 'electronics', price: 199.99, sku: 'E-2', soldCount: 300 },
      { name: 'Product C', category: 'clothing', price: 49.99, sku: 'C-1', soldCount: 500 }
    ]);

    const stats = await collection.aggregate([
      { $group: {
        _id: '$category',
        avgPrice: { $avg: '$price' },
        totalRevenue: { $sum: { $multiply: ['$price', '$soldCount'] } },
        productCount: { $sum: 1 }
      }},
      { $sort: { totalRevenue: -1 } }
    ]).toArray();

    expect(stats[0]._id).toBe('electronics');
    expect(stats[0].productCount).toBe(2);
    expect(stats[0].avgPrice).toBeCloseTo(249.99, 2);
  });
});

Database Integration Testing with Test Containers Test containers provide ephemeral, isolated database instances that start fresh for each test suite. This eliminates shared state problems and ensures tests run identically on developer machines and CI. import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import { GenericContainer, StartedTestContainer } from 'testcontainers';
import { Pool } from 'pg';
import { UserRepository } from './user-repository';
import { runMigrations } from './migrations';

describe('UserRepository Integration', () => {
  let container: StartedTestContainer;
  let pool: Pool;
  let repository: UserRepository;

  beforeAll(async () => {
    // Start a PostgreSQL container
    container = await new GenericContainer('postgres:15-alpine')
      .withEnvironment({
        POSTGRES_DB: 'testdb',
        POSTGRES_USER: 'testuser',
        POSTGRES_PASSWORD: 'testpass',
      })
      .withExposedPorts(5432)
      .start();

    const connectionString = `postgresql://testuser:testpass@${container.getHost()}:${container.getMappedPort(5432)}/testdb`;

    pool = new Pool({ connectionString });
    await runMigrations(pool); // Apply schema
    repository = new UserRepository(pool);
  }, 60000); // Container startup timeout

  afterAll(async () => {
    await pool.end();
    await container.stop();
  });

  beforeEach(async () => {
    // Clean slate for each test — truncate with cascade
    await pool.query('TRUNCATE TABLE users, orders, sessions CASCADE');
  });

  it('should persist and retrieve a user with all fields', async () => {
    const user = {
      email: 'test@example.com',
      name: 'Test User',
      role: 'admin',
      metadata: { department: 'engineering', level: 'senior' },
    };

    const created = await repository.create(user);
    const retrieved = await repository.findById(created.id);

    expect(retrieved).not.toBeNull();
    expect(retrieved!.email).toBe('test@example.com');
    expect(retrieved!.metadata).toEqual({ department: 'engineering', level: 'senior' });
    expect(retrieved!.createdAt).toBeInstanceOf(Date);
  });

  it('should enforce unique email constraint', async () => {
    await repository.create({ email: 'dup@example.com', name: 'First', role: 'user' });

    await expect(
      repository.create({ email: 'dup@example.com', name: 'Second', role: 'user' })
    ).rejects.toThrow(/unique.*email/i);
  });

  it('should support pagination with correct ordering', async () => {
    // Seed 25 users
    for (let i = 0; i < 25; i++) {
      await repository.create({
        email: `user${i.toString().padStart(2, '0')}@example.com`,
        name: `User ${i}`,
        role: 'user',
      });
    }

    const page1 = await repository.findAll({ page: 1, pageSize: 10, orderBy: 'email' });
    const page2 = await repository.findAll({ page: 2, pageSize: 10, orderBy: 'email' });
    const page3 = await repository.findAll({ page: 3, pageSize: 10, orderBy: 'email' });

    expect(page1.items).toHaveLength(10);
    expect(page2.items).toHaveLength(10);
    expect(page3.items).toHaveLength(5);
    expect(page1.totalCount).toBe(25);
    // Verify ordering
    expect(page1.items[0].email).toBe('user00@example.com');
    expect(page1.items[9].email).toBe('user09@example.com');
  });

  it('should handle JSONB queries correctly', async () => {
    await repository.create({
      email: 'eng@example.com',
      name: 'Engineer',
      role: 'user',
      metadata: { department: 'engineering', skills: ['typescript', 'rust'] },
    });
    await repository.create({
      email: 'sales@example.com',
      name: 'Sales Rep',
      role: 'user',
      metadata: { department: 'sales', skills: ['negotiation'] },
    });

    const engineers = await repository.findByMetadata({ department: 'engineering' });

    expect(engineers).toHaveLength(1);
    expect(engineers[0].email).toBe('eng@example.com');
  });
});

API Integration Testing with Supertest API integration tests verify the full HTTP request/response cycle including routing, middleware, serialization, validation, and error handling. import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.web.servlet.MockMvc;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.hamcrest.Matchers.*;

@SpringBootTest
@AutoConfigureMockMvc
@Testcontainers
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class OrderApiIntegrationTest {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:15-alpine")
        .withDatabaseName("orders_test")
        .withUsername("test")
        .withPassword("test");

    @DynamicPropertySource
    static void configureProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", postgres::getJdbcUrl);
        registry.add("spring.datasource.username", postgres::getUsername);
        registry.add("spring.datasource.password", postgres::getPassword);
    }

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private OrderRepository orderRepository;

    @BeforeEach
    void cleanDatabase() {
        orderRepository.deleteAll();
    }

    @Test
    @DisplayName("POST /api/orders - should create order and return 201")
    void createOrder() throws Exception {
        String orderJson = """
            {
                "customerId": "cust-123",
                "items": [
                    {"productId": "prod-1", "quantity": 2, "unitPrice": 29.99},
                    {"productId": "prod-2", "quantity": 1, "unitPrice": 49.99}
                ],
                "shippingAddress": {
                    "street": "123 Main St",
                    "city": "Portland",
                    "state": "OR",
                    "zip": "97201"
                }
            }
            """;

        mockMvc.perform(post("/api/orders")
                .contentType(MediaType.APPLICATION_JSON)
                .content(orderJson))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.id").exists())
            .andExpect(jsonPath("$.status").value("PENDING"))
            .andExpect(jsonPath("$.totalAmount").value(109.97))
            .andExpect(jsonPath("$.items", hasSize(2)))
            .andExpect(jsonPath("$.createdAt").exists());
    }

    @Test
    @DisplayName("POST /api/orders - should return 400 for invalid input")
    void createOrderValidationError() throws Exception {
        String invalidJson = """
            {
                "customerId": "",
                "items": []
            }
            """;

        mockMvc.perform(post("/api/orders")
                .contentType(MediaType.APPLICATION_JSON)
                .content(invalidJson))
            .andExpect(status().isBadRequest())
            .andExpect(jsonPath("$.errors", hasSize(greaterThanOrEqualTo(2))))
            .andExpect(jsonPath("$.errors[*].field", hasItems("customerId", "items")));
    }

    @Test
    @DisplayName("GET /api/orders/{id} - should return 404 for non-existent order")
    void getOrderNotFound() throws Exception {
        mockMvc.perform(get("/api/orders/non-existent-id"))
            .andExpect(status().isNotFound())
            .andExpect(jsonPath("$.message").value("Order not found"));
    }

    @Test
    @DisplayName("PATCH /api/orders/{id}/cancel - should transition order to CANCELLED")
    void cancelOrder() throws Exception {
        // Create an order first
        Order order = orderRepository.save(Order.builder()
            .customerId("cust-123")
            .status(OrderStatus.PENDING)
            .totalAmount(new BigDecimal("59.99"))
            .build());

        mockMvc.perform(patch("/api/orders/" + order.getId() + "/cancel")
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"reason\": \"changed_mind\"}"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.status").value("CANCELLED"))
            .andExpect(jsonPath("$.cancellationReason").value("changed_mind"));
    }
}

Contract Testing with Pact Contract tests verify that API producers and consumers agree on the interface without requiring both services to be running simultaneously. This enables independent deployment of microservices. import { PactV3, MatchersV3 } from '@pact-foundation/pact';
import { resolve } from 'path';
import { UserApiClient } from './user-api-client';

const { like, eachLike, string, integer, iso8601DateTimeWithMillis } = MatchersV3;

const provider = new PactV3({
  consumer: 'OrderService',
  provider: 'UserService',
  dir: resolve(process.cwd(), 'pacts'),
});

describe('UserService Contract', () => {
  it('should return user details for a valid user ID', async () => {
    // Define the expected interaction
    provider
      .given('a user with ID user-123 exists')
      .uponReceiving('a request for user details')
      .withRequest({
        method: 'GET',
        path: '/api/users/user-123',
        headers: { Accept: 'application/json' },
      })
      .willRespondWith({
        status: 200,
        headers: { 'Content-Type': 'application/json' },
        body: {
          id: string('user-123'),
          email: string('john@example.com'),
          name: string('John Doe'),
          tier: string('premium'),
          createdAt: iso8601DateTimeWithMillis('2024-01-15T10:30:00.000Z'),
          orderCount: integer(42),
        },
      });

    await provider.executeTest(async (mockServer) => {
      const client = new UserApiClient(mockServer.url);
      const user = await client.getUserById('user-123');

      expect(user.id).toBe('user-123');
      expect(user.email).toBe('john@example.com');
      expect(user.tier).toBe('premium');
    });
  });

  it('should return 404 for non-existent user', async () => {
    provider
      .given('no user with ID user-999 exists')
      .uponReceiving('a request for a non-existent user')
      .withRequest({
        method: 'GET',
        path: '/api/users/user-999',
        headers: { Accept: 'application/json' },
      })
      .willRespondWith({
        status: 404,
        body: {
          error: string('USER_NOT_FOUND'),
          message: string('User with ID user-999 does not exist'),
        },
      });

    await provider.executeTest(async (mockServer) => {
      const client = new UserApiClient(mockServer.url);
      await expect(client.getUserById('user-999')).rejects.toThrow('User not found');
    });
  });
});

Roundtrip Properties with fast-check The roundtrip property is the most common and powerful pattern: if you can encode and decode, then decoding an encoded value must return the original. This single property replaces dozens of example-based tests. import fc from 'fast-check';
import { describe, it, expect } from 'vitest';
import { serialize, deserialize } from './json-codec';
import { compress, decompress } from './compression';
import { encrypt, decrypt } from './crypto';

describe('Serialization Properties', () => {
  it('should roundtrip any valid user object', () => {
    const userArbitrary = fc.record({
      id: fc.uuid(),
      name: fc.string({ minLength: 1, maxLength: 100 }),
      email: fc.emailAddress(),
      age: fc.integer({ min: 0, max: 150 }),
      roles: fc.array(fc.constantFrom('admin', 'user', 'moderator'), { minLength: 1, maxLength: 5 }),
      metadata: fc.dictionary(
        fc.string({ minLength: 1, maxLength: 20 }),
        fc.oneof(fc.string(), fc.integer(), fc.boolean())
      ),
      createdAt: fc.date({ min: new Date('2000-01-01'), max: new Date('2030-12-31') }),
    });

    fc.assert(
      fc.property(userArbitrary, (user) => {
        const serialized = serialize(user);
        const deserialized = deserialize(serialized);

        expect(deserialized).toEqual(user);
      }),
      { numRuns: 500 }
    );
  });

  it('should roundtrip compression for any byte sequence', () => {
    fc.assert(
      fc.property(
        fc.uint8Array({ minLength: 0, maxLength: 10000 }),
        (data) => {
          const compressed = compress(data);
          const decompressed = decompress(compressed);

          expect(decompressed).toEqual(data);
          // Bonus property: compressed size should not exceed original + overhead
          expect(compressed.length).toBeLessThanOrEqual(data.length + 64);
        }
      ),
      { numRuns: 200 }
    );
  });

  it('should roundtrip encryption for any plaintext', () => {
    const key = 'test-encryption-key-32-bytes!!!';

    fc.assert(
      fc.property(fc.string({ minLength: 0, maxLength: 5000 }), (plaintext) => {
        const encrypted = encrypt(plaintext, key);
        const decrypted = decrypt(encrypted, key);

        expect(decrypted).toBe(plaintext);
        // Encrypted output should differ from plaintext (unless empty)
        if (plaintext.length > 0) {
          expect(encrypted).not.toBe(plaintext);
        }
      }),
      { numRuns: 300 }
    );
  });
});

Custom Generators and Shrinking Building domain-specific generators lets you test with realistic data that satisfies your business constraints. Good generators produce values that exercise edge cases naturally. import fc from 'fast-check';
import { describe, it, expect } from 'vitest';
import { PriceCalculator } from './price-calculator';
import { Money, Currency } from './money';

// Custom generator for monetary amounts
const moneyArbitrary = (currency: Currency = 'USD'): fc.Arbitrary<Money> =>
  fc.record({
    amount: fc.integer({ min: 0, max: 999999999 }), // Cents to avoid floating point
    currency: fc.constant(currency),
  });

// Custom generator for a shopping cart
const cartItemArbitrary = fc.record({
  productId: fc.uuid(),
  name: fc.string({ minLength: 1, maxLength: 50 }),
  unitPrice: moneyArbitrary(),
  quantity: fc.integer({ min: 1, max: 100 }),
  taxRate: fc.double({ min: 0, max: 0.25, noNaN: true }),
});

const cartArbitrary = fc.record({
  items: fc.array(cartItemArbitrary, { minLength: 1, maxLength: 20 }),
  discountPercent: fc.double({ min: 0, max: 0.5, noNaN: true }),
  shippingCents: fc.integer({ min: 0, max: 5000 }),
});

describe('PriceCalculator Properties', () => {
  const calculator = new PriceCalculator();

  it('total should never be negative', () => {
    fc.assert(
      fc.property(cartArbitrary, (cart) => {
        const total = calculator.calculateTotal(cart);
        expect(total.amount).toBeGreaterThanOrEqual(0);
      })
    );
  });

  it('total should equal sum of line items minus discount plus shipping plus tax', () => {
    fc.assert(
      fc.property(cartArbitrary, (cart) => {
        const total = calculator.calculateTotal(cart);
        const subtotal = cart.items.reduce(
          (sum, item) => sum + item.unitPrice.amount * item.quantity,
          0
        );
        const discount = Math.floor(subtotal * cart.discountPercent);
        const afterDiscount = subtotal - discount;
        const tax = cart.items.reduce(
          (sum, item) =>
            sum + Math.floor(item.unitPrice.amount * item.quantity * item.taxRate),
          0
        );
        const expected = afterDiscount + tax + cart.shippingCents;

        expect(total.amount).toBe(expected);
      })
    );
  });

  it('adding an item should never decrease the total', () => {
    fc.assert(
      fc.property(cartArbitrary, cartItemArbitrary, (cart, newItem) => {
        const totalBefore = calculator.calculateTotal(cart);
        const cartWithItem = { ...cart, items: [...cart.items, newItem] };
        const totalAfter = calculator.calculateTotal(cartWithItem);

        expect(totalAfter.amount).toBeGreaterThanOrEqual(totalBefore.amount);
      })
    );
  });

  it('zero discount should equal no discount applied', () => {
    fc.assert(
      fc.property(cartArbitrary, (cart) => {
        const withDiscount = calculator.calculateTotal({ ...cart, discountPercent: 0 });
        const withoutDiscount = calculator.calculateTotal({ ...cart, discountPercent: 0 });

        expect(withDiscount.amount).toBe(withoutDiscount.amount);
      })
    );
  });
});

Stateful Testing with Model-Based Approach Stateful property-based testing generates random sequences of operations and verifies that the system under test behaves identically to a simplified model. This catches bugs that only manifest after specific operation sequences. import fc from 'fast-check';
import { describe, it } from 'vitest';
import { BoundedQueue } from './bounded-queue';

// Model: a simple array-based queue for comparison
class QueueModel {
  private items: number[] = [];
  constructor(private capacity: number) {}

  enqueue(item: number): boolean {
    if (this.items.length >= this.capacity) return false;
    this.items.push(item);
    return true;
  }

  dequeue(): number | undefined {
    return this.items.shift();
  }

  peek(): number | undefined {
    return this.items[0];
  }

  get size(): number {
    return this.items.length;
  }

  get isEmpty(): boolean {
    return this.items.length === 0;
  }

  get isFull(): boolean {
    return this.items.length >= this.capacity;
  }
}

// Define commands that operate on both model and real implementation
class EnqueueCommand implements fc.Command<QueueModel, BoundedQueue<number>> {
  constructor(readonly value: number) {}

  check(model: Readonly<QueueModel>): boolean {
    return true; // Always applicable
  }

  run(model: QueueModel, real: BoundedQueue<number>): void {
    const modelResult = model.enqueue(this.value);
    const realResult = real.enqueue(this.value);

    // Both should agree on whether enqueue succeeded
    expect(realResult).toBe(modelResult);
    // Size should match
    expect(real.size).toBe(model.size);
  }

  toString(): string {
    return `enqueue(${this.value})`;
  }
}

class DequeueCommand implements fc.Command<QueueModel, BoundedQueue<number>> {
  check(model: Readonly<QueueModel>): boolean {
    return true; // Test behavior on both empty and non-empty
  }

  run(model: QueueModel, real: BoundedQueue<number>): void {
    const modelResult = model.dequeue();
    const realResult = real.dequeue();

    expect(realResult).toBe(modelResult);
    expect(real.size).toBe(model.size);
  }

  toString(): string {
    return 'dequeue()';
  }
}

class PeekCommand implements fc.Command<QueueModel, BoundedQueue<number>> {
  check(): boolean {
    return true;
  }

  run(model: QueueModel, real: BoundedQueue<number>): void {
    expect(real.peek()).toBe(model.peek());
    // Peek should not modify size
    expect(real.size).toBe(model.size);
  }

  toString(): string {
    return 'peek()';
  }
}

class SizeCommand implements fc.Command<QueueModel, BoundedQueue<number>> {
  check(): boolean {
    return true;
  }

  run(model: QueueModel, real: BoundedQueue<number>): void {
    expect(real.size).toBe(model.size);
    expect(real.isEmpty).toBe(model.isEmpty);
    expect(real.isFull).toBe(model.isFull);
  }

  toString(): string {
    return 'checkSize()';
  }
}

describe('BoundedQueue Stateful Properties', () => {
  it('should behave identically to the array-based model under any operation sequence', () => {
    const capacity = 5;

    const allCommands = [
      fc.integer({ min: -100, max: 100 }).map((v) => new EnqueueCommand(v)),
      fc.constant(new DequeueCommand()),
      fc.constant(new PeekCommand()),
      fc.constant(new SizeCommand()),
    ];

    fc.assert(
      fc.property(fc.commands(allCommands, { maxCommands: 100 }), (cmds) => {
        const model = new QueueModel(capacity);
        const real = new BoundedQueue<number>(capacity);

        fc.modelRun(() => ({ model, real }), cmds);
      }),
      { numRuns: 1000 }
    );
  });
});

Invariant Properties for Data Structures import fc from 'fast-check';
import { describe, it, expect } from 'vitest';
import { SortedSet } from './sorted-set';

describe('SortedSet Invariants', () => {
  it('should always maintain sorted order after any sequence of insertions', () => {
    fc.assert(
      fc.property(
        fc.array(fc.integer({ min: -10000, max: 10000 }), { maxLength: 200 }),
        (values) => {
          const set = new SortedSet<number>();
          for (const v of values) {
            set.insert(v);
          }

          const elements = set.toArray();
          for (let i = 1; i < elements.length; i++) {
            expect(elements[i]).toBeGreaterThan(elements[i - 1]);
          }
        }
      )
    );
  });

  it('should never contain duplicates', () => {
    fc.assert(
      fc.property(
        fc.array(fc.integer({ min: 0, max: 50 }), { maxLength: 100 }),
        (values) => {
          const set = new SortedSet<number>();
          for (const v of values) {
            set.insert(v);
          }

          const elements = set.toArray();
          const uniqueElements = new Set(elements);
          expect(elements.length).toBe(uniqueElements.size);
        }
      )
    );
  });

  it('size should equal number of unique values inserted', () => {
    fc.assert(
      fc.property(
        fc.array(fc.integer({ min: 0, max: 100 }), { maxLength: 200 }),
        (values) => {
          const set = new SortedSet<number>();
          for (const v of values) {
            set.insert(v);
          }

          const expectedSize = new Set(values).size;
          expect(set.size).toBe(expectedSize);
        }
      )
    );
  });

  it('contains should return true for all inserted values', () => {
    fc.assert(
      fc.property(
        fc.array(fc.integer(), { minLength: 1, maxLength: 100 }),
        (values) => {
          const set = new SortedSet<number>();
          for (const v of values) {
            set.insert(v);
          }

          for (const v of values) {
            expect(set.contains(v)).toBe(true);
          }
        }
      )
    );
  });

  it('delete should remove element and maintain sorted order', () => {
    fc.assert(
      fc.property(
        fc.array(fc.integer({ min: 0, max: 50 }), { minLength: 2, maxLength: 50 }),
        fc.nat(),
        (values, indexSeed) => {
          const set = new SortedSet<number>();
          for (const v of values) {
            set.insert(v);
          }

          // Delete a random element that exists
          const elements = set.toArray();
          const toDelete = elements[indexSeed % elements.length];
          set.delete(toDelete);

          expect(set.contains(toDelete)).toBe(false);
          // Still sorted
          const remaining = set.toArray();
          for (let i = 1; i < remaining.length; i++) {
            expect(remaining[i]).toBeGreaterThan(remaining[i - 1]);
          }
        }
      )
    );
  });
});

Seed Management for Reproducibility Every property-based test framework records the random seed that produced a failure. Store this seed in your test configuration or CI logs so you can reproduce failures deterministically. In fast-check, use the seed option to replay a specific run. In CI, log the seed on every run — when a test fails intermittently, you can reproduce it locally with the exact seed from the failing build. // Reproduce a specific failure
fc.assert(
  fc.property(fc.integer(), (n) => {
    // ... property
  }),
  { seed: 1234567890, path: '4:2:1' } // Exact reproduction
);

Flaky Test Detection and Quarantine System Flaky tests erode trust in the test suite. A quarantine system automatically detects, isolates, and tracks flaky tests without blocking deployments. import { describe, it, expect, beforeAll } from 'vitest';
import { FlakyTestTracker } from './flaky-test-tracker';

// Flaky test detection middleware
class TestStabilityMonitor {
  private results: Map<string, { passes: number; failures: number; lastFailure?: string }> = new Map();
  private readonly flakyThreshold = 0.05; // 5% failure rate = flaky
  private readonly windowSize = 100; // Last 100 runs

  recordResult(testId: string, passed: boolean, errorMessage?: string): void {
    const existing = this.results.get(testId) || { passes: 0, failures: 0 };
    if (passed) {
      existing.passes++;
    } else {
      existing.failures++;
      existing.lastFailure = errorMessage;
    }
    this.results.set(testId, existing);
  }

  isFlaky(testId: string): boolean {
    const result = this.results.get(testId);
    if (!result) return false;
    const total = result.passes + result.failures;
    if (total < 10) return false; // Not enough data
    const failureRate = result.failures / total;
    return failureRate > 0 && failureRate < this.flakyThreshold;
  }

  getQuarantinedTests(): string[] {
    return Array.from(this.results.entries())
      .filter(([id]) => this.isFlaky(id))
      .map(([id]) => id);
  }

  getFlakyReport(): FlakyReport {
    const flaky = this.getQuarantinedTests();
    return {
      totalTracked: this.results.size,
      flakyCount: flaky.length,
      flakyTests: flaky.map((id) => ({
        id,
        ...this.results.get(id)!,
        failureRate: this.results.get(id)!.failures /
          (this.results.get(id)!.passes + this.results.get(id)!.failures),
      })),
    };
  }
}

interface FlakyReport {
  totalTracked: number;
  flakyCount: number;
  flakyTests: Array<{
    id: string;
    passes: number;
    failures: number;
    failureRate: number;
    lastFailure?: string;
  }>;
}

// Vitest custom reporter for flaky detection
// In vitest.config.ts:
// reporters: ['default', './src/test-utils/flaky-reporter.ts']
export class FlakyReporter {
  private tracker = new TestStabilityMonitor();

  onTestResult(testPath: string, result: { passed: boolean; name: string; error?: string }): void {
    const testId = `${testPath}::${result.name}`;
    this.tracker.recordResult(testId, result.passed, result.error);
  }

  onRunComplete(): void {
    const report = this.tracker.getFlakyReport();
    if (report.flakyCount > 0) {
      console.warn(`\n⚠️  ${report.flakyCount} flaky tests detected:`);
      for (const test of report.flakyTests) {
        console.warn(`  - ${test.id} (${(test.failureRate * 100).toFixed(1)}% failure rate)`);
      }
    }
  }
}

