      expect(() => cart.applyDiscount(1.5)).toThrow('Discount must be between 0 and 1');
    });
  });
});

TDD Cycle: Red-Green-Refactor Test-Driven Development inverts the traditional workflow. You write the test first, watch it fail, write the minimal code to pass, then refactor. This cycle ensures every line of production code exists to satisfy a documented requirement. // Step 1: RED — Write the failing test
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.DisplayName;
import static org.assertj.core.api.Assertions.*;

class PasswordValidatorTest {

    @Test
    @DisplayName("should reject passwords shorter than 8 characters")
    void rejectShortPasswords() {
        PasswordValidator validator = new PasswordValidator();
        ValidationResult result = validator.validate("Ab1!xyz");

        assertThat(result.isValid()).isFalse();
        assertThat(result.getErrors()).contains("Password must be at least 8 characters");
    }

    @Test
    @DisplayName("should reject passwords without uppercase letter")
    void rejectWithoutUppercase() {
        PasswordValidator validator = new PasswordValidator();
        ValidationResult result = validator.validate("abcdefg1!");

        assertThat(result.isValid()).isFalse();
        assertThat(result.getErrors()).contains("Password must contain at least one uppercase letter");
    }

    @Test
    @DisplayName("should accept valid password meeting all criteria")
    void acceptValidPassword() {
        PasswordValidator validator = new PasswordValidator();
        ValidationResult result = validator.validate("SecureP@ss1");

        assertThat(result.isValid()).isTrue();
        assertThat(result.getErrors()).isEmpty();
    }

    @Test
    @DisplayName("should collect all validation errors at once")
    void collectAllErrors() {
        PasswordValidator validator = new PasswordValidator();
        ValidationResult result = validator.validate("ab");

        assertThat(result.isValid()).isFalse();
        assertThat(result.getErrors()).hasSize(3); // short, no uppercase, no special char
    }
}

// Step 2: GREEN — Minimal implementation to pass
class PasswordValidator {
    public ValidationResult validate(String password) {
        List<String> errors = new ArrayList<>();

        if (password.length() < 8) {
            errors.add("Password must be at least 8 characters");
        }
        if (!password.chars().anyMatch(Character::isUpperCase)) {
            errors.add("Password must contain at least one uppercase letter");
        }
        if (!password.matches(".*[!@#$%^&*()_+\\-=\\[\\]{};':\"\\\\|,.<>/?].*")) {
            errors.add("Password must contain at least one special character");
        }

        return new ValidationResult(errors.isEmpty(), errors);
    }
}

// Step 3: REFACTOR — Extract rules into composable validators
class PasswordValidator {
    private final List<ValidationRule> rules;

    public PasswordValidator() {
        this.rules = List.of(
            new MinLengthRule(8),
            new UppercaseRule(),
            new SpecialCharRule()
        );
    }

    public ValidationResult validate(String password) {
        List<String> errors = rules.stream()
            .map(rule -> rule.check(password))
            .filter(Optional::isPresent)
            .map(Optional::get)
            .toList();

        return new ValidationResult(errors.isEmpty(), errors);
    }
}

Mocking Dependencies with Test Doubles When a unit depends on external services, use test doubles to isolate the unit under test. The key is to mock at the boundary — the interface between your code and the external world. import { describe, it, expect, vi, beforeEach } from 'vitest';
import { OrderService } from './order-service';
import { PaymentGateway } from './payment-gateway';
import { InventoryService } from './inventory-service';
import { EmailService } from './email-service';

describe('OrderService', () => {
  let orderService: OrderService;
  let mockPayment: PaymentGateway;
  let mockInventory: InventoryService;
  let mockEmail: EmailService;

  beforeEach(() => {
    // Create mock implementations
    mockPayment = {
      charge: vi.fn().mockResolvedValue({ transactionId: 'txn-123', success: true }),
      refund: vi.fn().mockResolvedValue({ success: true }),
    };
    mockInventory = {
      reserve: vi.fn().mockResolvedValue(true),
      release: vi.fn().mockResolvedValue(undefined),
      checkStock: vi.fn().mockResolvedValue(10),
    };
    mockEmail = {
      sendConfirmation: vi.fn().mockResolvedValue(undefined),
      sendFailureNotice: vi.fn().mockResolvedValue(undefined),
    };

    orderService = new OrderService(mockPayment, mockInventory, mockEmail);
  });

  it('should process order successfully when stock is available', async () => {
    const order = { userId: 'user-1', productId: 'prod-1', quantity: 2, amount: 59.98 };

    const result = await orderService.placeOrder(order);

    expect(result.status).toBe('confirmed');
    expect(result.transactionId).toBe('txn-123');
    expect(mockInventory.reserve).toHaveBeenCalledWith('prod-1', 2);
    expect(mockPayment.charge).toHaveBeenCalledWith('user-1', 59.98);
    expect(mockEmail.sendConfirmation).toHaveBeenCalledWith('user-1', expect.objectContaining({
      orderId: expect.any(String),
    }));
  });

  it('should release inventory and skip payment when charge fails', async () => {
    mockPayment.charge = vi.fn().mockResolvedValue({ success: false, error: 'declined' });
    const order = { userId: 'user-1', productId: 'prod-1', quantity: 1, amount: 29.99 };

    const result = await orderService.placeOrder(order);

    expect(result.status).toBe('failed');
    expect(mockInventory.release).toHaveBeenCalledWith('prod-1', 1);
    expect(mockEmail.sendFailureNotice).toHaveBeenCalled();
  });

  it('should not charge payment when inventory reservation fails', async () => {
    mockInventory.reserve = vi.fn().mockResolvedValue(false);
    const order = { userId: 'user-1', productId: 'prod-1', quantity: 100, amount: 2999 };

    const result = await orderService.placeOrder(order);

    expect(result.status).toBe('out_of_stock');
    expect(mockPayment.charge).not.toHaveBeenCalled();
  });
});

Testing Asynchronous Code Async operations require careful handling to avoid false positives. Always await promises and test both success and failure paths. import { describe, it, expect, vi } from 'vitest';
import { RetryableHttpClient } from './retryable-http-client';

describe('RetryableHttpClient', () => {
  it('should retry on transient failures up to max attempts', async () => {
    const mockFetch = vi.fn()
      .mockRejectedValueOnce(new Error('ECONNRESET'))
      .mockRejectedValueOnce(new Error('ETIMEDOUT'))
      .mockResolvedValueOnce({ status: 200, data: { id: 1 } });

    const client = new RetryableHttpClient({
      maxRetries: 3,
      baseDelay: 10, // Short delay for tests
      fetchFn: mockFetch,
    });

    const result = await client.get('/api/users/1');

    expect(result.status).toBe(200);
    expect(mockFetch).toHaveBeenCalledTimes(3);
  });

  it('should throw after exhausting all retry attempts', async () => {
    const mockFetch = vi.fn().mockRejectedValue(new Error('ECONNREFUSED'));

    const client = new RetryableHttpClient({
      maxRetries: 3,
      baseDelay: 10,
      fetchFn: mockFetch,
    });

    await expect(client.get('/api/users/1')).rejects.toThrow('ECONNREFUSED');
    expect(mockFetch).toHaveBeenCalledTimes(3);
  });

  it('should not retry on non-transient errors (4xx)', async () => {
    const mockFetch = vi.fn().mockResolvedValue({ status: 404, data: null });

    const client = new RetryableHttpClient({
      maxRetries: 3,
      baseDelay: 10,
      fetchFn: mockFetch,
    });

    const result = await client.get('/api/users/999');

    expect(result.status).toBe(404);
    expect(mockFetch).toHaveBeenCalledTimes(1); // No retry for 4xx
  });
});

Use Test Fixtures and Builders Production test suites accumulate complex object construction. Instead of repeating 20-field object literals in every test, use builder patterns or fixture factories that provide sensible defaults and allow per-test overrides. This reduces test maintenance cost when the domain model changes — update the builder once instead of 200 test files. // Builder pattern for test data
const defaultOrder = OrderBuilder.create()
  .withStatus('pending')
  .withItems([{ productId: 'p1', quantity: 1, price: 29.99 }])
  .build();

// Override only what matters for this test
const cancelledOrder = OrderBuilder.create()
  .withStatus('cancelled')
  .withCancellationReason('customer_request')
  .build();

Hexagonal Architecture — Ports and Adapters The hexagonal architecture (also called ports and adapters) places the application core at the center, defining ports (interfaces) that describe how the application interacts with the outside world. Adapters implement these ports for specific technologies. // === DOMAIN LAYER (innermost) ===
// Pure business entity — no framework dependencies
public class Account {
    private final AccountId id;
    private Money balance;
    private final List<Transaction> transactions;

    public Account(AccountId id, Money initialBalance) {
        this.id = id;
        this.balance = initialBalance;
        this.transactions = new ArrayList<>();
    }

    public void withdraw(Money amount) {
        if (amount.isGreaterThan(balance)) {
            throw new InsufficientFundsException(id, amount, balance);
        }
        balance = balance.subtract(amount);
        transactions.add(Transaction.withdrawal(amount, LocalDateTime.now()));
    }

    public void deposit(Money amount) {
        if (amount.isNegativeOrZero()) {
            throw new InvalidAmountException(amount);
        }
        balance = balance.add(amount);
        transactions.add(Transaction.deposit(amount, LocalDateTime.now()));
    }

    public Money getBalance() { return balance; }
    public AccountId getId() { return id; }
}

// === PORTS (interfaces defined by the application core) ===

// Driven port — the application needs this to persist data
public interface AccountRepository {
    Optional<Account> findById(AccountId id);
    void save(Account account);
}

// Driven port — the application needs this to send notifications
public interface TransferNotifier {
    void notifyTransferCompleted(AccountId from, AccountId to, Money amount);
    void notifyTransferFailed(AccountId from, AccountId to, String reason);
}

// Driving port — external actors use this to trigger application behavior
public interface TransferUseCase {
    TransferResult execute(TransferCommand command);
} // === USE CASE LAYER ===
// Orchestrates domain entities to fulfill a specific user intention
public class TransferMoneyUseCase implements TransferUseCase {
    private final AccountRepository accountRepository;
    private final TransferNotifier notifier;
    private final TransactionLogger transactionLogger;

    public TransferMoneyUseCase(
            AccountRepository accountRepository,
            TransferNotifier notifier,
            TransactionLogger transactionLogger) {
        this.accountRepository = accountRepository;
        this.notifier = notifier;
        this.transactionLogger = transactionLogger;
    }

    @Override
    public TransferResult execute(TransferCommand command) {
        Account source = accountRepository.findById(command.sourceAccountId())
            .orElseThrow(() -> new AccountNotFoundException(command.sourceAccountId()));
        Account target = accountRepository.findById(command.targetAccountId())
            .orElseThrow(() -> new AccountNotFoundException(command.targetAccountId()));

        try {
            source.withdraw(command.amount());
            target.deposit(command.amount());

            accountRepository.save(source);
            accountRepository.save(target);

            transactionLogger.log(command.sourceAccountId(), command.targetAccountId(), command.amount());
            notifier.notifyTransferCompleted(command.sourceAccountId(), command.targetAccountId(), command.amount());

            return TransferResult.success(source.getBalance());
        } catch (InsufficientFundsException e) {
            notifier.notifyTransferFailed(command.sourceAccountId(), command.targetAccountId(), e.getMessage());
            return TransferResult.failure(e.getMessage());
        }
    }
}

// Command object — immutable input to the use case
public record TransferCommand(
    AccountId sourceAccountId,
    AccountId targetAccountId,
    Money amount
) {
    public TransferCommand {
        Objects.requireNonNull(sourceAccountId, "Source account ID required");
        Objects.requireNonNull(targetAccountId, "Target account ID required");
        Objects.requireNonNull(amount, "Amount required");
        if (sourceAccountId.equals(targetAccountId)) {
            throw new IllegalArgumentException("Cannot transfer to same account");
        }
    }
}

Adapter Implementations Adapters sit in the outermost layer and implement the ports defined by the application core. They translate between the application's language and the external system's language. // === ADAPTER LAYER (outermost) ===

// Driven adapter — implements the repository port using JPA
@Repository
public class JpaAccountRepository implements AccountRepository {
    private final JpaAccountEntityRepository jpaRepository;
    private final AccountMapper mapper;

    public JpaAccountRepository(JpaAccountEntityRepository jpaRepository, AccountMapper mapper) {
        this.jpaRepository = jpaRepository;
        this.mapper = mapper;
    }

    @Override
    public Optional<Account> findById(AccountId id) {
        return jpaRepository.findById(id.value())
            .map(mapper::toDomain);
    }

    @Override
    @Transactional
    public void save(Account account) {
        AccountEntity entity = mapper.toEntity(account);
        jpaRepository.save(entity);
    }
}

// Driven adapter — implements notification port using email
public class EmailTransferNotifier implements TransferNotifier {
    private final EmailClient emailClient;
    private final UserRepository userRepository;

    public EmailTransferNotifier(EmailClient emailClient, UserRepository userRepository) {
        this.emailClient = emailClient;
        this.userRepository = userRepository;
    }

    @Override
    public void notifyTransferCompleted(AccountId from, AccountId to, Money amount) {
        User sender = userRepository.findByAccountId(from);
        emailClient.send(
            sender.getEmail(),
            "Transfer Completed",
            String.format("Your transfer of %s has been completed.", amount)
        );
    }

    @Override
    public void notifyTransferFailed(AccountId from, AccountId to, String reason) {
        User sender = userRepository.findByAccountId(from);
        emailClient.send(sender.getEmail(), "Transfer Failed", reason);
    }
}

// Driving adapter — REST controller that invokes the use case
@RestController
@RequestMapping("/api/transfers")
public class TransferController {
    private final TransferUseCase transferUseCase;

    public TransferController(TransferUseCase transferUseCase) {
        this.transferUseCase = transferUseCase;
    }

    @PostMapping
    public ResponseEntity<TransferResponse> transfer(@RequestBody @Valid TransferRequest request) {
        TransferCommand command = new TransferCommand(
            new AccountId(request.sourceAccountId()),
            new AccountId(request.targetAccountId()),
            Money.of(request.amount(), request.currency())
        );

        TransferResult result = transferUseCase.execute(command);

        if (result.isSuccess()) {
            return ResponseEntity.ok(new TransferResponse(result.remainingBalance().toString()));
        }
        return ResponseEntity.badRequest()
            .body(new TransferResponse(result.errorMessage()));
    }
}

Clean Architecture in TypeScript with Dependency Rule // === DOMAIN LAYER ===
// Pure domain entity — no external dependencies
export class Order {
  private readonly items: OrderItem[] = [];
  private status: OrderStatus = OrderStatus.DRAFT;

  constructor(
    public readonly id: string,
    public readonly customerId: string,
    private readonly pricingPolicy: PricingPolicy
  ) {}

  addItem(product: Product, quantity: number): void {
    if (this.status !== OrderStatus.DRAFT) {
      throw new OrderNotModifiableError(this.id, this.status);
    }
    if (quantity <= 0) {
      throw new InvalidQuantityError(quantity);
    }
    const price = this.pricingPolicy.calculatePrice(product, quantity);
    this.items.push(new OrderItem(product.id, quantity, price));
  }

  submit(): void {
    if (this.items.length === 0) {
      throw new EmptyOrderError(this.id);
    }
    this.status = OrderStatus.SUBMITTED;
  }

  getTotal(): Money {
    return this.items.reduce(
      (sum, item) => sum.add(item.totalPrice),
      Money.zero('USD')
    );
  }
}

// === PORT (interface defined by application core) ===
export interface OrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
  findByCustomer(customerId: string): Promise<Order[]>;
}

export interface InventoryService {
  reserve(productId: string, quantity: number): Promise<ReservationResult>;
  release(reservationId: string): Promise<void>;
}

// === USE CASE ===
export class SubmitOrderUseCase {
  constructor(
    private readonly orderRepository: OrderRepository,
    private readonly inventoryService: InventoryService,
    private readonly eventPublisher: DomainEventPublisher
  ) {}

  async execute(command: SubmitOrderCommand): Promise<SubmitOrderResult> {
    const order = await this.orderRepository.findById(command.orderId);
    if (!order) {
      return SubmitOrderResult.notFound(command.orderId);
    }

    // Reserve inventory for all items
    const reservations: string[] = [];
    try {
      for (const item of order.getItems()) {
        const result = await this.inventoryService.reserve(item.productId, item.quantity);
        if (!result.success) {
          // Rollback previous reservations
          await Promise.all(reservations.map(r => this.inventoryService.release(r)));
          return SubmitOrderResult.insufficientInventory(item.productId);
        }
        reservations.push(result.reservationId);
      }

      order.submit();
      await this.orderRepository.save(order);
      await this.eventPublisher.publish(new OrderSubmittedEvent(order.id, order.getTotal()));

      return SubmitOrderResult.success(order.id);
    } catch (error) {
      await Promise.all(reservations.map(r => this.inventoryService.release(r)));
      throw error;
    }
  }
}

Single Responsibility Principle The SRP states that a class should have only one reason to change. This means each class should encapsulate a single concern or responsibility. When a class handles multiple concerns, changes to one concern risk breaking the other. Violation — a class handling both business logic and persistence: // BAD: This class has two reasons to change:
// 1. Business rules for order validation change
// 2. Database schema or persistence mechanism changes
public class OrderService {
    private final DataSource dataSource;

    public OrderService(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public Order createOrder(OrderRequest request) {
        // Business logic
        if (request.getItems().isEmpty()) {
            throw new IllegalArgumentException("Order must have at least one item");
        }
        BigDecimal total = request.getItems().stream()
            .map(item -> item.getPrice().multiply(BigDecimal.valueOf(item.getQuantity())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        if (total.compareTo(BigDecimal.valueOf(10000)) > 0) {
            throw new OrderLimitExceededException("Order exceeds maximum limit");
        }

        Order order = new Order(UUID.randomUUID(), request.getItems(), total, OrderStatus.PENDING);

        // Persistence logic mixed in
        try (Connection conn = dataSource.getConnection()) {
            PreparedStatement stmt = conn.prepareStatement(
                "INSERT INTO orders (id, total, status) VALUES (?, ?, ?)"
            );
            stmt.setString(1, order.getId().toString());
            stmt.setBigDecimal(2, order.getTotal());
            stmt.setString(3, order.getStatus().name());
            stmt.executeUpdate();
        } catch (SQLException e) {
            throw new RuntimeException("Failed to persist order", e);
        }

        return order;
    }
} Corrected — responsibilities separated: // GOOD: Business logic isolated in domain service
public class OrderService {
    private final OrderRepository orderRepository;
    private final OrderValidator validator;

    public OrderService(OrderRepository orderRepository, OrderValidator validator) {
        this.orderRepository = orderRepository;
        this.validator = validator;
    }

    public Order createOrder(OrderRequest request) {
        validator.validate(request);
        BigDecimal total = calculateTotal(request.getItems());
        Order order = new Order(UUID.randomUUID(), request.getItems(), total, OrderStatus.PENDING);
        orderRepository.save(order);
        return order;
    }

    private BigDecimal calculateTotal(List<OrderItem> items) {
        return items.stream()
            .map(item -> item.getPrice().multiply(BigDecimal.valueOf(item.getQuantity())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

// Persistence concern isolated
public class JdbcOrderRepository implements OrderRepository {
    private final DataSource dataSource;

    public JdbcOrderRepository(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    @Override
    public void save(Order order) {
        try (Connection conn = dataSource.getConnection()) {
            PreparedStatement stmt = conn.prepareStatement(
                "INSERT INTO orders (id, total, status) VALUES (?, ?, ?)"
            );
            stmt.setString(1, order.getId().toString());
            stmt.setBigDecimal(2, order.getTotal());
            stmt.setString(3, order.getStatus().name());
            stmt.executeUpdate();
        } catch (SQLException e) {
            throw new PersistenceException("Failed to persist order", e);
        }
    }
}

Open/Closed Principle The OCP states that you should be able to extend behavior without modifying existing code. This is typically achieved through polymorphism, strategy patterns, or plugin architectures. Violation — adding new payment types requires modifying existing code: // BAD: Every new payment method requires modifying this function
function processPayment(payment: Payment): PaymentResult {
  switch (payment.type) {
    case 'credit_card':
      return chargeCreditCard(payment.cardNumber, payment.amount);
    case 'paypal':
      return chargePayPal(payment.email, payment.amount);
    case 'bank_transfer':
      return initiateBankTransfer(payment.accountNumber, payment.amount);
    // Adding 'crypto' requires modifying this function
    default:
      throw new Error(`Unsupported payment type: ${payment.type}`);
  }
} Corrected — new payment types extend without modification: // GOOD: Open for extension via new implementations, closed for modification
interface PaymentProcessor {
  supports(payment: Payment): boolean;
  process(payment: Payment): PaymentResult;
}

class CreditCardProcessor implements PaymentProcessor {
  supports(payment: Payment): boolean {
    return payment.type === 'credit_card';
  }

  process(payment: Payment): PaymentResult {
    return this.chargeCreditCard(payment.cardNumber!, payment.amount);
  }

  private chargeCreditCard(cardNumber: string, amount: number): PaymentResult {
    // Credit card specific logic
    return { success: true, transactionId: generateId() };
  }
}

class PayPalProcessor implements PaymentProcessor {
  supports(payment: Payment): boolean {
    return payment.type === 'paypal';
  }

  process(payment: Payment): PaymentResult {
    return this.chargePayPal(payment.email!, payment.amount);
  }

  private chargePayPal(email: string, amount: number): PaymentResult {
    // PayPal specific logic
    return { success: true, transactionId: generateId() };
  }
}

// Adding crypto requires ZERO changes to existing code
class CryptoProcessor implements PaymentProcessor {
  supports(payment: Payment): boolean {
    return payment.type === 'crypto';
  }

  process(payment: Payment): PaymentResult {
    return this.processBlockchainPayment(payment.walletAddress!, payment.amount);
  }

  private processBlockchainPayment(wallet: string, amount: number): PaymentResult {
    return { success: true, transactionId: generateId() };
  }
}

// Registry is closed for modification but open for extension via registration
class PaymentService {
  private processors: PaymentProcessor[] = [];

  register(processor: PaymentProcessor): void {
    this.processors.push(processor);
  }

  processPayment(payment: Payment): PaymentResult {
    const processor = this.processors.find(p => p.supports(payment));
    if (!processor) {
      throw new Error(`No processor registered for payment type: ${payment.type}`);
    }
    return processor.process(payment);
  }
}

Liskov Substitution Principle LSP requires that objects of a superclass should be replaceable with objects of a subclass without breaking the application. This goes beyond simple type compatibility — it requires behavioral compatibility including preconditions, postconditions, and invariants. // BAD: Square violates LSP when substituted for Rectangle
// because setWidth/setHeight have unexpected coupled behavior
public class Rectangle {
    protected int width;
    protected int height;

    public void setWidth(int width) { this.width = width; }
    public void setHeight(int height) { this.height = height; }
    public int getArea() { return width * height; }
}

public class Square extends Rectangle {
    @Override
    public void setWidth(int width) {
        this.width = width;
        this.height = width;  // Violates expected behavior of setWidth
    }

    @Override
    public void setHeight(int height) {
        this.width = height;  // Violates expected behavior of setHeight
        this.height = height;
    }
}

// Client code breaks with Square:
void resize(Rectangle rect) {
    rect.setWidth(5);
    rect.setHeight(10);
    assert rect.getArea() == 50;  // FAILS with Square (returns 100)
} // GOOD: Use composition and separate interfaces
public interface Shape {
    int getArea();
}

public class Rectangle implements Shape {
    private final int width;
    private final int height;

    public Rectangle(int width, int height) {
        this.width = width;
        this.height = height;
    }

    @Override
    public int getArea() { return width * height; }
}

public class Square implements Shape {
    private final int side;

    public Square(int side) {
        this.side = side;
    }

    @Override
    public int getArea() { return side * side; }
}

Interface Segregation Principle ISP states that no client should be forced to depend on methods it does not use. Fat interfaces create unnecessary coupling and make implementations harder to maintain. // BAD: Fat interface forces implementations to handle irrelevant methods
interface Worker {
  work(): void;
  eat(): void;
  sleep(): void;
  attendMeeting(): void;
  writeReport(): void;
}

// A robot worker is forced to implement eat() and sleep()
class RobotWorker implements Worker {
  work(): void { /* productive work */ }
  eat(): void { throw new Error('Robots do not eat'); }  // Forced stub
  sleep(): void { throw new Error('Robots do not sleep'); }  // Forced stub
  attendMeeting(): void { /* join video call */ }
  writeReport(): void { /* generate report */ }
} // GOOD: Segregated interfaces — clients depend only on what they need
interface Workable {
  work(): void;
}

interface Feedable {
  eat(): void;
}

interface Restable {
  sleep(): void;
}

interface Communicable {
  attendMeeting(): void;
  writeReport(): void;
}

class HumanWorker implements Workable, Feedable, Restable, Communicable {
  work(): void { /* productive work */ }
  eat(): void { /* lunch break */ }
  sleep(): void { /* rest period */ }
  attendMeeting(): void { /* join standup */ }
  writeReport(): void { /* write status update */ }
}

class RobotWorker implements Workable, Communicable {
  work(): void { /* productive work */ }
  attendMeeting(): void { /* join monitoring dashboard */ }
  writeReport(): void { /* generate automated report */ }
}

// Functions depend only on the interface they need
function assignTask(worker: Workable): void {
  worker.work();
}

function scheduleLunch(worker: Feedable): void {
  worker.eat();
}

Dependency Inversion Principle DIP states that high-level policy should not depend on low-level detail. Both should depend on abstractions. This enables swapping implementations, testing in isolation, and evolving systems without cascading changes. // BAD: High-level NotificationService depends directly on low-level EmailSender
public class NotificationService {
    private final SmtpEmailSender emailSender;  // Concrete dependency

    public NotificationService() {
        this.emailSender = new SmtpEmailSender("smtp.company.com", 587);  // Hardcoded
    }

    public void notifyUser(User user, String message) {
        emailSender.send(user.getEmail(), "Notification", message);
    }
} // GOOD: Both high-level and low-level depend on abstraction
public interface NotificationChannel {
    void send(User user, String message);
    boolean supports(NotificationType type);
}

public class EmailNotificationChannel implements NotificationChannel {
    private final EmailClient emailClient;

    public EmailNotificationChannel(EmailClient emailClient) {
        this.emailClient = emailClient;
    }

    @Override
    public void send(User user, String message) {
        emailClient.send(user.getEmail(), "Notification", message);
    }

    @Override
    public boolean supports(NotificationType type) {
        return type == NotificationType.EMAIL;
    }
}

public class SlackNotificationChannel implements NotificationChannel {
    private final SlackClient slackClient;

    public SlackNotificationChannel(SlackClient slackClient) {
        this.slackClient = slackClient;
    }

    @Override
    public void send(User user, String message) {
        slackClient.postMessage(user.getSlackId(), message);
    }

    @Override
    public boolean supports(NotificationType type) {
        return type == NotificationType.SLACK;
    }
}

// High-level service depends on abstraction, not concrete implementations
public class NotificationService {
    private final List<NotificationChannel> channels;

    public NotificationService(List<NotificationChannel> channels) {
        this.channels = channels;
    }

    public void notifyUser(User user, String message, NotificationType preferredType) {
        NotificationChannel channel = channels.stream()
            .filter(c -> c.supports(preferredType))
            .findFirst()
            .orElseThrow(() -> new UnsupportedNotificationException(preferredType));
        channel.send(user, message);
    }
}

Review Checklist Implementation A structured checklist ensures consistent review quality across team members and prevents common oversights. // review-checklist.ts — Automated checklist generation based on PR content
interface ReviewChecklist {
