      },
    ],
  },
  {
    category: 'Design',
    items: [
      {
        description: 'Single responsibility — each class/function has one job',
        severity: 'important',
        automated: false,
        applicable: () => true,
      },
      {
        description: 'No unnecessary coupling between modules',
        severity: 'important',
